/* 由 tools/build_lib.js 从 tools/lib_notes/zhuyan/*.json 组装，请勿手改。 */
LIT.addLibNotes({"zhuyan_sanguofahui":{"intro":"西晋崩溃后，大批流亡士民投奔辽西的慕容廆，引起平州刺史崔毖的忌恨。崔毖暗中联络高句丽、宇文部、段部三方合攻慕容廆。这一段写慕容廆怎样先散其盟、再以奇兵击溃最强的宇文部，是慕容部从部落首领走向辽东霸主的关键一战。《晋书》只说“太兴初”，一般系于东晋太兴二年（319）。","focus":["慕容廆的判断建立在对联盟结构的分析上：“既无统一，莫相归伏”——三方各怀利益、没有统一指挥。所以他不急于决战，而是“靖以待之”，等对方互相猜疑。这是以静制动、先谋后战的典型。","离间手段极简：只给宇文部送去牛酒，再当众扬言“崔毖昨有使至”。高句丽和段部立刻怀疑宇文与慕容私下勾结，引兵而去。可见临时联盟最脆弱的不是兵力，而是互信。","决战是正兵加奇兵：慕容皝率锐士正面推进，慕容翰领精骑从旁直冲敌营纵火，慕容廆方阵继进。宇文悉独官“自恃其众，不设备”，一触即溃。战后把缴获的玉玺送往建邺，表明慕容廆名义上仍奉东晋，借晋室旗号经营辽东。"],"notes":[["崔毖","西晋平州刺史、东夷校尉，这次联兵的幕后策动者"],["乌合","像乌鸦一样临时聚集，喻无组织"],["韩魏之谋","典出春秋末智伯攻赵，韩、魏临阵倒戈；喻盟友暗中背叛"],["棘城","慕容部当时的都城（大棘城）"],["悉独官","宇文部首领宇文悉独官"],["推锋","领兵冲锋在前"],["奇兵","出其不意、从侧翼突击的部队"],["玉玺三纽","三方皇帝印玺；纽本指印鼻，这里作量词"],["建邺","东晋都城，即建康，今南京"],["首服","低头认罪"]],"think":["慕容廆为什么不趁三国“初合”时速战？这种“等对方先乱”的打法，在什么条件下会失效？","他判断联军锋芒正盛却“莫相归伏”：速战会逼联军抱团，拖延反而让猜疑发酵。失效的条件是：联军有统一指挥或共同的生死利益；自己的城守撑不到对方生变；或者离间被识破。棘城之战能成，是因为三方本就各打算盘，宇文部又自恃兵多而轻敌。"],"quiz":[["慕容廆使高句丽、段部退兵，主要靠什么？",["只犒劳宇文部并扬言崔毖有使者到来，使二国生疑","派精骑分别击败两国","割地求和"],"送牛酒给宇文、当众说崔毖的使者到了，让另两家怀疑宇文与慕容私通，于是撤兵。"],["击溃宇文悉独官时，“翰领精骑为奇兵”的作用是？",["从侧面直冲敌营纵火，打乱敌阵","切断敌军退路","护送玉玺南下"],"慕容翰从旁直冲敌营纵火，宇文军震扰溃败；正面由慕容皝推锋、慕容廆方阵继进。"],["战后把缴获的玉玺送往建邺，说明什么？",["慕容廆名义上仍尊奉东晋","慕容廆准备称帝","玉玺毫无价值"],"送往东晋都城，表示奉晋正朔、借晋室名义经营辽东；这和后来慕容儁称帝不同。"]],"cards":[["三国伐廆的“三国”是哪三方？背后是谁？","高句丽、宇文部、段部；平州刺史崔毖暗中联络。"],["慕容廆破联军分哪两步？","先犒宇文以离间，使高句丽、段部退兵；再以皝正面、翰奇兵大破宇文悉独官。"]],"line":["既无统一，莫相归伏","评估一个临时拼起来的竞争联盟时可以说：既无统一，莫相归伏——先别急着正面硬碰，看它自己会不会散。"],"tags":["前燕","慕容廆","谋略"]},"zhuyan_xirong":{"intro":"《晋书·慕容廆载记》开篇：先交代慕容部的族源、迁徙和得名，再写少年慕容廆被名士张华赏识、被国人迎立为首领。这是读诸燕史的起点：既要看史官怎样“编”一个北族的来历，也要看慕容部从莫护跋到涉归怎样一步步靠近中原。","focus":["族源写法是晋代史家的惯例：“其先有熊氏之苗裔”把鲜卑慕容追到黄帝，“邑于紫蒙之野，号曰东胡”再接上东胡。这一层只能当作传说层。真正可以追着读的世系从“曾祖莫护跋，魏初率其诸部入居辽西，从宣帝伐公孙氏有功”才开始，“宣帝”即晋追尊的司马懿。","“慕容”二字有两说，史官并列、不裁断：一说莫护跋喜爱燕代流行的步摇冠，“乃敛发袭冠，诸部因呼之为步摇，其后音讹，遂为慕容”；另一说是汉式雅解，“慕二仪之德，继三光之容”。前者是语音演变，后者是文人附会，读者要有自己的判断。","继承方式值得注意：涉归死后，“其弟耐篡位，将谋杀廆”，廆只能“亡潜以避祸”，是“后国人杀耐，迎廆立之”。可见此时部落首领的位子靠的是“国人”认可，不是父死子继的定制。张华赠“簪帻”、说他将是“命世之器”，则是中原名士给他的第一张政治名片。"],"notes":[["东胡","先秦以来对东北游牧族群的统称，史书把鲜卑追溯到这一支"],["控弦之士","能开弓的战士，指部落的兵员规模"],["鲜卑山","鲜卑部族退保之处，史书说“鲜卑”之名由此而来"],["莫护跋","慕容廆的曾祖，魏初率部入居辽西，受封率义王"],["步摇冠","一种缀有摇动金饰的冠，燕代之地流行"],["音讹","读音辗转变错；这里指“步摇”变成“慕容”"],["涉归","慕容廆之父，因保全柳城之功进拜鲜卑单于"],["渐慕诸夏之风","逐渐仰慕中原的风气，史官对涉归时代的概括"],["命世之器","一代难得的大才"],["簪帻","束发的簪与包头的巾，汉式冠服；赠簪帻有收为知己之意"],["国人","这里指部落里有话语权的本族人"]],"think":["为什么《晋书》既写“有熊氏之苗裔”，又写“音讹”“慕二仪”两说，而不替读者选一个？","史官同时记下传说与异说，是在处理材料而不是编故事：族源出自边外，只能依据旧说；得名的两说一个朴素、一个雅致，史官无从判断，就并存。读史时，凡是涉及族源和地名来由的，都应当把“可核对的世系”与“传说层”分开，前者可以引用，后者要标注“据载”。"],"quiz":[["按本段，“慕容”之名的第一种来历是什么？",["莫护跋喜爱步摇冠，诸部称他为“步摇”，后来读音讹变成慕容","莫护跋被魏帝赐姓慕容","鲜卑山中的一座城叫慕容城"],"原文先说“诸部因呼之为步摇，其后音讹，遂为慕容”，再并列“或云慕二仪之德”。赐姓与城名都不见于本段。"],["涉归死后，慕容廆最终得到首领之位，主要靠什么？",["国人杀掉篡位的耐，把他迎立起来","晋武帝下诏册立","涉归生前立了遗嘱"],"“后国人杀耐，迎廆立之”。可见当时首领的合法性来自本部族人的拥戴。"],["张华对少年慕容廆说“君至长必为命世之器”，同时赠他簪帻，这一举动说明了什么？",["中原名士认可他，也是他被汉人社会接纳的开端","张华要将他收为部下","晋廷借此任命他为官"],"张华是“有知人之鉴”的名士，评价加上赠送汉式冠服，既是赏识也是象征接纳。文中并没有任官的记载。"]],"cards":[["本段里慕容部可追的世系从谁开始？","曾祖莫护跋，魏初率诸部入居辽西，从宣帝伐公孙氏，拜率义王。"],["“慕容”得名的两说？","一说“步摇”音讹；一说“慕二仪之德，继三光之容”。"],["耐篡位后，廆怎样成为首领？","先逃亡避祸，后来国人杀耐，迎廆立之。"]],"line":["君至长必为命世之器，匡难济时者也","给团队里一位年轻人写推荐评语时可以引：君至长必为命世之器——先把评价说在前头，再看他怎样做到。"],"tags":["慕容部","世系","族源"]},"zhuyan_yuwen_fuyu":{"intro":"这一段讲慕容廆早年的路线选择：先为父仇讨宇文、灭扶余，同晋军在肥如交手大败，随后他在部众面前一转，“不和以害吾百姓邪”，遣使降晋。读它要抓的是：慕容部为什么要把“事晋”当作长期国策，以及他在礼仪上怎样守住尊严。","focus":["先打后和：廆“表请讨”宇文被“武帝弗许”，“怒，入寇辽西，杀略甚众”，幽州诸军出兵，“战于肥如，廆众大败”，后来又“每岁不绝”地掠昌黎。史书不隐他的败仗与寇掠。转折全在一句“吾先公以来世奉中国，且华裔理殊，强弱固别，岂能与晋竞乎”：他用三个理由——世奉中国、华夷有别、强弱悬殊——说服部众，核心是“害吾百姓”。","改服一节写礼数对等：“巾衣诣门，抗士大夫之礼”是对东夷校尉何龛表示敬意；龛“严兵引见”，廆就“改服戎衣而入”，说“主人不以礼，宾复何为哉”。他既不拒绝汉礼，也不接受被人当作蛮夷设防，结果是“龛闻而惭之，弥加敬惮”。","对不同对象用不同手段：对晋是“和”，对宇文、段部这样“惧有吞并之计”的邻部是“卑辞厚币以抚之”，对扶余这类弱邻则“夷其国城，驱万余人而归”。一位首领要在大国、同等对手和弱邻之间分层处置，这是慕容廆后来能立住脚的实际办法。"],"notes":[["肥如","地名，在今河北东北部，廆与幽州晋军交战处"],["昌黎","晋代郡名，慕容部所在的辽西一带"],["扶余","东北古国，被廆攻破后又被晋官扶立复国"],["夷其国城","把对方的都城夷平"],["东夷校尉","晋朝设在东北、统辖东夷诸部的官职，何龛当时在任"],["鲜卑都督","晋朝授给廆的名号，统领鲜卑诸部事务"],["华裔理殊","华夏与四夷的情理不同，廆借此说明不应与晋对抗"],["巾衣诣门","以汉式巾衣到门拜见"],["抗士大夫之礼","用士大夫之间对等的礼节，而非部落首领见官长的礼节"],["戎衣","军服，这里指鲜卑武装"],["卑辞厚币","话说得谦卑、礼送得丰厚"],["督护","军事官名，贾沈当时奉命迎立依虑之子"]],"think":["廆说“何为不和以害吾百姓邪”，这是真心还是权术？怎样判断？","两者并存，要看后续行为：他之后几十年一直通使江东、受晋官爵，说明“和”是长期国策而非一时策略；同时他又“卑辞厚币”稳住宇文、段部，说明他会把“和”当作争取时间的工具。判断时看他在实力增长之后是否仍守这条线——后面“遣使劝进”“固辞公封”都能印证。"],"quiz":[["廆最初请求讨宇文、攻掠昌黎，原因是？",["涉归与宇文鲜卑有旧怨，他要“修先君之怨”","晋朝下令他出兵","宇文部先攻破了棘城"],"原文“初，涉归有憾于宇文鲜卑，廆将修先君之怨，表请讨之”，武帝不许，他便自己入寇。"],["廆“改服戎衣而入”，是因为何龛怎样对他？",["严兵引见，对他不以礼","下令缴他的兵器","要求他跪拜"],"“龛严兵引见”，所以廆回应“主人不以礼，宾复何为哉”。他的意思是：你用兵礼待我，我就以武装相见。"],["本段中廆面对宇文、段部的威胁用的是哪种办法？",["卑辞厚币以抚之","联合高句丽共击","举族迁走"],"“时东胡宇文鲜卑段部以廆威德日广，惧有吞并之计，因为寇掠，往来不绝。廆卑辞厚币以抚之。”"]],"cards":[["廆为何决定降晋？","先公世奉中国，华夷理殊、强弱有别，不值得为争战伤害百姓。"],["“主人不以礼，宾复何为哉”什么意思？","对方不按礼接待，我也不必再守宾礼：改穿戎服回应。"]],"line":["主人不以礼，宾复何为哉","对方把场面搞得不对等时，可以用这句话回应：主人不以礼，宾复何为哉——我按你给的规格还礼。"],"tags":["慕容廆","前燕","外交"]},"zhuyan_lianjin":{"intro":"永嘉初年辽东大乱，慕容廆自称鲜卑大单于。本段写他的儿子慕容翰提出“勤王”之议，廆随即出兵讨平素连、木津二部，徙其众于棘城、立辽东郡。这是慕容部把“打晋朝旗号”和“扩张实力”合在一起的早期样板。","focus":["翰的论证有三层，层层递进：先讲事实，“竖子外以庞本为名，内实幸而为寇”——说素连、木津假借为李臻报仇，实际是趁乱劫掠；再讲道义，“求诸侯莫如勤王，自古有为之君靡不杖此以成事业者也”；最后讲利益，“忠义彰于本朝，私利归于我国”。把私利装进道义的话，是他的聪明处，也是慕容部长期的政治手法。","晋官的无能被写成论据：“太守袁谦频战失利，校尉封释惧而请和”，而“封使君以诛本请和，而毒害滋深”，所以翰说“王师覆败，苍生屠脍”。这给慕容部留出了介入的空间：王师不能保境，就由慕容来“救倒悬之命”。","结果写得很干脆：“二部悉降，徙之棘城，立辽东郡而归。”降部被迁到自己的都城，又立“辽东郡”安置——在晋朝的行政名义下处理自己新得的人口与土地。“流亡归附者日月相继”一句，则说明慕容部此时已成为辽东乱局里的安全岛。"],"notes":[["大单于","匈奴、鲜卑首领的称号，廆自称鲜卑大单于"],["附塞鲜卑","依附在边塞之内的鲜卑部落"],["跋扈","强横不受约束"],["勤王","为王室出力、救援朝廷"],["九伐之威","古代讨伐有罪的九种征伐之法，借指堂堂正正的出师"],["倒悬之命","像被倒挂着一样危急的百姓生命"],["鸿渐之始","好比鸿雁逐步飞升的开端，指发迹的第一步"],["封使君","称东夷校尉封释"],["兴复辽邦","恢复辽东的旧局面"],["流亡归附者","从各地逃难、投奔慕容部的人"],["徙之棘城","把降部迁到棘城"]],"think":["翰说“忠义彰于本朝，私利归于我国”，把“公”与“私”说得如此直白。你认为这种直白是破绽还是高明？","在内部议事里直白反而高明：廆是要听取利害，直白能让决策者看清收益；对外则用“勤王”作旗号。这段话没有被史官删改，也说明在慕容部内部，“借义取利”是被公开接受的路径。判断时要区分内外场合：对内讲利，对外讲义。"],"quiz":[["素连、木津起事的名义是什么？",["为被杀的东夷校尉李臻报仇","为慕容廆复仇","反抗高句丽"],"“附塞鲜卑素连、木津等托为臻报仇，实欲因而为乱”。翰指出这只是借口。"],["慕容翰提出出兵的最大理由是？",["勤王，既能彰忠义又能为自己得利","朝廷已下诏命令讨伐","宇文部要求联兵"],"“求诸侯莫如勤王”，并说“忠义彰于本朝，私利归于我国”。"],["二部投降后，廆怎样处置？",["迁到棘城，并立辽东郡","全部杀死","放回原地"],"“二部悉降，徙之棘城，立辽东郡而归。”"]],"cards":[["翰的出兵论证三层？","事实（庞本为名实为寇）→ 道义（勤王）→ 利益（私利归我国）。"],["廆平连、津后做了什么？","徙二部到棘城，立辽东郡。"]],"line":["求诸侯莫如勤王","写项目申报材料时，可以化用这句：求诸侯莫如勤王——先找能借的名分，再谈自己的收益。"],"tags":["慕容廆","前燕","谋略"]},"zhuyan_quanjin":{"intro":"西晋覆亡后，北方诸势力纷纷向慕容廆送官。本段写他先后辞去王浚所授之官和元帝所授的公爵，征虏将军鲁昌为他分析：诸部不服，是因为“官非王命”，应当通使江东、劝进元帝。廆遂遣长史王济浮海劝进。慕容氏“尊晋而自强”的路线由此确定。","focus":["辞官有章法：怀帝被俘后，王浚“承制”授廆大单于等官，“廆不受”；元帝“承制”拜他为龙骧将军、大单于、昌黎公，廆“让而不受”；元帝即位后重申前命，他又“固辞公封”。拒绝的都是来源不正或爵位过高的封号。愍帝一条，本段只写“遣使拜廆镇军将军、昌黎辽东二国公”，没说受或不受，读时不要替史官补。","鲁昌的话抓住了关键：“诸部犹怙众称兵，未遵道化者，盖以官非王命，又自以为强”。慕容部想让别的鲜卑部服从，需要一个“王命”的名义，通使“琅邪”（元帝本封琅邪王）、“劝承大统”，再“敷宣帝命，以伐有罪，谁敢不从”。名分被当作号召力的来源来经营。","“浮海”两字也有分量：两京倾覆、陆路被石勒与王浚的地盘阻隔，王济只能走海路到江东。这条海上通道，后来成为慕容部同东晋往来的主线，也说明辽东当时与中原的联系已经相当依赖海运。"],"notes":[["蒙尘","皇帝被迫离开宫廷、流亡在外，这里指怀帝被俘到平阳"],["承制","没有皇帝诏命时，权臣代为行使任命权"],["前锋大都督","军事统帅类的官号"],["昌黎公","以昌黎郡为封地的公爵"],["让而不受","谦让而不接受"],["两京倾没","洛阳、长安两京陷落"],["琅邪","指琅邪王司马睿，即后来的东晋元帝"],["劝承大统","劝他继承皇位"],["敷宣帝命","宣布皇帝的命令"],["浮海","走海路"],["固辞","坚决推辞"]],"think":["鲁昌的建议是“通使琅邪”。为什么不就接受王浚、愍帝已经给的名号，而要再去江东找一个新的？","王浚、愍帝都已不能代表“王命”：王浚是地方权臣，愍帝所在的长安岌岌可危。慕容部要用名分号令诸部，需要一个能长期存在的正统；东晋虽远，却是当时汉人士大夫认可的朝廷。选正统要看谁的“承诺”未来仍有效，而不是谁离得近。"],"quiz":[["鲁昌认为诸部不肯服从廆，原因是什么？",["官号不是来自王命，而且诸部自恃强大","廆的兵力太弱","晋朝禁止他用兵"],"原文“盖以官非王命，又自以为强”。所以他提出通使琅邪、请其即位，再宣布帝命。"],["王浚“承制”授廆官职，廆的态度是？",["不接受","全盘接受","接受一半"],"“王浚承制以廆为散骑常侍……大单于，廆不受。”"],["遣王济浮海，直接目的是？",["向元帝劝进","购买战马","向江东求援兵"],"“乃遣其长史王济浮海劝进”。"]],"cards":[["“官非王命”的意思？","官号不出自皇帝的正式诏命，不足以号召各部。"],["廆对王浚所授官职的态度？","不受；对元帝初授让而不受，称帝后固辞公封。"]],"line":["官非王命，又自以为强","同事不服新任主管时，可以借这句分析：官非王命，又自以为强——先看名分来源，再看对方的底气。"],"tags":["慕容廆","前燕","名分"]},"zhuyan_peiyi":{"intro":"裴嶷是河东名门，辗转投奔慕容廆，在“诸流寓之士……并怀去就”的时刻率先定下名分，之后为廆献策破宇文、出使建邺。三段连读，可以看到汉人士大夫在慕容政权里承担的三种角色：稳定人心、出谋、对外说话。","focus":["“嶷首定名分，为群士启行”是关键句：当流亡士人看到廆“草创”，都在去留之间，裴嶷第一个把自己交给慕容氏，等于替众人做了决定。廆的反应是“以嶷为长史，委以军国之谋”——给出的不是虚衔，而是“军国”。","献策只用了四个短语：“军无号令，众无部陈，若简精兵乘其无备，则成擒耳”。他不去评论敌人兵多，只看指挥与阵列这两个组织指标，因此判断出兵多反而是弱点。与三国伐廆一段（悉独官“自恃其众，不设备”）互相印证。","出使一节最见分寸：朝廷“以廆僻在荒远，犹以边裔之豪处之”，嶷到后“盛言廆威略，又知四海英赋并为其用，举朝改观”；晋帝试探性地要留他，他说“今若留臣，必谓国家遗其僻陋，孤其丹心，使怀义懈怠”，把个人去留放到对辽东忠诚的信号上，帝“卿言是也”。廆随后说“裴长史名重中朝，而降屈于此，岂非天以授孤也”，点出中原名士在政治上的价值。"],"notes":[["流寓之士","流亡到异乡寄居的士人"],["草创","刚刚开创、基础未立"],["首定名分","第一个确定君臣身份"],["长史","幕府中的主要僚佐，掌管文书与军政事务"],["悉独官","宇文部首领"],["简精兵","挑选精锐士兵"],["献捷","向朝廷报告战胜的消息"],["边裔之豪","边远地区的豪强首领"],["丹心","忠诚之心"],["孤其丹心","让他的忠心落空、孤立无援"],["降屈","屈身降低身份"]],"think":["裴嶷为什么拒绝留在朝廷？只是忠诚吗？","忠诚是理由，但并非唯一：他是廆的长史，留京等于切断廆与朝廷之间最重要的信息渠道；朝廷“遗其僻陋”的印象一旦坐实，辽东诸将、流人的归心都会受影响。他的回答是在为整个集团保信号，也在保护自己在慕容政权里的位置。"],"quiz":[["“嶷首定名分，为群士启行”的含义是？",["他率先表态归附，给犹豫的士人带了头","他起草了官制","他第一个劝廆称王"],"“诸流寓之士见廆草创，并怀去就。嶷首定名分”，意思是他先定下了君臣名分，别人随之。"],["裴嶷评价悉独官的弱点是？",["军无号令、众无部阵","粮草不足","将领内讧"],"“军无号令，众无部陈”，所以建议“简精兵乘其无备”。"],["帝要留他，他怎样回绝？",["说留他会让国家显得遗弃辽东忠臣，使人懈怠","称自己年老多病","说廆会因此怪罪他"],"“今若留臣，必谓国家遗其僻陋，孤其丹心，使怀义懈怠。”"]],"cards":[["裴嶷对廆的三个角色？","稳定士人（首定名分）、出谋（破悉独官）、出使建邺。"],["廆评裴嶷“天以授孤”的意思？","名重中朝的人才愿意屈居辽东，是天赐。"]],"line":["裴长史名重中朝，而降屈于此，岂非天以授孤也","招到一位行业里有名的人时可以说：名重一时而降屈于此，岂非天以授孤也——但要想清楚怎样不辜负。"],"tags":["慕容廆","前燕","人才"]},"zhuyan_gaozhan":{"intro":"高瞻是渤海大族，永嘉乱后几次转投，最后被裹进慕容廆这一边，却始终称疾不出。廆亲自探病，说出一番著名的“夷夏”议论，高瞻仍不为所动，最终忧郁而死。这一段是理解前燕汉人士族复杂心态的好材料。","focus":["高瞻前后三次择主：先带数千家去幽州，因为“王彭祖先在幽蓟，据燕代之资，兵强国富，可以托也”；后来“以王浚政令无恒，乃依崔毖”；崔毖败，他“随众降于廆”。每一次都是“可以托”的现实判断，不见多少认同。这是乱世士族的真实逻辑：先保全宗族，再谈名分。","廆的话分两步：先点破“君之疾在此，不在余也”，直指他是心病；再说“匡复帝室……迎天子于吴会”，把自己放在勤王的阵营里；最后给出论据：“大禹出于西羌，文王生于东夷，但问志略何如耳，岂以殊俗不可降心乎！”——用圣王出身说明夷夏不是问题。论证很漂亮，但对象不接受。","结局值得留意：高瞻“仍辞疾笃”，廆“深不平之”，又加上“与宋该有隙，该阴劝廆除之”，他“弥不自安，遂以忧死”。《晋书》没有说廆杀了他，也没有说他被说服——他是被内外压力耗掉的。这与裴嶷的主动合作形成对照：汉人士族在慕容政权里并非铁板一块。"],"notes":[["尚书郎","尚书台的官员，负责起草文书、办理事务"],["寇庭","成为敌寇活动的场所"],["王彭祖","指王浚，当时坐镇幽州"],["政令无恒","政令没有稳定性、常常改变"],["称疾","借口生病"],["华夷之异","华夏与夷狄的区别"],["殊俗","风俗不同的人，这里指鲜卑"],["枕戈待旦","枕着兵器等天亮，形容时刻准备作战"],["大禹出于西羌","传说大禹出身西方羌人地区"],["文王生于东夷","廆借此说周文王出身“东夷”，用来驳“华夷之异”"],["志略","志向与谋略"],["冠冕之余","世代做官的名门之后"]],"think":["廆的论证“大禹出于西羌，文王生于东夷”，为什么没有说服高瞻？","圣王出身的例子可以反驳“夷人不可为君”的理论，却解决不了高瞻的实际顾虑：他来自中州大族，担忧的是身份与立场被重新定义，以及与宋该这类同僚的政治关系。理论上的反驳打不到现实的担心。对人说服要先弄清他不接受的真正原因。"],"quiz":[["高瞻一开始主张北徙幽州，依据是？",["王浚据燕代之资，兵强国富，可以依托","幽州离家乡近","王浚是同族"],"“王彭祖先在幽蓟，据燕代之资，兵强国富，可以托也。”"],["崔毖谋划联合三国攻廆时，高瞻的态度是？",["固谏认为不可","积极参加","保持沉默"],"“毖之与三国谋伐廆也，瞻固谏以为不可，毖不从。”"],["高瞻最终怎样结束？",["因忧虑而死","被廆处死","出任高官"],"“瞻闻其言，弥不自安，遂以忧死。”"]],"cards":[["廆对高瞻“称疾”的判断？","“君之疾在此，不在余也”：心病，不是身病。"],["廆驳“华夷之异”的例子？","大禹出西羌，文王生东夷。"]],"line":["大禹出于西羌，文王生于东夷，但问志略何如耳","招聘时被问“你们是外资/小公司吗”，可以引：大禹出于西羌，文王生于东夷，但问志略何如耳——看志向与能力，不看出身。"],"tags":["慕容廆","前燕","汉人士族"]},"zhuyan_shile_jialing":{"intro":"这一组短段连读，可以看到慕容廆在“官爵、外交、治国”三个层面的做法：东晋授他平州牧、辽东郡公，“承制海东”；他拒绝石勒使节、转而灭宇文乞得龟；他亲撰家令，把司法、贤才、农业、戒酒色列为四条国本。","focus":["官爵的实质：“承制海东，命备官司，置平州守宰”——晋廷把设官权实际交给慕容廆，所谓“丹书铁券”只是追认既成事实。再看“寻加使持节、都督幽州东夷诸军事、车骑将军、平州牧，进封辽东郡公，邑一万户”，官职一层层加码，一方面是东晋要利用慕容部牵制北方，另一方面也说明慕容部对晋的作用已高于一个边将。","“石勒遣使通和，廆距之，送其使于建邺”是一步一箭三雕：向东晋表明立场，切断与羯赵的往来，也激怒了石勒。随后宇文乞得龟来攻，廆“以裴嶷为右部都督，率索头为右翼，命其少子仁自平郭趣柏林为左翼”，三路合围，“悉虏其众……徙其人数万户以归”。拒绝与胜利联成一条因果链。","家令四条：“狱者，人命之所悬也，不可以不慎。贤人君子，国家之基也，不可以不敬。稼穑者，国之本也，不可以不急。酒色便佞，乱德之甚也，不可以不戒。”每条用“不可以不”收束，语气是自我约束而非号令。排序也有意味：先“慎狱”，后“敬贤”，再“重农”，最后戒私德。"],"notes":[["丹书铁券","以丹砂书写在铁券上的封赏凭证，表示恩宠与免罪"],["承制海东","在辽东、海东之地代表朝廷行使任命权"],["平州牧","平州的最高长官"],["辽东郡公","封地为辽东郡的公爵"],["令支","段部所在地，在今河北迁安一带"],["索头","对拓跋鲜卑的称呼，这里指其所率部众"],["右部都督","统领右翼部队的官职"],["特进","给予位次崇高的官衔，礼同三公"],["开府仪同三司","可以开设府署、待遇同三公的高级官衔"],["家令","为子孙训诫而写的文字"],["便佞","善于谄媚逢迎的人"],["稼穑","耕种与收获，指农业"]],"think":["为什么廆要把使者“送于建邺”而不是直接杀掉或驱走？","送使者给东晋是向对方展示忠诚的最直接证据：对方通过石勒使节的真实身份，就知道辽东已经站在晋一边；杀掉则会失去这个筹码，驱走则无法证明。这是把对手的外交举动转化为自己的政治资本。"],"quiz":[["石勒使节来通和，廆的处理是？",["拒绝并送使者去建邺","接受通和","扣押使者索取赎金"],"“石勒遣使通和，廆距之，送其使于建邺。”"],["击败宇文乞得龟时，廆的布置是？",["皝正面，裴嶷率索头为右翼，仁为左翼","只派慕容仁一路","自己全军压上"],"“遣皝距之。以裴嶷为右部都督，率索头为右翼，命其少子仁自平郭趣柏林为左翼”。"],["家令里关于农业的一条怎么说？",["稼穑者，国之本也，不可以不急","稼穑者，赋税之源也","稼穑者，仓廪之资"],"原文“稼穑者，国之本也，不可以不急”。"]],"cards":[["廆家令四条的对象？","狱、贤人君子、稼穑、酒色便佞。"],["石勒使者的下场？","被送到东晋建邺。"]],"line":["稼穑者，国之本也，不可以不急","做区域规划时可以引这句：稼穑者，国之本也，不可以不急——先把粮食与基本盘稳住。"],"tags":["慕容廆","前燕","治国"]},"zhuyan_taokan":{"intro":"慕容廆写给东晋太尉陶侃的书信节选。信里痛陈东晋内乱，劝陶侃整军北伐，并自许在北方为“内应”。读这一封信，可以看出慕容廆对自己地位的认识：他把自己放在“边臣”位置，同时试图把东晋拉进共同讨羯的计划，为日后求封燕王铺垫。","focus":["前半段是指责：“王敦唱祸于前，苏峻肆毒于后，凶暴过于董卓，恶逆甚于傕汜”，“深怪文武之士，过荷朝荣，不能灭中原之寇，刷天下之耻”。他先把东晋的内乱说成比汉末更甚，再责怪重臣不作为——这是以外藩身份批评朝廷，但一直落脚在“耻”和“寇”两个字，而非攻击正统。","对王导与庾亮的评价耐人寻味：“王司徒清虚寡欲，善于全己，昔曹参亦崇此道，著画一之称”，“庾公居元舅之尊，处申伯之任，超然高蹈，明智之权”。表面都是褒奖，但“善于全己”“超然高蹈”读起来更像委婉的批评：不肯做事。这是我对语气的解读，原文并未直说。","方案是联手：“今海内之望，足为楚汉轻重者，惟在君侯。若戮力尽心，悉五州之众，据兖豫之郊，使向义之士倒戈释甲，则羯寇必灭”。廆自己“在一方，敢不竭命”，却强调“孤军轻进，不足使勒畏首畏尾”——自己出兵不够，必须有晋军主力牵制石勒，他才能与“怀旧之士”里应外合。"],"notes":[["王敦","东晋初年起兵作乱的权臣"],["苏峻","咸和年间叛乱的将领"],["傕泛","李傕、郭汜，汉末董卓余党，祸乱长安"],["清虚寡欲","心志清静、少有欲望"],["曹参","西汉初相国，主张守成无为"],["画一","法令整齐划一；“画一之称”指萧规曹随的美名"],["申伯","周宣王的舅父，贤舅的典型"],["元舅","皇帝的大舅，指外戚首辅"],["楚汉轻重","像楚汉相争时能左右胜负的力量"],["羯寇","指羯族出身的后赵石勒政权"],["畏首畏尾","前后都有顾忌；这里指石勒受到南北两面牵制"],["五州","指陶侃所能调动的长江流域州郡"]],"think":["这封信对陶侃说“惟在君侯”，对别的朝臣却多有微词，为什么？","陶侃当时握有荆江重兵，是东晋唯一可能北伐的人；慕容廆想要的是一个军事上的盟友，而不是朝廷上的清谈官员。信里的褒贬是有选择的：褒的是能出兵的人，贬的是主张守成的人。读书信要看收信人与写信人的利益关系。"],"quiz":[["信中说“惟在君侯”，“君侯”指？",["太尉陶侃","司徒王导","东晋皇帝"],"该信是“遣使与太尉陶侃笺”，“君侯”是对陶侃的尊称。"],["廆认为自己“孤军轻进”会怎样？",["不足使石勒畏首畏尾，内应也无法发动","必败无疑","足以击溃石勒"],"“孤军轻进，不足使勒畏首畏尾，则怀旧之士欲为内应，无由自发故也。”"],["信里以什么形容东晋内乱？",["王敦、苏峻比董卓、傕汜","八王之乱","赤眉绿林"],"“王敦唱祸于前，苏峻肆毒于后，凶暴过于董卓，恶逆甚于傕汜”。"]],"cards":[["廆提出的联合北伐方案？","陶侃悉五州之众据兖豫，廆在北方里应外合。"],["廆为何强调自己“孤军轻进”不足？","单靠辽东力量不能牵制石勒，内应无从发动。"]],"line":["今海内之望，足为楚汉轻重者，惟在君侯","向关键合作方发出邀请时可以说：足为楚汉轻重者，惟在君侯——点明对方的位置，也是点明合作的价值。"],"tags":["慕容廆","前燕","外交"]},"zhuyan_qing_yanwang":{"intro":"东夷校尉封抽等三十余人联名上疏，请求晋廷进封慕容廆为燕王；陶侃回信，说朝廷自会定夺；结果“朝议未定。八年，廆卒，乃止”。三段合读，可以看清前燕“燕王”之号的来历，以及它为什么在廆生前没有落地。","focus":["上疏的论证不在“功高”，而在“职权”。他们先说廆“忠于王室”，再说“九命未加”“位卑爵轻”，真正的理由是“今燕之旧壤，北周沙漠，东尽乐浪，西暨代山，南极冀方，而悉为虏庭”，所以应“遵周室、准汉初”封为燕王，“上以总统诸部，下以割损贼境”。封王是为了统领、为了名义上收复，而不只是荣誉。","陶侃回信把话说得谨慎：他列举廆的功劳——“羯贼求和，执使送之，西讨段国，北伐塞外，远绥索头”，也承认“东方官号，高下齐班，进无统摄之权，退无等差之降”，即辽东官员品级相同，廆没有名义节制他们。但结尾是“当任天台也”：由朝廷决定。他不替朝廷拍板。","结局只用八个字：“朝议未定。八年，廆卒，乃止。”此后封王之号并未批准。廆死后，谥“襄”；儁称帝后追尊为“武宣皇帝”。这一对比提醒读者：《晋书》里的“谥曰襄”是东晋所赠，“武宣”是慕容氏自己追上的庙谥。"],"notes":[["九命","周代官爵最高一级，借指最高礼遇"],["藩翰","屏藩，指镇守边地的诸侯"],["匡霸","辅助王业、稳定霸局"],["管仲","春秋时齐桓公之相"],["燕之旧壤","战国燕国旧地，借指北方这一带"],["桓文之功","齐桓公、晋文公称霸之功"],["苟利社稷，专之可也","只要对国家有利，可以自作决断"],["官号","官职与称号"],["统摄之权","统领、节制其他官员的权力"],["天台","朝廷"],["荒服","离王畿最远的边远地区，也指献贡的边远部族"],["谥曰襄","朝廷所赠谥号为“襄”"]],"think":["封抽等人为什么选择“燕王”这个名号，而不是更高或更低的名号？","“燕”对应战国燕国旧地，“北周沙漠，东尽乐浪，西暨代山”恰在慕容辖区；封号与地域相应，朝廷易于接受，对内也可以主张“收复旧壤”的合法性。比“公”高、比“帝”低，既能总统诸部，又不至于被视作僭越。这是名分设计的一个现实选择。"],"quiz":[["上疏请封廆为燕王的主要依据是？",["燕之旧壤悉为虏庭，需要有人总统诸部、割损贼境","廆的年龄最长","石勒已被擒"],"原文“进封廆为燕王，行大将军事，上以总统诸部，下以割损贼境”。"],["陶侃回信对封王之事的态度是？",["表示同情，但交由朝廷决定","坚决反对","立即批准"],"“可不、迟速，当任天台也。朝议未定。”"],["“乃止”说明什么？",["廆去世，封王一事不了了之","朝廷批准封王","廆自己放弃"],"“八年，廆卒，乃止。”"]],"cards":[["陶侃说的“东方官号，高下齐班”指什么？","辽东的官员品级相同，廆没有统属他们的名义权力。"],["廆生前有没有被封燕王？","没有，“朝议未定，廆卒乃止”。"]],"line":["苟利社稷，专之可也","紧急情况下需要先决策后汇报时，可以引：苟利社稷，专之可也——但事后要补程序，要说明。"],"tags":["慕容廆","前燕","名分"]},"zhuyan_huang_xi":{"intro":"慕容廆去世，慕容皝嗣位。他一边应付宇文部内乱，一边面对兄弟之间的猜忌：庶兄慕容翰出奔段辽，同母弟慕容仁在平郭起兵、尽有辽左之地，宇文归、段辽都成了仁的外援。这是前燕早期最险的一次家变，读它要注意皝的处理手法和后果。","focus":["皝本人的材料：“龙颜版齿，身长七尺八寸。雄毅多权略，尚经学，善天文”，是个读书又有谋略的人；而他面对的格局是：庶兄翰“骁武有雄才，素为皝所忌”，母弟仁、昭“并有宠于廆，皝亦不平之”。继位者与有功的兄、受宠的弟之间，早就存在三角猜疑。","触发点在“遣使按检仁之虚实”：皝先杀昭，再派使者去查仁，结果使者被杀，仁“东归平郭”举兵。这一步是先杀一个弟，再去查另一个弟——对方自然不会束手。后面“幼等大败，皆没于仁”“王冰、孙机以辽东叛”“封抽、乙逸……弃城奔还”，说明辽东郡县都不把皝当作稳固的主君。","仁的外援清单：“宇文归、段辽及鲜卑诸部并为之援”。家变一旦与外部势力联成线，就不再是家事。后来皝亲征辽东、斩仁，是通过几年努力才收回的。此段只写失败，没有粉饰；读《晋书》载记，要注意这类“先败后胜”的结构。"],"notes":[["龙颜版齿","相书称帝王之相的套话：额骨隆起、门牙宽大"],["世子","诸侯、王公的法定继承人"],["左贤王","匈奴、鲜卑系统中仅次于单于的王号"],["行平州刺史","代理平州刺史"],["督摄部内","统领、监督全部境内事务"],["别部","同一族中另一支部落"],["按检","核查、检查"],["险渎","地名，皝使者与仁相遇处"],["平郭","辽东郡属县，慕容仁据点"],["辽左","辽河以东之地"],["车骑将军","高级将军号，仁自称"]],"think":["皝派使者“按检仁之虚实”是否必然逼反了仁？换成别的处理方式会怎样？","不必然，但风险极高：仁刚见昭被杀，核查使者一到，就等于下一个轮到他。更稳妥的做法是先稳住仁、以任命或联姻缓和，再逐步收权。皝的选择说明他把“猜疑”当成“事实”，直接动手，收益是果断，代价是将对手推到敌人一边。"],"quiz":[["翰出奔后投靠谁？",["段辽","宇文归","高句丽王"],"“翰出奔段辽，仁劝昭举兵废皝”。"],["仁起兵后，“尽有”的是哪里？",["辽左之地","幽州","平州全境"],"“仁于是尽有辽左之地，自称车骑将军、平州刺史、辽东公”。"],["皝派去讨仁的“幼等”结局如何？",["大败，全军被仁所获","击溃仁军","与仁讲和"],"“仁尽众距战，幼等大败，皆没于仁。”"]],"cards":[["皝继位初期三个潜在对手？","庶兄翰（骁武被忌）、同母弟仁与昭（有宠于廆）。"],["仁的外援？","宇文归、段辽与鲜卑诸部。"]],"line":["翰骁武有雄才，素为皝所忌","分析组织内权力交接时可以引：素为……所忌——先问谁被谁忌，再看谁会先出走。"],"tags":["慕容皝","前燕","家变"]},"zhuyan_han":{"intro":"慕容翰是慕容廆的庶长子，也是前燕早期最能打仗的人。他被皝猜忌而出奔段辽，又转投宇文，最终逃回，仍难免被赐死。四段连读，是一个人物弧线非常完整的例子：他在敌国时“因事立忠”，射中刀环才得以回国，回国后却死在自己的故国。","focus":["“因事立忠”一语概括了他在段氏时的做法：柳城之败后，段兰想乘胜深入，翰“虑成本国之害，诡说于兰，兰遂不进”；石季龙攻辽，皝亲征令支，段辽欲追，翰抢先劝阻，“燕王自来，士马精锐……若其失利，何以南御乎”。他的话从段氏的利益出发，却把对方拖在原地，叫人挑不出毛病，这是他最难得的技术。","射刀环是一场心理战：“吾既思恋而归，理无反面。吾之弓矢，汝曹足知，无为相逼”。他先说明立场，再抬出自己的名声，最后给出一个选择——“汝可百步竖刀，吾射中者，汝便宜反”。“归骑解刀竖之，翰一发便中刀环，追骑乃散”。武艺在这里是政治信号，是让追兵放弃的借口。","被杀的缘由很小：病愈后“于其家中骑马自试”，有人告发“私习骑，疑为非常”，皝“素忌之，遂赐死”。翰临终说“今日之死，翰之生也”，意思是自己外奔有罪，用死来洗刷；又说“志吞丑虏”“没有余恨，命也奈何”。《晋书》借这句话留下评价：翰至死仍以前燕之人自居。"],"notes":[["折冲之任","击退敌人、保卫疆土的重任"],["猿臂","臂长如猿，善于射箭"],["膂力","体力、臂力"],["柳城之败","段兰进攻柳城的战事；这里指前燕与段氏的冲突"],["诡说","用计谋游说"],["因事立忠","借着具体事情，向本国表达忠诚"],["理无反面","于理不应再回头相见"],["刀镮","刀柄上的圆环"],["私习骑","私下练习骑马"],["赐死","皇帝或君主命人自杀"],["骸骨","遗体"],["仰药","服毒"]],"think":["皝为什么对翰始终不放心？这种猜忌有没有道理？","有一部分道理：翰是庶长子，战功大、威望高，又曾投靠段氏、宇文，在继承权与外联上都具有风险；但皝的做法太过：病愈骑马被视为“非常”，已经是把防范扩张成惩罚。结局是失去一位最能带兵的将领，也让后来儁、恪一代缺少老将。"],"quiz":[["翰在段氏时劝阻段辽追击皝，说的理由是？",["石氏将至，燕王亲征士马精锐，失利则无法南御","段部兵少","天时不利"],"“今石氏向至，方对大敌……燕王自来，士马精锐……若其失利，何以南御乎！”"],["追兵追来，翰怎么脱身？",["让追兵竖刀，射中刀环","与追兵决斗","收买追兵"],"“汝可百步竖刀，吾射中者，汝便宜反”，“翰一发便中刀环，追骑乃散”。"],["翰被赐死的直接导火索是？",["病愈后在家骑马被举报私习骑","与段氏通信","违令出兵"],"“或有人告翰私习骑，疑为非常。皝素忌之，遂赐死焉。”"]],"cards":[["“因事立忠”的例子？","在段氏时劝段兰不要深入、劝段辽不要追皝，实际保护了前燕。"],["翰临死的话？","“今日之死，翰之生也”，并以未能志吞丑虏为恨。"]],"line":["今日之死，翰之生也","组织内被冤却仍认同大局的人，也可以这样说：今日之死，翰之生也——不是认错，是守住最后的立场。"],"tags":["慕容皝","前燕","人物"]},"zhuyan_chengwang":{"intro":"咸康三年，慕容皝在封弈等人劝进下称燕王，建官署、乘金根车、驾六马，出入称警跸，同时晋廷又加他征北大将军、幽州牧。这一段是前燕从“晋臣”走向“王国”的转折，读法是：看称王的理由、看礼制参照、看晋廷的反应。","focus":["称王的理由是“任重位轻”：封弈等指出皝的责任与名位不匹配，要求“宜称燕王”。这是以事功推导名位，而非“天命”之类的话。接着是一串任命：国相封弈、司马韩寿，裴开、阳骛、王宇、李洪等十余人“并为列卿将帅”，说明班底已按王国格局设置，其中汉人士人占了很大比例。","礼制很讲究，也很自信：“起文昌殿，乘金根车，驾六马，出入称警跸。以其妻段氏为王后，世子儁为太子，皆如魏武、晋文辅政故事。”金根车、驾六马、称警跸本属天子仪制，但他援引的是“魏武、晋文”这两位未称帝的权臣，等于把自己定位成辅政的王而不是皇帝。名义上维持“晋臣”，实际仪制拉到最高。","晋廷的动作很被动：“帝又遣使进皝为征北大将军、幽州牧，领平州刺史，加散骑常侍，增邑万户”，只是加官；同传下文说“皝虽称燕王，未有朝命”，皝才遣刘祥献捷并上表，朝廷后来“听皝称燕王”。也就是先称后认，朝廷追认。"],"notes":[["任重位轻","肩负的责任重而地位低"],["国相","王国的最高行政官"],["列卿","各部门的长官"],["文昌殿","皝所建宫殿的名称"],["金根车","天子所乘的饰金之车"],["驾六马","六匹马拉车，天子仪制"],["警跸","帝王出入时清道、警戒行人"],["魏武","曹操，死后被追尊为魏武帝"],["晋文","春秋晋文公，称霸而未称王"],["辅政故事","辅佐朝政的先例"],["王后","王的正妻"],["征北大将军","晋朝授给皝的高级将军号"]],"think":["皝称燕王，却又“皆如魏武、晋文辅政故事”。这是谦虚还是留后路？","两者都有：以“辅政”自比，是在名义上保留“忠晋”的叙事，使朝廷可以追认；同时在礼仪上按王与帝的规格操作，为日后儁称帝铺路。这种“名义上低、实质上高”的手法，是十六国许多政权的共性。"],"quiz":[["封弈等劝皝称燕王的理由是？",["任重位轻","晋室已亡","天降祥瑞"],"“封弈等以皝任重位轻，宜称燕王。”"],["皝仪制中“驾六马”属于？",["天子乘舆的规格","诸侯常规","武官仪仗"],"金根车、驾六马、警跸都是帝王出行的排场，皝在称王时已经采用。"],["晋廷在皝称王后首先做了什么？",["加征北大将军、幽州牧等官衔","出兵讨伐","册立新王"],"“帝又遣使进皝为征北大将军、幽州牧，领平州刺史……”"]],"cards":[["皝称燕王的年份？","咸康三年。"],["“如魏武、晋文辅政故事”的含义？","以辅政的权臣自居，不直接称帝，保留尊晋名义。"]],"line":["以皝任重位轻，宜称燕王","为一位关键同事争取头衔时可以说：任重位轻，宜加其号——职责与名分要匹配。"],"tags":["慕容皝","前燕","名分"]},"zhuyan_waiqi_biao":{"intro":"皝称燕王后未得朝命，遣长史刘祥到京师献捷并请讨中原，又听说庾亮去世、其弟庾冰庾翼继任将相，便上表痛陈外戚之弊。表文从申伯、穰侯一路讲到王莽、窦宪、梁冀，落到庾亮与苏峻之乱，最后提出“封以藩国”的办法。这是一份史学素养很高的政论，也是他向朝廷表明立场的策略。","focus":["论证先立两条正反线：“亲贤并建，则功致升平；若亲党后族，必有倾辱之祸”。随后举例：周之申伯是贤舅，“以其身藩于外，不握朝权”；秦昭王“委信二舅，几至乱国”；汉武“推重田蚡”，成帝“外恣五舅，卒令王莽坐取帝位”。他的结论是：舅氏若贤，则“但闻有二臣，不闻有二主”；若不才，便有“窦宪、梁冀之祸”。","第二层落到当朝：“实因故司空亮居元舅之尊，势业之重，执政裁下，轻侮边将，故令苏峻、祖约不胜其忿，遂致败国。”把苏峻之乱的责任落在庾亮对边将的轻侮上，而自己恰是“边将”，这是一个很巧妙的立场安排：批评的是外戚，维护的是外镇；暗示朝廷不该轻视边将。","第三层是办法：“何不封以藩国，丰其禄赐，限其势利”，使“上无偏优，下无私论”。一个外镇要求朝廷把外戚改封为藩王，听起来大义凛然，也给了对方台阶：只要改封，就不是被边将逼退。同传随后写“冰见表及书甚惧，以其绝远，非所能制，遂与何充等奏听皝称燕王”，可见表文起了作用。"],"notes":[["献捷","向朝廷报告战胜俘获"],["权假","暂时凭借权宜之计取得名号，这里指皝权且称燕王"],["申伯","周宣王舅，号称贤舅"],["穰侯","秦昭王之舅魏冉，权势极盛"],["田蚡","汉武帝的舅父，曾把持朝政"],["王莽","汉成帝之舅王氏出身，后篡汉"],["窦宪","东汉外戚，骄横专权"],["梁冀","东汉外戚，权倾一时"],["苏峻","咸和年间叛乱，“祖约”为其同谋"],["枢机","国家权力中枢"],["藩国","分封的诸侯国"],["户告","挨家挨户去解释"]],"think":["皝的表文把“防外戚”与“请讨中原”放在一起，这样的组合有什么政治用意？","前者让皇帝觉得他是忠诚直谏的人，后者给自己的称王和备战找名义。防外戚的话在朝廷权力结构里真实有效：庾氏兄弟确实是当时的实权人物，批评他们等于给皇帝一个与外戚拉开距离的理由，也是在为自己争取支持。"],"quiz":[["皝认为“苏峻、祖约”之乱的原因是？",["庾亮居元舅之位，轻侮边将","朝廷财政困难","蛮族入侵"],"“实因故司空亮居元舅之尊……轻侮边将，故令苏峻、祖约不胜其忿，遂致败国。”"],["皝提出处理外戚的办法？",["封以藩国，丰其禄赐，限其势利","诛杀外戚","流放外戚"],"“何不封以藩国，丰其禄赐，限其势利，使上无偏优，下无私论。”"],["表文之后，朝廷对皝称燕王的反应？",["听皝称燕王","下诏斥责","出兵讨伐"],"“冰见表及书甚惧，以其绝远，非所能制，遂与何充等奏听皝称燕王。”"]],"cards":[["表文说贤舅与不才舅的差别？","贤舅则“但闻有二臣，不闻有二主”；不才则有窦宪、梁冀之祸。"],["表文最后的办法？","封外戚以藩国，给禄限权。"]],"line":["则但闻有二臣，不闻有二主","评价集团内的双核权力时可以引：但闻有二臣，不闻有二主——最好的结构是都服从同一个核心。"],"tags":["慕容皝","前燕","政论"]},"zhuyan_ji_xi":{"intro":"皝在咸康年间图谋石赵，在判断石虎防守重心之后，绕开“安乐诸城”，从蠮螉塞出兵，长驱到蓟城，渡武遂津、入高阳，焚积聚、徙户口三万余。随后命阳裕等筑龙城，晋成帝遣郭希持节拜皝为燕王。这一段是皝用兵与建城、名分与实力同时推进的写照。","focus":["作战判断的逻辑清晰：“石季龙自以安乐诸城守防严重，城之南北必不设备，今若诡路出其不意，冀之北土尽可破也。”他先看对手最重视哪里，再选对手最不设防处。行动内容也明确：“所过焚烧积聚，掠徙幽冀三万余户”，目标不是占城，而是削弱对方储备并增加己方人口。","建城同步进行：“使阳裕、唐柱等筑龙城，构宫庙，改柳城为龙城县。”阳裕主持规划（后传说“皝所制城池宫阁，皆裕之规模”），说明汉人士大夫不只做文书，还参与国都营造。军事掠户和筑城正好互补：有了人，才建得起城。","晋廷的反应是“使兼大鸿胪郭希持节拜皝侍中、大都督河北诸军事、大将军、燕王”。这里出现的“燕王”是由晋廷正式拜授，与上一单元的“称燕王、未有朝命”形成时间差：先自称、后遣使献捷与上表，再由朝廷持节拜授。末尾“皝躬巡郡县，劝课农桑，起龙城宫阙”，又回到农与城的基本盘。"],"notes":[["安乐诸城","后赵设在北方安乐一带的防御城镇"],["诡路","不走寻常道路，绕行奇道"],["蠮螉塞","塞名，在今北京西北居庸关一带"],["武遂津","黄河支流上的渡口"],["高阳","地名，今河北保定一带"],["积聚","囤积的粮草物资"],["柳城","地名，皝将其改为龙城县"],["龙城县","皝为新都所设之县"],["大鸿胪","掌礼仪、外事的官员"],["持节","手持符节，代表朝廷行使权力"],["河北诸军事","黄河以北各军事事务"],["劝课农桑","督促耕田、养蚕"]],"think":["皝突袭幽冀“所过焚烧积聚”，战略收益是什么？","焚毁储备直接削弱后赵的后勤和动员能力；掠户三万多，等于补充了前燕的劳动力与兵源；而且不占城，不需要防守，风险较小。这类“打了就走”的战术，是弱国对强国最现实的办法。"],"quiz":[["皝判断石虎的防御薄弱点在哪里？",["安乐诸城的南北两侧不会设防","渡口","都城"],"“石季龙自以安乐诸城守防严重，城之南北必不设备。”"],["这一战的主要成果是？",["焚烧积聚、掠徙三万余户","占领蓟城","擒获石虎"],"“所过焚烧积聚，掠徙幽冀三万余户。”"],["晋廷此次派谁、拜皝为什么官？",["郭希，拜燕王及侍中、大都督河北诸军事、大将军","庾翼，拜平州牧","陶侃，拜太尉"],"“成帝使兼大鸿胪郭希持节拜皝侍中、大都督河北诸军事、大将军、燕王。”"]],"cards":[["皝选择进攻路线的原则？","避开对手重点防守，从“城之南北”这类不设防处突入。"],["改柳城为什么县？","龙城县。"]],"line":["诡路出其不意，冀之北土尽可破也","制定竞争策略时可以引：诡路出其不意——别在对手最强处硬碰，先找他的盲区。"],"tags":["慕容皝","前燕","战例"]},"zhuyan_longcheng_fa":{"intro":"《晋书》把迁都龙城、伐高句丽、破宇文连在一起写：皝亲率四万精兵走南陕，另遣长史王宇走北置，高句丽王钊误判主攻方向，被翰击败于木底，丸都被毁；随后宇文归遣国相莫浅浑来攻，皝先示弱而后击破，再亲伐宇文归，斩涉奕于。这几场仗展示了前燕兵力部署与心理战的一套打法。","focus":["高句丽一战的关键是“误判”：皝兵分两路，自己走南陕，王宇走北置。钊“谓皝军之从北路也”，遂“遣其弟武统精锐五万距北置，躬率弱卒以防南陕”——把精锐放在了次要方向。翰与钊在木底交战，“大败之，乘胜遂入丸都”。战后处置相当严厉：“掘钊父利墓，载其尸并其母妻珍宝，掠男女五万余口，焚其宫室，毁丸都而归”，钊于次年“遣使称臣”，皝才“归其父尸”。","对宇文的打法是示弱：莫浅浑来攻，“诸将请战，皝不许”，莫浅浑以为皝畏惧，“荒酒纵猎，不复设备”，皝才说“浑奢怠已甚，今则可一战矣”，派翰一击成功。这与廆时三国伐廆如出一辙：先让对方骄，然后动手。","亲伐宇文归时出现战术分歧：皝派人对翰说“奕于雄悍，宜小避之，待虏势骄，然后取也”，翰却认为“归之精锐，尽在于此，今若克之，则归可不劳兵而灭”。翰违令进战，斩涉奕于，“尽俘其众，归远遁漠北”，皝“开地千余里，徙其部人五万余落于昌黎”。这里能看到前线将领的判断权：皝有计划，翰有临场判断，胜利时君主承认前者的修正。"],"notes":[["南陕","通向高句丽的南路险道"],["北置","通向高句丽的北路"],["木底","战场地名"],["丸都","高句丽都城之一"],["掘钊父利墓","挖开高句丽王钊之父的坟墓，取走遗体"],["莫浅浑","宇文归的国相"],["国相","此处指宇文部的执政大臣"],["涉奕于","宇文归的骑将"],["漠北","大漠以北，指宇文归逃往之地"],["饮至之礼","出征凯旋后在宗庙宴饮、记功的礼仪"],["威德城","皝把涉奕于城改成的名称"],["前锋","最先行动的先头部队"]],"think":["钊为什么会“谓皝军之从北路”？这种误判在战争中常见吗？","北路较近、较平、道路通畅，对手很自然地认为主力走北；皝利用了这种“常识”。战争里，对手总会按“最合理”的路径判断，所以反其道而行就能制造机会。更常见的做法是同时给出佯动与实动，让对方分兵。此役年份有出入：传文把战事写在咸康七年前后，通行系年常作咸康八年（342），存疑，读时不必强定。"],"quiz":[["高句丽之战，皝本人走哪条路？",["南陕","北置","水路"],"“率劲卒四万，入自南陕”，王宇等“从北置而进”。"],["莫浅浑被击败前，为什么松懈？",["以为皝畏惧，荒酒纵猎、不设备","兵力占优","天气不利"],"“浑以皝为惮之，荒酒纵猎，不复设备。”"],["亲伐宇文归时，皝与翰对涉奕于的意见？",["皝主张避其锋，翰主张立即进击","皝主张强攻，翰主张避让","两人意见一致"],"“皝驰遣谓翰曰：奕于雄悍，宜小避之”，翰答“今若克之，则归可不劳兵而灭”。"]],"cards":[["高句丽一战的胜因？","兵分两路，钊误判北路为主攻，主力放错方向。"],["皝对宇文莫浅浑的战术？","诸将请战而不许，示弱使其骄怠，再一战击破。"]],"line":["浑奢怠已甚，今则可一战矣","判断对手进入松懈期、决定出手时可以说：奢怠已甚，今则可一战矣——先等，再打。"],"tags":["慕容皝","前燕","战例"]},"zhuyan_fengyu_zhi":{"intro":"记室参军封裕上谏，批评皝的“苑囿牧牛”政策；皝下令罢苑囿、赐牧牛、复谏臣官。这一对谏与令展示了前燕早期的君臣政治：谏的内容涉及租佃比例、流人安置、游食与官制，令的回应有取有舍。","focus":["皝原先的政策是：“以牧牛给贫家，田于苑中，公收其八，二分入私。有牛而无地者，亦田苑中，公收其七，三分入私。”官家收七八成，农户只留二三成。封裕的数字对照很直接：“魏晋虽道消之世，犹削百姓不至于七八，持官牛田者官得六分，百姓得四分，私牛而官田者与官中分”。皝的分成比魏晋更苛，所以他说“臣犹曰非明王之道，而况增乎”。","封裕的主张是“善藏者藏于百姓”，具体做法是“省罢诸苑，以业流人”，“人至而无资产者，赐之以牧牛”，并提到“流人之多旧土十倍有余，人殷地狭，故无田者十有四焉”。他的逻辑是：流人是慕容的财富，靠得住的是他们能耕作而不是被盘剥。","皝的回应有取有舍：“苑囿悉可罢之，以给百姓无田业者”，“各赐牧牛一头”，愿取官牛耕官田者依魏晋旧法；又说“中州未平，兵难不息，勋诚既多，官僚不可以减也”，把裁官一条暂时搁置，但“百工商贾数……速定大员，余者还农”。同时，对被禁锢的谏臣王宪、刘明“悉复本官，仍居谏司”，对封裕“赐钱五万”，并宣示“有欲陈孤过者，不拘贵贱，勿有所讳”。一个完整的纳谏闭环。"],"notes":[["牧牛","耕牛，皝以此赐给贫家"],["苑囿","供君主游猎的园林，被皝用作官田"],["官牛","官府所有的耕牛"],["魏晋旧法","魏晋时官牛官田的分成办法"],["流人","因战乱流亡到辽东的百姓"],["善藏者藏于百姓","善于积蓄的人，把财富留在百姓手里"],["黎元","百姓"],["勋诚","有功而忠诚的人"],["百工商贾","工匠与商人，当时被视为非农业人口"],["谏司","负责进谏的官署"],["蹇蹇","正直敢言的样子"],["王臣之体","臣子应有的体统与风度"]],"think":["皝接受了封裕的哪些建议，又暂时没有接受哪一条？背后的考虑是什么？","接受的是罢苑囿、赐牧牛、恢复谏官、宣示纳谏；暂时搁置的是“官僚不可以减”。前者能立刻改善民生，且成本低；后者涉及功臣利益，在“中州未平”的借口下延后。这是典型的“先做代价小的事，把难的留到以后”。"],"quiz":[["封裕指出皝的分成比例比魏晋更重，主要对比的数字是？",["皝官收七八成，魏晋官得六分","皝官收五成","皝官收三成"],"皝“公收其八”“公收其七”，封裕说魏晋“官得六分，百姓得四分”。"],["封裕的核心建议是？",["罢苑囿、赐牧牛、安置流人","增加赋税","停止征战"],"“宜省罢诸苑，以业流人。人至而无资产者，赐之以牧牛。”"],["皝对“官僚不可以减”的处理是？",["待中原平定后再议","立即裁减","完全不理"],"“官僚不可以减也，待克平凶丑，徐更议之。”"]],"cards":[["皝对谏臣王宪、刘明的处理？","悉复本官，仍居谏司。"],["“善藏者藏于百姓”意思？","真正会储存的人，把财富留在百姓那里。"]],"line":["善藏者藏于百姓","谈政策让利时可以引这句：善藏者藏于百姓——先让下面有积累，上面才不会空。"],"tags":["慕容皝","前燕","谏诤"]},"zhuyan_dongxiang":{"intro":"皝重视文教。这几段记载了“高门生”“东庠”等制度，皝亲自编写《太上章》《典诫》，罢郡立县安置流人，最后以白马老父的异兆和“引儁属以后事”结尾。读它可以看到前燕在军事之外建设教育与行政的努力。","focus":["学校制度把门第和学业绑在一起：“赐其大臣子弟为官学生者号高门生，立东庠于旧宫，以行乡射之礼，每月临观，考试优劣。”皝还亲自“考试学生”，“其经通秀异者，擢充近侍”。学业成绩直接决定仕进，这是汉化政权常见的用人办法。“学徒甚盛，至千余人”，数字是史书记载，可见规模不小。","皝亲自编书：“亲造《太上章》以代《急就》，又著《典诫》十五篇，以教胄子。”《急就》是汉代蒙学字书，“以代”二字写明他认为旧教材不够用，要用自己写的取代。胄子指贵族子弟，教材面向的是继承人群体，可见皝想把文化当作继承的一部分。","“罢成周、冀阳、营丘等郡，以勃海人为兴集县，河间人为宁集县……吴人为吴县，悉隶燕国”，是把流人按原籍编成县并入燕国：既减少郡级机构，又保留乡土认同。结尾“引儁属以后事”前，先写黑龙白龙、白马老父的异兆，史书用神异收束，实际重点还是后事的交代。"],"notes":[["官学生","官办学校的学生"],["高门生","皝给大臣子弟官学生所起的称号"],["东庠","东边的学校，周代有东序之称"],["乡射之礼","地方官学中举行的射箭礼仪"],["急就","汉代史游所作的识字课本《急就篇》"],["胄子","贵族子弟"],["典诫","皝所著的训诫文章，共十五篇"],["近侍","君主身边的侍从官"],["丐","免除、赐予"],["兴集县","为渤海流人所设的县"],["悉隶燕国","全都归属燕国"],["属以后事","把后事托付给他"]],"think":["皝设立“高门生”“东庠”，同时以“经通秀异者擢充近侍”，这种制度有什么后果？","好处是把贵族子弟与官学、仕进联系起来，有利于文化与行政的汉化；风险是门第与学业合一，容易形成固定的特权阶层，也压缩了出身低但有才者的升迁路径。读这类制度要同时看“选拔”与“固化”。"],"quiz":[["“高门生”指的是？",["大臣子弟中的官学生","宫中侍卫","州郡的贡士"],"“赐其大臣子弟为官学生者号高门生。”"],["《太上章》的作用是？",["代替《急就》作为教材","记录军功","颁行法令"],"“亲造太上章以代急就”。"],["把勃海人设为兴集县的目的？",["按原籍安置流人，同时归属燕国","扩大海防","迁都"],"“以勃海人为兴集县，河间人为宁集县……悉隶燕国。”"]],"cards":[["皝自己编写的教材？","《太上章》（代《急就》）与《典诫》十五篇。"],["东庠的考核结果影响什么？","经通秀异者擢充近侍。"]],"line":["亲造太上章以代急就","自己动手编内部教材时可以引这句：亲造……以代——不满意现成的，就自己写一套。"],"tags":["慕容皝","前燕","文教"]},"zhuyan_jun_shizi":{"intro":"慕容儁是慕容皝的第二子。这一段交代他的出身、嗣位，以及他怎样利用石赵之乱布置兼并。要看三件事：廆那句“子孙当有中原”的预言怎样被写进开篇；儁“依春秋列国故事称元年”的自立方式；皝、儁两代都由晋廷“承制封拜”的格局。","focus":["史官在儁出生前放了一句预言：“吾积福累仁，子孙当有中原。”儁出生，廆说“此儿骨相不恒，吾家得之矣”。这是传记里常见的“预兆”写法，只能当作叙述层，不能当作事实。真正可核对的是后面的几句：“博观图书，有文武干略”，皝为燕王时拜他“东夷校尉、左贤王、燕王世子”——他是被按继承人训练出来的。","“依春秋列国故事称元年”是自立年号体系的第一步：诸侯即位称元年，既不用晋年号，又不称帝，处在“晋臣”与“新国”之间。同一年“穆帝使谒者陈沈拜儁为使持节、侍中、大都督、都督河北诸军事、幽冀并平四州牧、大将军、大单于、燕王，承制封拜一如廆、皝故事”，晋廷追认了他的王位，也继续承认他对辖区的任命权。","兼并布置在“石季龙死，赵魏大乱”之后。儁分派了四位将领：慕容恪“辅国将军”，慕容评“辅弼将军”，阳骛“辅义将军”，慕容垂“前锋都督、建锋将军”，并且“简精卒二十余万以待期”。其中恪、评、垂，正是此后前燕、后燕两代的关键人物。这份名单里已经埋着后来的矛盾。"],"notes":[["骨相","相貌骨骼所显示的命运，古人相术用语"],["假节","临时授予符节，使其在特定范围内有处置权"],["东夷校尉","晋朝设在东北的官职，统辖东夷各部"],["世子","王公爵位的法定继承人"],["春秋列国故事","春秋诸侯即位后改称元年的先例"],["辅国将军","军号之一"],["前锋都督","统率先头部队的主将"],["简精卒","挑选精锐士兵"],["以待期","等候时机"],["使持节","皇帝授予的最高一级符节，可诛杀二千石以下官员"],["承制封拜","在没有皇帝逐次下诏的情况下，可代行任命官爵"],["河北诸军事","黄河以北各军事事务"]],"think":["为什么《晋书》要把“子孙当有中原”写在慕容廆口中、写在儁出生那一刻？","预言是后设的叙事：作者知道儁后来称帝入中原，便把预兆放到前面，强化“天命”的因果。读者要把它与“博观图书，有文武干略”之类可核对的描述分开。凡是“生时有异”的内容，都按“据载”处理。"],"quiz":[["“依春秋列国故事称元年”意味着什么？",["以诸侯身份自行纪年，既不称帝也不沿用晋年号","已经改元称帝","向晋廷请求改元"],"春秋列国诸侯嗣位称元年，儁借此建立自己的纪年，又保留“燕王”身份。"],["晋廷给儁的册封特点是？",["承制封拜，一如廆、皝故事","只授虚衔","拒绝承认"],"“承制封拜一如廆、皝故事”，延续此前对慕容氏的做法。"],["儁预备南图时任命的“前锋都督”是？",["慕容垂","慕容评","阳骛"],"“慕容垂为前锋都督、建锋将军”。"]],"cards":[["廆对儁出生时的评语？","“此儿骨相不恒，吾家得之矣。”"],["儁嗣位后的四位核心将领？","恪（辅国）、评（辅弼）、阳骛（辅义）、垂（前锋）。"]],"line":["吾积福累仁，子孙当有中原","给团队鼓劲时，可以借这句的结构：积福累仁，当有中原——但别忘了，有人在把预言变成现实。"],"tags":["慕容儁","前燕","继位"]},"zhuyan_changwei_shi":{"intro":"冉闵杀石祗后称帝，派常炜出使前燕。慕容儁让记室封裕连问三个问题，并“积薪置火”试他是否说谎。这一段是一场以命相搏的外交对话：祥瑞、玉玺、铸像，三个问题都围绕“天命”，而儁真正在意的，也是自己称帝前的合法性。","focus":["三问有层次：先问“冉闵养息常才，负恩篡逆，有何祥应而僭称大号”，常炜答“狼乌纪于三王，麟龙表于汉魏”；再问石祗使者所说“玺在襄国”，答“诛胡之日，在邺者略无所遗，玺何从而向襄国”；最后问“闵铸金为己象，坏而不成”，答“铸形之事，所未闻也”。三次回答，每次都在拆对方的材料。","儁的反应说明了用意：“既锐信举言，又欣于闵铸形之不成也，必欲审之”，于是“积薪置火于其侧”。他要的是一个确凿的“冉闵无天命”的证据，因为这关系到他自己：如果天命还未归任何人，他就可以考虑承接。这里是我对动机的推断，史文只写了“欣于闵铸形之不成”。","常炜的回答是：“结发已来，尚不欺庸人，况千乘乎！巧诈虚言以救死者，使臣所不为也。直道受戮，死自分耳。益薪速火，君之大惠。”他的逻辑是使节的信用就是国家的信用。儁最后说“古者兵交，使在其间，此亦人臣常事”，遂赦之。这也是后来苻丕对慕容垂使者姜让、慕容垂对苻丕使者所说的类似的话——乱世里“使不可杀”几乎是双方默认的底线。"],"notes":[["养息","养子；冉闵是石虎的养孙，这里称“养息”"],["僭称大号","越分自称皇帝"],["祥应","祥瑞的应验"],["狼乌","狼与乌鸦，传说周文王、武王时的祥瑞"],["麟龙","麒麟与龙，汉魏受命的祥瑞"],["干符","天授的符命"],["积薪","堆起柴火"],["直道受戮","因为坚持直言而被杀"],["千乘","拥有千辆兵车的君主，这里指儁"],["神色自若","神态镇定如常"],["使在其间","使者在两军之间往来"],["铸金","用金属铸造像，古人以铸像成否占测天命"]],"think":["常炜为什么敢当面说“益薪速火，君之大惠”？这是勇气，还是对儁的判断？","二者兼有：他明知儁的目的是要听到真话，只要自己前后一致，儁就没有理由杀他；同时他也要用死来证明使节的诚信，这比任何辩解都有力。判断对方真正想要什么，再给他一个“不可替代”的答案，是外交场合最危险也最有效的手法。"],"quiz":[["常炜用什么回应“玺在襄国”的说法？",["诛胡时邺中无一遗存，玉玺不可能到襄国","承认玉玺在襄国","说玉玺已被毁"],"“诛胡之日，在邺者略无所遗，玺何从而向襄国，此求救之辞耳。”"],["儁为什么积薪置火？",["想验证常炜与石祗使者的说法真假","要处死常炜","想吓退冉闵"],"“必欲审之，乃积薪置火于其侧，命裕等以意喻之。”"],["儁最终怎样处理常炜？",["赦免，理由是“使在其间”","关押","杀掉"],"“古者兵交，使在其间，此亦人臣常事。”遂赦之。"]],"cards":[["冉闵为何被称“养息常才”？","他是石虎养孙，被燕人视为出身不明、才具平常。"],["常炜自述的原则？","结发以来不欺庸人，况千乘乎；巧诈虚言救死，使臣不为。"]],"line":["结发已来，尚不欺庸人，况千乘乎","在谈判里被怀疑诚信时，可以引：结发已来，尚不欺庸人——把信用摆在最前面。"],"tags":["慕容儁","前燕","外交"]},"zhuyan_ke_weicheng":{"intro":"慕容恪是前燕最会打仗、也最会控制战争成本的统帅。两段文字相隔数年：一是儁时围广固，对象是段龛；一是暐时围野王，对象是吕护。两次他都不肯急攻，理由几乎相同。放在一起读，可以归纳出他“该急则急、该缓则缓”的判断标准。","focus":["广固之战的核心是恪的“急缓之辨”：“若彼我势均，且有强援，虑腹背之患者，须急攻之，以速大利。如其我强彼弱，外无寇援，力足制之者，当羁縻守之，以待其毙。”他援引“兵法十围五攻”，并分析龛“恩结贼党，众未离心，济南之战，非不锐也，但其用之无术”。结论是“若其促攻，不过数旬，克之必矣，但恐伤吾士众”，所以“筑室反耕，严固围垒”。","野王之战同一逻辑，更强调代价：傅颜主张“宜急攻之，以省千金之费”，恪回答“护老贼，经变多矣……何必遽残士卒之命而趣一时之利哉！吾严浚围垒，休养将卒，以重官美货间而离之”，要用官爵与财货离间守军。结果“自三月至八月而野王溃，护南奔于晋”。两次胜利都不靠强攻，而靠“内无积蓄，外无强援”的计算。","要注意史文的限定：恪每次先打一场野战消灭对手机动兵力（广固前有济水之战，野王前有张兴出战被斩），再围。这说明他不是“怕打”，而是选择最小损失的方式。广固围城后，“王腾、薛云降于恪”，也是政治手段发生作用。"],"notes":[["广固","地名，段龛据守处，在今山东青州一带"],["齐王","段龛自号"],["中表之仪","表亲平等的礼节"],["羁縻","用笼络办法使其不乱，这里指围困不急攻"],["十围五攻","兵法：兵力十倍于敌则围，五倍则攻"],["济水","古水名，在今山东"],["筑室反耕","修建营房、让士兵耕田，表示长期围困"],["严固围垒","加强围城工事"],["野王","地名，吕护据守处，在今河南沁阳"],["千金之费","巨额费用"],["重官美货","高官厚禄与财物"],["兵不血刃","没有拼杀就取胜"]],"think":["傅颜认为“宜急攻之，以省千金之费”，恪却不同意。从成本角度看，谁更合理？","短期看，急攻可以省钱省时；长期看，伤亡会导致兵源与士气损耗，也会让后续作战更难。恪的判断前提是对手“内无蓄积，外无强援”，所以等得起。如果对手有援军、有补给，傅颜的观点就更正确。判断标准是“对手能否被拖死”，而不是“时间成本”。"],"quiz":[["恪认为什么情况下应当急攻？",["敌我势均、敌有强援、己方担心腹背受敌","敌人兵少","天气有利"],"“若彼我势均，且有强援，虑腹背之患者，须急攻之。”"],["围野王时，恪用来瓦解守军的办法是？",["以重官美货间而离之","断水断粮","强攻城门"],"“吾严浚围垒，休养将卒，以重官美货间而离之。”"],["围广固时恪对部下说“恐伤吾士众”的含义？",["不愿因急攻造成不必要的伤亡","怕敌人逃跑","担心粮草不足"],"“但恐伤吾士众……亦何宜轻残人命乎！当持久以取耳。”"]],"cards":[["恪的“急缓之辨”？","势均有援则急；我强彼弱、无援则羁縻以待其毙。"],["野王之围持续多久？","自三月至八月。"]],"line":["军势有宜缓以克敌，有宜急而取之","决定项目节奏时可以引：军势有宜缓以克敌，有宜急而取之——先判断对手有无援兵。"],"tags":["慕容恪","前燕","战例"]},"zhuyan_zhema_bian":{"intro":"同一位君主，对先祖的名马和对前朝的僵尸，做了截然不同的两件事：为赭白马铸铜、亲撰铭赞，为梦中被咬而发石季龙之墓、鞭尸弃漳水。这两段摘自慕容儁载记，不加评语，却能让读者看到他重仪式、重象征，也有残酷的一面。","focus":["赭白马的故事先写灵验：石季龙攻棘城时，皝想骑它出逃，“马悲鸣踶啮，人莫能近”，皝说“此马见异先朝……今不欲者，盖先君之意乎”，于是留下，“季龙寻退，皝益奇之”。这是以“先君之意”解释马的反应，把一匹马写成保护者。再说它“四十九岁矣，而骏逸不亏”，马的年龄数字出奇长，当属夸张或志怪，存疑。","儁“比之于鲍氏骢，命铸铜以图其象，亲为铭赞，镌勒其旁，置之蓟城东掖门”，最后“象成而马死”。公共雕像、君主亲撰铭文、置于宫门，做的是一件政治纪念物：纪念慕容氏历代的“先君之意”，也宣示迁都蓟城后继续承接龙城的传统。","鞭尸则是另一类“仪式”：儁“夜梦石季龙啮其臂，寤而恶之，命发其墓，剖棺出尸，蹋而骂之曰：死胡安敢梦生天子”，还派御史中尉阳约“数其残酷之罪”，鞭后“弃于漳水”。数罪、鞭尸、弃水，一整套程序，说明他处理恐惧的方式是公开化、程序化的惩罚。史官只记行为，不下评语，读者可自行判断。"],"notes":[["赭白","毛色赭白的骏马，廆所养"],["逸力","超常的奔跑力量"],["踶啮","踢咬"],["先君之意","已故先主的意愿"],["鲍氏骢","古代名马之一，儁用来比赭白"],["铭赞","刻在器物或雕像上的颂文"],["东掖门","宫城东边的侧门"],["蓟城","今北京一带，儁迁邺前的都城"],["啮其臂","咬他的手臂"],["发其墓","挖开坟墓"],["御史中尉","负责纠察的官员"],["数其残酷之罪","一条条列举其残忍罪行"]],"think":["儁对一匹马“铸铜图象”，对一具尸体“剖棺鞭之”，这两件事是否有共同的逻辑？","共同点是“把情绪转化为公共仪式”。纪念先祖与惩罚旧敌，都需要一个物质的承载：铜像、棺尸。区别在于一个是荣誉，一个是羞辱。史书保留这两条，可能是为了呈现他的两面：有文化、有仪式感，也有执念与暴戾。"],"quiz":[["皝为什么没有骑赭白马出避难？",["马悲鸣踶啮，他认为是先君之意","马已经老死","道路被封"],"“马悲鸣踶啮，人莫能近。皝曰：此马见异先朝……盖先君之意乎！”"],["儁为这匹马做了什么？",["铸铜像并亲撰铭赞，置于蓟城东掖门","杀马祭天","赐予功臣"],"“命铸铜以图其象，亲为铭赞，镌勒其旁，置之蓟城东掖门。”"],["儁为何发石季龙墓？",["夜梦石季龙咬他的手臂，醒后厌恶","为了寻找玉玺","为了安葬"],"“夜梦石季龙啮其臂，寤而恶之，命发其墓，剖棺出尸。”"]],"cards":[["赭白马的结局？","铜像造成之年，马死。"],["儁对石虎尸体的处理程序？","发墓、剖棺、踏骂、遣人数罪、鞭尸、弃漳水。"]],"line":["死胡安敢梦生天子","此句很难直接套用，更适合作为“情绪外化”的案例：当领导者的恐惧被公开化为惩罚时，团队会读出什么？"],"tags":["慕容儁","前燕","人物"]},"zhuyan_liugui":{"intro":"两段材料都写儁对并州一带的经略：一段写李历、张平等垒壁势力“两头下注”，儁用军事与官爵分化他们；另一段写儁欲大发兵经略关西，武邑人刘贵上书极谏，儁“览而悦之”。前者是对强者的统战，后者是对谏言的处理。","focus":["张平等人对前燕的态度是典型的“羁縻自固”：对儁“称藩，遣子入侍”，又“投款建邺，结援苻坚，并受爵位”，所以“贡使不绝，而诚节未尽”。张平“跨有新兴、雁门、西河、太原、上党、上郡之地，垒壁三百余，胡晋十余万户，遂拜置征、镇，为鼎跱之势”，实际是一个自立的小政权。","儁的办法是军事与官爵并行：“遣其司徒慕容评讨平，领军慕舆根讨鸯，司空阳骛讨昌，抚军慕容臧攻历”，四路并出；同时以悦绾为并州刺史“以抚之”，对投降者“皆复其官爵”。“并州垒壁降者百余所”，“平所署征西诸葛骧……率垒壁百三十八降于儁”。先破其核心，再保留其中层官员，是比较高明的统战手法。","征兵一节更值得读：儁“欲使步卒满一百五十万”，令“率户留一丁，余悉发之”，数字夸张，存疑。刘贵上书说“百姓凋弊，召兵非法，恐人不堪命，有土崩之祸”，并陈“时政不便于时者十有三事”。儁的反应是“览而悦之，付公卿博议，事多纳用，乃改为三五占兵，宽戎备一周”，没有取消，只调整节奏。“三五占兵”的具体算法史文未详。"],"notes":[["称藩","自称藩属，向上国称臣"],["入侍","派子弟入朝侍奉，等于人质"],["羁縻自固","用笼络周旋的方法保护自己"],["垒壁","乡村中以垒、壁自保的武装据点"],["鼎跱","像鼎的三足并立，指势力对峙"],["领护匈奴中郎将","负责管理匈奴等部族的官职"],["校阅见丁","检查现有壮丁"],["精覆隐漏","仔细核查隐瞒的户口"],["土崩之祸","国家像土墙一样崩塌的灾祸"],["凋弊","凋敝困苦"],["三五占兵","改定后的征兵办法，具体比例史文未详"],["季冬","冬天的最后一个月"]],"think":["儁对刘贵“览而悦之”，却没有取消征兵，只是“宽戎备一周”。这算纳谏吗？","算部分采纳：谏言击中的是“召兵非法”“人不堪命”，儁改“率户留一丁，余悉发之”为“三五占兵”，并延长一年，已经减轻了压力；但“明年季冬赴集邺都”的目标没变。判断是否纳谏，要看对象是目标还是手段：手段改了，目标仍在。"],"quiz":[["张平等人对儁“诚节未尽”的表现是？",["一边称藩入侍，一边向建邺、苻坚结援受爵","拒绝朝贡","起兵反抗"],"“既而投款建邺，结援苻坚，并受爵位，羁縻自固，虽贡使不绝，而诚节未尽。”"],["平定张平之后，对降者的政策是？",["皆复其官爵","全部迁往邺城","悉数遣散"],"“平所署征西诸葛骧……率垒壁百三十八降于儁，儁大悦，皆复其官爵。”"],["刘贵上书谏征兵，说最大的风险是？",["百姓不堪命，有土崩之祸","粮食不足","邻国趁虚而入"],"“召兵非法，恐人不堪命，有土崩之祸。”"]],"cards":[["张平的势力规模？","跨有六郡之地，垒壁三百余，胡晋十余万户。"],["“三五占兵”是什么？","儁采纳刘贵意见后改定的征兵办法，史文未详算法。"]],"line":["召兵非法，恐人不堪命，有土崩之祸","评估一项高强度动员政策时可以引：召兵非法，恐人不堪命——先看承受能力，再谈目标。"],"tags":["慕容儁","前燕","谏言"]},"zhuyan_xiaoxue":{"intro":"儁在蒲池宴群臣，谈到太子晔之死，潸然流涕，向司徒左长史李绩问先太子的为人，又问新立的太子暐怎样。李绩先赞后抑，儁转身对暐说：“伯阳之言，药石之惠，汝宜戢之。”这一段把前燕的继承困境放在一场宴会里写完。","focus":["儁的开场是自我反省：“昔魏武追痛仓舒，孙权悼登无已，孤常谓二主缘爱称奇，无大雅之体。自晔亡以来，孤须发中白，始知二主有以而然。”他借历史典故讲私人的悲痛，又担心“得无贻怪将来”，说明他在乎史书与后人怎么看。","李绩“先太子大德有八”：至孝、聪敏、沉毅、疾谀亮物、好学、英姿、虚襟、轻财，每一条都落在行为上。儁说“卿言亦以过矣”，他仍照说。这一份称赞有两层意图：满足儁对亡子的追念，也为后面的比较做铺垫。","关键是儁自问：“吾既不能追踪唐虞，官天下以禅有德，近模三王，以世传授。景茂幼冲，器艺未举，卿以为何如？”李绩回答：“皇太子天资岐嶷，圣敬日跻，而八德阒然，二阙未补，雅好游田，娱心丝竹，所以为损耳。”“八德阒然”四个字，是对比，也是批评。儁当场顾谓暐：“伯阳之言，药石之惠，汝宜戢之。”这不是教育，是当着群臣说明：继承人需要补课。"],"notes":[["小学","教育贵族子弟的学校"],["胄子","贵族子弟"],["蒲池","邺城宫中池苑"],["周太子晋","传说周灵王太子，早逝"],["仓舒","曹操之子曹冲的字，早亡"],["大雅之体","稳重得体的君子风度"],["献怀","已故太子晔的谥号"],["中庶子","太子属官，负责陪侍和辅导"],["官天下","把天下当作公器，传给有德之人"],["岐嶷","幼年聪慧"],["药石之惠","像药和针石一样治病的益处，指直言规劝"],["游田","游乐与狩猎"]],"think":["李绩没有直接说“太子不如先太子”，却说“八德阒然，二阙未补”。这种说法的好处与风险是什么？","好处是既不否定现任太子的名位，又让儁听出差距；风险是“二阙”只指出两个问题——游田与丝竹——可能让儁低估问题的严重性。劝谏要在说实话与保护关系之间找平衡，用对比和具体缺点而不是总体评价。"],"quiz":[["儁在宴会上因为什么流泪？",["太子晔去世后，想起周太子晋之事","边境失利","宗室叛乱"],"“语及周太子晋，潸然流涕”，之后说起自晔亡以来的悲痛。"],["李绩对暐的批评是？",["八德阒然，二阙未补，雅好游田，娱心丝竹","不孝","不识字"],"“而八德阒然，二阙未补，雅好游田，娱心丝竹，所以为损耳。”"],["儁最后对暐说了什么？",["伯阳之言，药石之惠，汝宜戢之","好自为之","从此不必再问"],"“伯阳之言，药石之惠，汝宜戢之。”伯阳是李绩的字。"]],"cards":[["李绩所说的“八德”？","至孝、聪敏、沉毅、疾谀、好学、英姿、虚襟、轻财。"],["儁说“吾既不能追踪唐虞”指什么？","他承认自己不能禅让给有德之人，只能世传给子嗣。"]],"line":["伯阳之言，药石之惠，汝宜戢之","给新人转述一位前辈的批评时可以说：药石之惠，汝宜戢之——不好听，但有用。"],"tags":["慕容儁","前燕","继承"]},"zhuyan_muyu_gen":{"intro":"慕容儁死，群臣欲立慕容恪，恪辞；暐继位，恪辅政，“行周公事”。不久，太师慕舆根劝恪废暐自立，恪斥其“公醉乎”，并劝垂“且可容忍之”；根转而与慕舆干密谋诛恪与评，反被暐一句话看穿，被斩于禁中。这一段是前燕最险的一次政治危机。","focus":["恪的两次拒绝：一是群臣欲立恪，“恪辞曰：国有储君，非吾节也”；二是根劝“兄亡弟及，先王之成制”，恪回答“公醉乎？何言之勃也！昔曹臧、吴札并于家难之际，犹曰为君非吾节，况今储君嗣统，四海无虞，宰辅受遗，奈何便有私议！”他把兄终弟及的鲜卑传统与汉家让国的典故两边都堵上了。","恪不立刻杀根，是出于政治成本的算计：“今新遭大凶，二虏伺隙，山陵未建，而宰辅自相诛灭，恐乖远近之望，且可容忍之。”垂劝杀，恪不允。根的论证很有技巧：先提“杨骏、诸葛元逊之变”，让恪害怕被清算；再讲“兄亡弟及”，给恪合法性。这是同一份名单里，把恐惧与野心装在一起。","转折在暐：根“入白可足浑氏及暐”，说太宰太傅谋乱，请率禁兵诛之，可足浑氏“将从之”，暐却说“二公国之亲穆，先帝所托，终应无此，未必非太师将为乱也”。于是使皇甫真、傅颜“收根等，禁中斩之”。一个被称作“庸弱”的君主，在这一刻做了正确判断。随后“遣傅颜率骑二万观兵河南，临淮而还，军威甚盛”，是以对外示威巩固内部。"],"notes":[["储君","已经确定的继承人"],["太宰","最高辅政官职，恪任"],["录尚书","总领尚书台事务"],["周公","周初辅佐成王的重臣，辅政的典范"],["杨骏","西晋外戚辅政，被诛杀"],["诸葛元逊","即诸葛恪，三国吴辅政大臣，被杀"],["兄亡弟及","兄死后由弟继承的制度，鲜卑旧俗"],["山陵","帝王陵墓，这里指先帝的丧葬"],["曹臧","春秋曹国公子，让位于国"],["禁兵","宫中守卫的军队"],["亲穆","亲近而和睦的宗室"],["观兵","陈兵示威"]],"think":["恪明知慕舆根有异心，为什么选择“容忍”？这个选择的得失是什么？","得：避免“宰辅自相诛灭”的乱象，在国丧初期稳定政局，并让根自己暴露；失：给了根组织力量的时间。成功的原因是恪判断“根不会立刻动手”、暐与可足浑氏之间的关系也在他的计算中。风险偏大，但在当时的内外压力下合乎逻辑。"],"quiz":[["恪对根的“废主”建议如何回应？",["斥其醉言，引曹臧、吴札为君非吾节之例","默许","立即处死"],"“公醉乎？何言之勃也！昔曹臧、吴札……犹曰为君非吾节。”"],["垂劝恪诛根，恪为何不同意？",["新遭大凶，二虏伺隙，担心宰辅相诛失去远近之望","根的党羽太多","根是宗室"],"“今新遭大凶，二虏伺隙，山陵未建，而宰辅自相诛灭，恐乖远近之望。”"],["暐如何识破根的诬告？",["他说“未必非太师将为乱也”","他搜出了证据","有人告发"],"“二公国之亲穆，先帝所托，终应无此，未必非太师将为乱也。”"]],"cards":[["“为君非吾节”出自谁？","曹臧、吴札让国的典故，恪借以拒绝废主。"],["根最终下场？","被皇甫真、傅颜收捕，斩于禁中。"]],"line":["国有储君，非吾节也","被推到本不该坐的位置时，可以用这句话拒绝：国有储君，非吾节也——先守分，再论事。"],"tags":["慕容恪","前燕","政变"]},"zhuyan_ke_zhuan":{"intro":"慕容恪死后，前燕再没有一个能稳住朝局的人。这四段选自《慕容恪传》：少年得授兵、根诛后“一人步从”的镇静、治军“密纵舍之”的手法，以及临终荐垂。读它们，可以明白恪为什么被后人称为前燕的支柱。","focus":["少年部分要看对比：“母高氏无宠，皝未之奇也”，十五岁身长八尺七寸，“皝始异焉，乃授之以兵”。伐夫余时“儁居中指授而已，恪身当矢石，推锋而进，所向辄溃”，一句话写出皝、儁、恪三人的位置，也为后来的权力格局作了注脚。","镇静之术：慕舆根被诛后“内外危惧”，恪“容止如常，神色自若，出入往还，一人步从”，有人劝他防备，他说“人情怀惧，且当自安以靖之。吾复不安，则众何瞻仰哉！”执政者的神情本身就是一种政策；同时“每事必咨之于评”，在外表上保持对评的尊重，也是保持平衡。","治军与遗言：“专以恩信御物，务于大略，不以小令劳众。军士有犯法，密纵舍之，捕斩贼首以令军。”小过私下放过，大罪公开处置。临终他对暐说“报恩莫大荐士”，推荐吴王垂为“管萧之亚”，并警告“二寇必有窥之计”。后来垂被评排挤、奔秦，前燕被秦所灭，这段话几乎成为《晋书》本卷的伏笔。"],"notes":[["谨厚","谨慎厚道"],["沈深","沉稳深邃"],["推锋","冲锋在前"],["容止","仪容举止"],["色养","和颜悦色地奉养父母"],["手不释卷","书不离手，形容勤学"],["恩信御物","用恩惠与信用管理下属"],["密纵舍之","私下放过"],["荐士","举荐人才"],["板筑","筑墙用的夹板与夯杵，指傅说、版筑出身之贤"],["懿藩","美好的藩屏，指宗室亲王"],["二寇","指前秦与东晋"]],"think":["恪“军士有犯法，密纵舍之”，这种做法为什么不会削弱军纪？","前提是“捕斩贼首以令军”：真正危害集体的人公开处置，起到震慑；一般过失则私下处理，保存士气与面子。关键在于分类——区分偶发与恶意。若连首恶也私放，就是纵容；若连小过也公开，就是苛刻。恪的做法是在两者之间划线。"],"quiz":[["慕舆根被诛后，恪稳定人心的方法是？",["神色自若、出入一人步从","加派禁卫","闭门不出"],"“恪容止如常，神色自若，出入往还，一人步从。”"],["恪治军对待犯法的士兵是？",["密纵舍之，捕斩贼首以令军","一律斩杀","全部鞭笞"],"“军士有犯法，密纵舍之，捕斩贼首以令军。”"],["恪临终荐的是谁？",["吴王垂","慕容评","慕容德"],"“吴王文武兼才，管萧之亚，陛下若任之以政，国其少安。”"]],"cards":[["恪遗言中的预警？","二寇必有窥之计。"],["“报恩莫大荐士”什么意思？","最大的报恩是为国家举荐人才。"]],"line":["人情怀惧，且当自安以靖之","团队出现恐慌时可以引：且当自安以靖之——领导者先稳，众人才有依凭。"],"tags":["慕容恪","前燕","人物"]},"zhuyan_deshangshu":{"intro":"苻謏据陕降燕，前秦主力被牵制，燕国本有一次西进关中的良机。慕容德上疏，要求趁机“兼弱攻昧，取乱侮亡”；暐“览表大悦，将从之”，却被慕容评“固执不许”。苻謏知道燕朝无远略，又写信给垂与皇甫真，垂私下说出了“方为人患者必在于秦”。这是前燕错失关西的一幕。","focus":["评的两句话把问题推开：“秦虽有难，未易可图。朝廷虽明，岂如先帝，吾等经略，又非太宰之匹，终不能平秦也。但可闭关息旅，保宁疆埸足矣。”前半句用恪的缺位当理由，后半句主张保守。史官在他名字前加了一句背景：“素无经略，又受苻坚间货”，所以这不是单纯的保守，是被贿赂的保守。","德的上疏层次分明：先用“昔周文既没，武王嗣兴”鼓励暐，再说“逆氐僭据关陇……自相疑戮，衅起萧墙”，接着给出判断“兼弱攻昧，取乱侮亡，机之上也”，最后布置三路：皇甫真“径趣蒲坂”，垂“驰解谟围”，评“总京都武旅，为二军后继”，并以“飞檄三辅，仁声先路，获城即侯，微功必赏”配合。结尾“天与不取，反受其殃”几乎成了谶语。","收尾极有力：暐同意，评否决，“乃止”。苻謏的信写到垂与真：“苻坚、王猛皆人杰也，谋为燕患，为日久矣。”垂私下对真说“观太傅度略，岂能抗苻坚、王猛乎”，真答“绕朝有云，谋之不从可如何”。明白的人有话语，却没有决策权——前燕灭亡的结构性原因，被这几句写尽。"],"notes":[["图书","谶纬类的书籍，这里指“燕马当饮渭水”的预言"],["关右","函谷关以西，关中地区"],["经略","筹划、治理"],["间货","离间用的财物"],["沮议","阻挠议事"],["兼弱攻昧","兼并弱者，攻打昏昧者"],["取乱侮亡","夺取混乱之国，欺凌将亡之国"],["牧野之旗","周武王在牧野灭商时的旗帜，喻大举征伐"],["蒲坂","地名，在今山西永济一带"],["三辅","长安周围的三个行政区，泛指关中"],["绕朝","春秋秦国人，谋划不被晋使采纳，叹“谋之不从”"],["甬东之悔","春秋越灭吴后吴王夫差被迁甬东，喻亡国的后悔"]],"think":["评为何能一句话否决两位王侯的建议？说明了前燕决策结构的什么问题？","表面是评坚持“保宁疆埸”，实质是他控制着朝廷的最后决定权，而暐“将从之”却没有执行力。皇帝庸弱、权臣贪墨、能者无权，三者叠加，使得再好的战略也变成空谈。判断一个政权的风险，不仅要看主张什么，还要看谁有权让主张落地。"],"quiz":[["慕容评反对西进的理由是？",["秦未易图，朝廷无经略，不如闭关息旅","兵力不足","天时不利"],"“秦虽有难，未易可图……但可闭关息旅，保宁疆埸足矣。”"],["德建议的三路布置中，垂负责？",["驰解谟围","径趣蒲坂","总京都武旅"],"“臣垂引许洛之兵，驰解谟围。”"],["暐对德的上疏有什么反应？",["览表大悦，将从之，评固执不许，乃止","立即出兵","毫无反应"],"“暐览表大悦，将从之。评固执不许，乃止。”"]],"cards":[["德所提战略的核心判断？","兼弱攻昧，取乱侮亡，机之上也。"],["垂与真私下的结论？","秦必为燕患，谋之不从，无可如何。"]],"line":["天与不取，反受其殃","面对一个稍纵即逝的窗口期，可以引：天与不取，反受其殃——但前提是有人真正拍板。"],"tags":["慕容德","前燕","战略"]},"zhuyan_qishi":{"intro":"桓温逼枋头，前燕向前秦乞师，答应割虎牢以西之地；事成之后，慕容暐又反悔，反让苻坚借口出兵。这一段连带写王猛劝苻坚杀慕容垂不成，苻坚署垂为冠军将军并以为乡导，攻下洛阳。前燕灭亡的外部链条，从这里开始。","focus":["“请割武牢以西之地”是乞师的价码，“苻坚亦欲与暐连横”是秦的考虑，两方各有算盘。事后暐“悔割武牢之地”，遣使谓坚“顷者割地，行人失辞”，把承诺归咎于使者失言。前一步“分灾救患，理之常也”也说得很勉强。苻坚“大怒”，等于得到了一个出兵的理由。","王猛劝杀垂的话很具体：“慕容垂，燕之戚属，世雄东夏，宽仁惠下，恩结士庶，燕赵之间咸有奉戴之意。观其才略，权智无方，兼其诸子明毅有干艺，人之杰也。蛟龙猛兽，非可驯之物，不如除之。”苻坚却说“吾方以义致英豪，建不世之功”。这一念之仁，是前秦后来不得不面对垂的伏笔。","战役节奏：猛与梁成、邓羌率三万人，苻坚特意“署慕容垂为冠军将军，以为乡导”攻洛阳；暐遣慕容臧率“精卒十万”，猛只派梁成“以精锐万人卷甲赴之，大破臧于荥阳”，筑“惧而请降”，猛“陈师以受之，留邓羌镇金墉，猛振旅而归”。数字是史文，兵力对比可能有夸张，但“以少击多”的格局是清楚的。"],"notes":[["枋头","桓温北伐被燕军击败之地"],["乞师","请求出兵援助"],["武牢","即虎牢关，在今河南荥阳西北"],["连横","联合邻国共同行动"],["世雄东夏","世代雄踞东方"],["蛟龙猛兽","蛟龙与猛兽，难以驯服"],["不世之功","世上少有的大功"],["行人失辞","使者说错话，借口推脱承诺"],["分灾救患","邻国之间共同承担灾难，互相救助"],["乡导","向导"],["卷甲","收起铠甲轻装疾行"],["振旅","整顿军队凯旋"]],"think":["苻坚说“吾方以义致英豪，建不世之功”，这是真心的价值观，还是对猛的托词？","两者交织：苻坚的行为模式始终偏向“以德怀远”，对降者多宽容，这是其政治风格；同时“且其初至，吾告之至诚”表明他不愿背弃刚做的承诺。但这种“义”在乱世里代价极高。史书保留猛的劝告，是为了让读者看到决策的另一种可能。"],"quiz":[["前燕乞师的代价是？",["割武牢以西之地","献出传国玺","派质子"],"“请割武牢以西之地。”"],["苻坚拒绝杀垂，理由是？",["吾方以义致英豪，建不世之功","垂已被软禁","垂有秦将保护"],"“吾方以义致英豪，建不世之功。且其初至，吾告之至诚，今而害之，人将谓我何！”"],["苻坚攻洛阳时，让垂担任？",["冠军将军并充当乡导","统帅","留守"],"“署慕容垂为冠军将军，以为乡导。”"]],"cards":[["暐悔约的借口？","“顷者割地，行人失辞”。"],["王猛评垂？","蛟龙猛兽，非可驯之物，不如除之。"]],"line":["蛟龙猛兽，非可驯之物，不如除之","评估一位能力过强又不受控的合作者时，可以参考这句判断，但要看清自己是否有驾驭的资源。"],"tags":["苻坚","前燕","枋头"]},"zhuyan_liangchen":{"intro":"前燕使节梁琛出使长安，苻坚打算在畋猎的地方接见，梁琛拒绝，坚持“设行宫”才见。这一段《资治通鉴》写出一场礼仪之争：名分、礼制、外交身份都在几句话里。更重要的是，梁琛在答苻坚“东朝名臣为谁”时，说出“官皆称职，野无遗贤”，与国内实际形成鲜明对比。","focus":["梁琛的拒绝说得很有分寸：先说燕国接秦使的礼节（“朝服备礼，洒扫宫庭，然后敢见”），再说“今秦王欲野见之，使臣不敢闻命”；辛劲的反驳用“乘舆”“行在所”“春秋遇礼”，琛回答“今寓县瓜裂，天光分曜，安得以乘舆、行在为言哉”。他把对方的“天子无所不在”还给对方：若你以天子自居，就该按国使之礼；若不以天子自居，也不能随便见使。","结果：“坚乃为之设行宫，百僚倍位，然后延客，如燕朝之仪。”苻坚让步，可见他重视这次接触——想听消息，也想显示度量。随后“私宴”中问东朝名臣，琛列举“太傅上庸王评”“车骑大将军吴王垂”，结论是“官皆称职，野无遗贤”。","对照同一事件的另一面：本卷另一处写评“贪昧无厌”，垂被排挤，暐朝廷“政以贿成”。梁琛对外的夸奖与国内情形差距巨大，这是外交辞令与国势实情的对照。他随后回国警告“秦人日阅军旅，为和必不能久”，不被采纳，这在同书与《晋书》都有记载。"],"notes":[["万年","地名，在今陕西西安一带"],["乘舆","天子出行时所乘之车，代指皇帝"],["行在所","皇帝所在之处"],["遇礼","不期而遇的简略礼节"],["寓县瓜裂","天下像瓜一样被割裂"],["天光分曜","日月之光分别照耀，喻天下有两个中心"],["二方承运","两个政权都承受天命"],["行宫","临时设立的宫室"],["倍位","增加站位的人数，提升仪式规格"],["折冲御侮","击退敌人，抵御外侮"],["东朝","东方的朝廷，指前燕"],["野无遗贤","民间没有被遗漏的贤才"]],"think":["梁琛对苻坚说“野无遗贤”，是外交客套，还是故意误导？这样说有什么得失？","从使节立场看，维护国家体面是第一职责，说“官皆称职”并不奇怪；但在私宴中夸大国力，也可能给对方一个错误判断：苻坚会因此更谨慎，也可能因此更警觉。不同的后果取决于对方怎么解读。作为读者，要把使节的话当作“表态”，把国内记载当作“实情”。"],"quiz":[["梁琛拒绝“野见”的理由是？",["燕朝礼待秦使，秦主不能草率接见","他生病","路途太远"],"“秦使至燕，燕之君臣朝服备礼，洒扫宫庭，然后敢见。今秦王欲野见之，使臣不敢闻命！”"],["梁琛怎样反驳“天子行曰乘舆，止曰行在”？",["寓县瓜裂，天光分曜，不能一概而论","承认并让步","拒绝回答"],"“今寓县瓜裂，天光分曜，安得以乘舆、行在为言哉！”"],["苻坚最后怎样接见梁琛？",["设行宫，如燕朝之仪","在野外接见","派他人代见"],"“坚乃为之设行宫，百僚倍位，然后延客，如燕朝之仪。”"]],"cards":[["梁琛对苻坚介绍的东朝名臣？","太傅上庸王评、车骑大将军吴王垂。"],["“寓县瓜裂，天光分曜”的意思？","天下分裂，各有天命，不能再说天子无所不在。"]],"line":["官皆称职，野无遗贤","对外介绍团队时常说的话，可以改写为：官皆称职，野无遗贤——但要先检查是不是真的。"],"tags":["前燕","外交","苻坚"]},"zhuyan_shenshao":{"intro":"尚书左丞申绍在前燕灭亡前夕上疏，从官吏、赋役、奢靡、边防四方面指出时弊。内容全面而具体，几乎每一条都被后来的失败证明。这是十六国时期少见的、系统的内政诊断，值得与《通鉴》的节录对读。","focus":["官吏问题：“守宰或擢自匹夫兵将之间，或因宠戚，藉缘时会，非但无闻于州闾，亦不经于朝廷。又无考绩，黜陟幽明。贪惰为恶，无刑戮之惧；清勤奉法，无爵赏之劝。”他的逻辑是：用人没有标准，考核没有制度，结果赏罚失效。再讲“吏多则政烦”，主张“并官省职，务劝农桑”。","赋役与兵役：“郡县守宰每于差调之际，无不舍越殷强，首先贫弱，行留俱窘，资赡无所，人怀嗟怨，遂致奔亡。”也就是税役落到最穷的人身上，富者被放过，穷者逃亡，兵源枯竭。他的办法是“严制军科，务先饶复，习兵教战，使偏伍有常”，核心是“兵岂在多，贵于用命”。","奢靡与边防：“后宫四千有余，僮侍冢养通兼十倍，日费之重，价盈万金……今帑藏虚竭，军士无襜褕之赉，宰相侯王迭以侈丽相尚。”接着建议收缩北边孤立据点，“宜摄就并豫，以临二河”，增重晋阳与南藩之兵，“蓄力待时，可一举而灭”，并预期“温猛之首可悬之白旗”。他指的是桓温与王猛，结局却是自己的国家被王猛灭了。"],"notes":[["良二千石","称职的郡守，二千石是郡守的俸禄级别"],["贡士","地方向朝廷推荐的人才"],["考绩","对官员政绩的考核"],["黜陟幽明","贬退昏庸、提拔贤明"],["吏多则政烦","官吏多了政务反而繁杂"],["差调","征派赋役"],["舍越殷强","放过富豪强势之家"],["兵岂在多，贵于用命","军队不在于数量多，而在于肯拼命"],["帑藏","国库"],["襜褕","一种长衣，这里指给军士的衣物赏赐"],["倾宫之女","后宫众多的美女，用来说明奢靡"],["温猛","桓温与王猛"]],"think":["申绍的上疏“全面而具体”，为什么没有被采用？这对理解前燕灭亡有什么启示？","条陈涉及官吏、军制、后宫、边防，每一条都会触动既得利益者：评、可足浑氏、宗室、将领。没有一位拥有足够权力的执政者来推行，上疏只能停在纸上。恪若在世，也许会实施；他去世后，这样的诊断只能成为“事后的预言”。"],"quiz":[["申绍指出守宰制度的核心问题是？",["选用无标准、考核不严，使赏罚失效","俸禄过低","官职太少"],"“又无考绩，黜陟幽明。贪惰为恶，无刑戮之惧；清勤奉法，无爵赏之劝。”"],["他对“兵”的主张是？",["兵岂在多，贵于用命","多多益善","应该裁撤"],"“兵岂在多，贵于用命。宜严制军科，务先饶复。”"],["疏中“温猛之首可悬之白旗”，“温猛”指？",["桓温与王猛","桓温与慕容垂","王猛与苻坚"],"“温猛之首可悬之白旗，秦吴二主可以礼之归命。”"]],"cards":[["申绍对后宫开支的描述？","后宫四千有余，日费价盈万金，帑藏虚竭，军士无襜褕之赉。"],["他对赋役的批评？","差调之际舍越殷强，首先贫弱，使人怀怨奔亡。"]],"line":["兵岂在多，贵于用命","做团队建设与人员规模决策时可以引：兵岂在多，贵于用命——人数不是第一指标。"],"tags":["前燕","内政","谏言"]},"zhuyan_luchuan":{"intro":"前秦以王猛、杨安伐燕，慕容评率四十余万人迎战，对阵潞川。《晋书》写朝廷怎样轻敌、评怎样“卖樵鬻水”失去军心，《资治通鉴》另写王猛与邓羌在阵前讨价还价、最后单骑冲阵。两书合读，战役的政治层面与战场层面都能看到。","focus":["暐的判断失误出现在开战之前。他问使者“秦众何如”，有人回答“秦国小兵弱，岂王师之敌，景略常才，又非太傅之匹”。梁琛、乐嵩反驳“计敌能鬭，当以算取之，若冀敌不鬭，非万全之道”，并说“秦行师千里，固战是求，何不战之有乎”，暐的反应是“不悦”。决策者喜欢听乐观的话，这是失败的起点。","评的战略其实不错：“以猛悬军远入，利在速战，议以持久制之。”但他“性贪鄙，鄣固山泉，卖樵鬻水，积钱绢如丘陵，三军莫有鬭志”。王猛“遣其将郭庆率骑五千，夜从间道起火高山，烧评辎重，火见邺中”，一把火烧到了邺城。暐遣兰伊斥责“皮之不存，毛将安傅”，评“惧而与猛战”，“死者五万余人”。这是战术正确、政治失败的典型。","《通鉴》里的邓羌一段更像戏剧：猛说“非将军不能破劲敌”，羌要“司隶”，猛说“必以安定太守、万户侯相处”，羌“不悦而退”；开战后猛召羌，羌“寝弗应”，猛“驰就许之”，羌“乃大饮帐中”，与张蚝、徐成“跨马运矛，驰赴燕陈，出入数四，旁若无人”。这说明前秦将领也有私利算计，王猛的处理是灵活让步；同时两书对战果的记法不同：《晋书》“死者五万余人”，《通鉴》“俘斩五万余人……所杀及降者又十万余人”。"],"notes":[["潞川","地名，在今山西长治一带，燕秦决战处"],["壶关","太行山要隘，王猛进攻处"],["中外精卒","朝廷与地方的精锐部队"],["景略","王猛的字"],["计敌能鬭","估算敌人能不能战斗"],["悬军","孤军深入、没有后援的军队"],["间道","隐蔽的小路"],["辎重","军队的粮草器械"],["鄣固山泉","封锁并独占山泉水源"],["卖樵鬻水","把柴与水卖给士兵"],["皮之不存，毛将安傅","皮都没有了，毛附在哪里；比喻根本丧失，枝节无依"],["跨马运矛","骑在马上舞动长矛"]],"think":["评的“持久制之”策略本身正确，为什么还是败了？说明了什么？","战略方向不等于执行条件：持久需要后勤、士气和统帅的威信，而评“卖樵鬻水”把这三项全毁了。再者，持久之策依赖于朝廷对前线的支持，暐派人训斥又逼评出战，决策链断裂。读战争，要同时看战略、组织、人心三层。"],"quiz":[["评以什么办法对付王猛？",["利用其悬军远入，议持久制之","立刻决战","撤回邺城"],"“评以猛悬军远入，利在速战，议以持久制之。”"],["王猛烧评辎重的办法是？",["遣郭庆率五千骑夜从间道起火","水攻","间谍纵火"],"“夜从间道起火高山，烧评辎重，火见邺中。”"],["《通鉴》中邓羌答应出战前提的条件是？",["猛许以司隶或安定太守、万户侯","加官进爵为公","赐美女"],"“若能以司隶见与者，公勿以为忧。”猛答“必以安定太守、万户侯相处”。"]],"cards":[["暐斥评的话？","“皮之不存，毛将安傅！”"],["潞川之战的结果（《晋书》）？","评师大败，死者五万余人，评单骑遁还。"]],"line":["皮之不存，毛将安傅","劝人别为眼前小利损伤根本时，可以引：皮之不存，毛将安傅——先保根基。"],"tags":["前燕","前秦","战例"]},"zhuyan_ye_xian":{"intro":"邺城陷落，慕容暐出奔昌黎，被苻坚部将巨武在高阳擒获。他回答苻坚的质问时说“狐死首丘”，苻坚“哀而释之”。随后暐被迁长安，封新兴侯，最终因谋杀苻坚响应垂、冲被诛。这是前燕的最后一幕，也是慕容氏复国叙事的起点。","focus":["出奔与被擒：暐“与评等数十骑奔于昌黎”，是想回辽西旧地。被郭庆追及，部将巨武要缚他，暐说“汝何小人，而缚天子”，武说“我梁山巨武，受诏缚贼，何谓天子邪”。一句话写出两个名分：被缚者仍以天子自居，缚者只认本国诏书，各有各的合法性。","对苻坚的回答是“狐死首丘，欲归死于先人坟墓耳”，用古语写出回归故土之意；苻坚“哀而释之，令还宫率文武出降”。这是一种体面的投降仪式：坚借“哀”表示宽仁，暐借“首丘”保存尊严。之后“徙暐及其王公已下并鲜卑四万余户于长安”，封暐新兴侯，署尚书，是把整个统治集团迁离故地的老办法。","结局：淝水之败后，暐“随坚还长安”，听说垂攻邺、冲起兵关中，“谋杀坚以应之，事发，为坚所诛，时年三十五”。南燕慕容德称帝后追谥“幽皇帝”。史官在“及德僭称尊号，伪谥幽皇帝”中使用“伪”字，是唐初修史对十六国政权的统一称呼。"],"notes":[["沙亭","地名，慕容桓屯兵处"],["昌黎","辽西郡，暐想北奔的方向"],["高阳","地名，暐被擒处"],["受诏缚贼","接受诏书来捆绑贼人"],["狐死首丘","狐狸死时头朝着出生的山丘，喻不忘故土"],["和龙","即龙城，慕容氏旧都"],["镇东","镇东将军，慕容亮所任"],["新兴侯","苻坚封给暐的侯爵"],["别部都督","统领别部军队的官职"],["淮南之败","指淝水之战前秦失利"],["幽皇帝","南燕给暐追上的谥号"],["三十五","暐去世时的年龄"]],"think":["暐被擒时自称“天子”，巨武却说“受诏缚贼”。这种冲突说明什么？","名分是战争中的话语权：暐仍以天子自居，说明他还认为自己是正统；巨武只承认苻坚的诏书，说明秦军已经不把燕当作“国”。史书把这段对话保留下来，等于记录了两个政权都在用名分争夺合法性。"],"quiz":[["暐出奔的方向是？",["昌黎，即旧都方向","建业","长安"],"“暐与评等数十骑奔于昌黎。”"],["暐对苻坚说“狐死首丘”表达的是？",["想回到先人坟墓所在的故地","愿意投降并做秦臣","请求原谅"],"“欲归死于先人坟墓耳。”"],["暐最终怎样死？",["谋杀苻坚响应垂、冲，事发被诛","病死长安","战死沙场"],"“暐谋杀坚以应之，事发，为坚所诛，时年三十五。”"]],"cards":[["巨武那句话？","“我梁山巨武，受诏缚贼，何谓天子邪！”"],["暐被迁往长安的人口规模？","暐及王公以下并鲜卑四万余户。"]],"line":["狐死首丘，欲归死于先人坟墓耳","在人事变动中表达对原岗位的归属感时可以用：狐死首丘——但要想清楚自己要回到哪里。"],"tags":["慕容暐","前燕","灭亡"]},"zhuyan_qianyan_shi":{"intro":"《晋书》卷一百一十一的“史臣曰”：唐初史臣对前燕四主（廆、皝、儁、暐）的总评。另附篇末一句统计：慕容氏自廆称公到暐亡，共八十五年。这段评语能看出《晋书》编纂者的立场：既承认他们的才略，也强调“僭”“窃”的道德判断。","focus":["对慕容廆的评价是两面的：“英姿伟量，是曰边豪，衅迹奸图，实惟乱首”；又说他“勤王之诚，当君危而未立；匡主之节，俟国泰而将殉。适所谓相时而动，岂素蓄之款哉”，不认可其忠诚。然后转折：“制敌多权，临下以惠，劝农桑，敦地利，任贤士，该时杰，故能恢一方之业，创累叶之基焉。”先批评忠诚的动机，再承认治国的实绩。","对皝的批评集中在称王：“乃负险自固，恃胜而骄，端拱称王，不待朝命。昔郑武职居三事，爵不改伯；齐桓绩宣九合，位止为侯。瞻曩烈而功微，征前经而礼缛，谿壑难满，此之谓也。”意思是历史上功劳更大的人也没有越位，而皝功小却礼重，贪欲无度。对儁则说“遽窃鸿名，偷安宝箓”，评价其“文武兼优”“机断”，却指责他称帝与南下“使江左疲于奔命”。","对暐与恪、垂、评的评语最有意味：“景茂庸材，不亲厥务，贤辅攸赖，逆臣挫谋”，“及玄恭即世，虐媪乱朝。垂以勋德不容，评以黩货干政……是知由余出而戎亡，子常升而郢覆，终于身死异域，智不自全”。用由余（戎臣入秦谋戎）与子常（楚贪臣致郢破）两个典故，把垂的出走与评的贪鄙并列为亡国之因。末尾的“赞曰”与开头的统计一并说明：前燕八十五年的世系是《晋书》给它的结论。"],"notes":[["北阴衍气","北方阴寒之气，指北方蛮族"],["边豪","边地的豪强"],["乱首","祸乱的首领"],["相时而动","根据时机行动"],["恢一方之业","开拓一方基业"],["端拱称王","稳坐不动却称了王"],["郑武","郑武公，周平王时的卿士，爵位仍为伯"],["谿壑难满","沟壑难以填满，喻贪欲无穷"],["鸿名","至高的名号，指皇帝之名"],["宝箓","帝王的符命，代指帝位"],["由余出而戎亡","由余原为戎臣，入秦后秦得以灭戎"],["子常升而郢覆","楚令尹子常贪财，导致都城郢被攻破"]],"think":["唐初史臣一方面称廆“制敌多权，临下以惠”，一方面称其“乱首”“相时而动”。这种两面评价可信吗？","可信的部分是他们提供的事实：劝农桑、任贤士；不可全信的是动机判断：“素蓄之款”只能推测。读史论赞时，要把“事实层”和“评价层”分开，评价层带有作者所处时代的政治立场，尤其是对非汉族政权的“僭”“窃”之词，要放在修史背景中看。"],"quiz":[["“由余出而戎亡”指的是？",["戎臣由余入秦后秦灭戎，比喻本国人才外流导致国亡","戎人联合灭秦","由余死而戎亡"],"史臣以此类比慕容垂的出走，说明人才为敌所用的危害。"],["史臣批评皝的核心是？",["不待朝命而称王，礼过其功","不重农桑","不够勇武"],"“端拱称王，不待朝命”，并用郑武、齐桓的例子反衬。"],["按本段统计，前燕历时多少年？",["八十五年（廆称公至暐亡）","六十年","一百年"],"“通廆、皝凡八十五年。”"]],"cards":[["史臣评廆的八字？","“英姿伟量，是曰边豪”，又称其“乱首”。"],["“子常升而郢覆”喻谁？","喻慕容评以贪渎误国。"]],"line":["制敌多权，临下以惠，劝农桑，敦地利，任贤士","评价一个团队领导的实绩时可以引：制敌多权，临下以惠，劝农桑，敦地利——把成绩拆成几件具体事。"],"tags":["前燕","史论","晋书"]},"zhuyan_wangmeng_chu":{"intro":"前秦灭燕靠王猛，王猛怎么走到苻坚身边？这一段《晋书》写他隐居华阴、与桓温一面而去、被苻坚礼聘、在始平令任上“鞭杀一吏”被劾、而被苻坚称为“夷吾、子产之俦”。对写慕容氏故事的人，这是理解对手的必读。","focus":["他的“待时”最有味道：“怀佐世之志，希龙颜之主，敛翼待时，候风云而后动。”桓温入关，猛“被褐而诣之，一面谈当世之事，扪虱而言，旁若无人”。温问“三秦豪杰未有至者何也”，猛答“公不远数千里，深入寇境，长安咫尺而不渡灞水，百姓未见公心故也”——一句话说破桓温北伐的真实态度。温邀他同行，他“还山咨师”，师说“卿与桓温岂并世哉”，他于是留下。","与苻坚的相遇写得极短：“一见便若平生，语及废兴大事，异符同契，若玄德之遇孔明也。”这是史书常用的“君臣遇合”套语。更重要的是接着的细节：始平令任上，猛“明法峻刑，澄察善恶，禁勒强豪。鞭杀一吏”，被百姓上书、有司弹劾，“槛车征下廷尉诏狱”。","苻坚亲问：“为政之体，德化为先，莅任未几而杀戮无数，何其酷也！”猛回答“臣闻宰宁国以礼，治乱邦以法……始杀一奸，余尚万数……酷政之刑，臣实未敢受之”，坚遂说“王景略固是夷吾、子产之俦也”，赦之。苻坚的用人是听理由、不听流言，王猛的执政风格是对豪强下重法——这些都与前燕“权贵舞弊、政以贿成”的朝政形成鲜明对照。"],"notes":[["瓌姿俊伟","仪表伟岸出众"],["浮华之士","只重外表虚名的人"],["功曹","地方官属吏，主管人事"],["华阴山","王猛隐居之山，即华山一带"],["佐世之志","辅佐世道的志向"],["龙颜之主","有帝王之相的君主"],["被褐","穿粗布衣，指平民"],["扪虱而言","一边捉虱子一边说话，形容从容放达"],["灞水","长安东的河，与长安咫尺之隔"],["玄德之遇孔明","刘备与诸葛亮的君臣际遇"],["始平令","始平县的县令"],["豪右","豪强大族"],["鼎镬","古代烹人的刑具，喻重刑"]],"think":["王猛对桓温说“长安咫尺而不渡灞水，百姓未见公心”，为什么这句话能让桓温“默然”？","因为它直接指出北伐中的结构性问题：桓温军队已经到了关中，却不愿深入，也不愿招抚当地豪杰，原因是怕自己势力被削弱或被朝廷猜忌。猛看穿的是“动机”而不是“战术”，所以无话可答。"],"quiz":[["猛为何不随桓温南归？",["他回山咨询老师，被告知“卿与桓温岂并世哉”","桓温不肯用他","苻坚已经招他"],"“猛还山咨师，师曰：卿与桓温岂并世哉！在此自可富贵，何为远乎！”猛乃止。"],["苻坚为何赦免猛？",["猛说明杀奸是明君的需要，苻坚称他为夷吾、子产之俦","百姓撤诉","猛交出官印"],"“始杀一奸，余尚万数……酷政之刑，臣实未敢受之。”坚曰：“王景略固是夷吾、子产之俦也。”"],["猛在始平令任上因为什么被劾？",["鞭杀一吏，被百姓上书控告","贪污","擅自出兵"],"“鞭杀一吏，百姓上书讼之，有司劾奏，槛车征下廷尉诏狱。”"]],"cards":[["猛对桓温的批评？","长安咫尺而不渡灞水，百姓未见公心。"],["苻坚评猛？","“夷吾、子产之俦”。"]],"line":["宰宁国以礼，治乱邦以法","接手混乱团队时可以引：宰宁国以礼，治乱邦以法——先看对象，再选工具。"],"tags":["苻坚","王猛","人物"]},"zhuyan_wangmeng_an":{"intro":"前秦攻灭前燕后，王猛留镇邺城。《晋书》记他军纪严明、邺中劫盗绝迹，苻坚赐美妾女妓，他“上疏固辞不受”；苻坚给他六州便宜行事之权，他数月后又上疏请辞。这是了解前秦如何接管旧燕地的第一手材料。","focus":["接管的第一件事是秩序：“军禁严明，师无私犯。猛之未至邺也，劫盗公行，及猛之至，远近帖然，燕人安之。”对比前燕末年“州郡盗贼大起，邺中多怪异”，可知邺城居民的感受。前秦是外来征服者，却比慕容评的朝廷更像“政府”。","辞赏：“赐以美妾五人，上女妓十二人，中妓三十八人，马百匹，车十乘，猛上疏固辞不受。”灭国后把降国的美人与财物赏给功臣是常规，他拒绝，既是自律，也是政治姿态：不让关东人看到“灭燕就是掠夺”。","最见个性的是治理权限：苻坚“听以便宜从事，简召英俊，以补关东守宰，授讫，言台除正”，意思是先任命后报备。猛却“居数月，上疏”，说“设官分职，各有司存，岂应孤任愚臣，以速倾败”，请求“徙授亲贤”，或“乞待罪一州”。苻坚“不许，遣其侍中梁谠诣邺喻旨，猛乃视事如前”。权大而自请辞，是在保全自己，也在防止权力过度集中引起猜忌。"],"notes":[["军禁严明","军队纪律严格"],["师无私犯","军队不扰民"],["劫盗公行","抢劫盗窃公开横行"],["帖然","平静安稳的样子"],["清河郡侯","封爵名，封地在清河郡"],["女妓","歌舞女艺人"],["固辞","坚决推辞"],["便宜从事","遇事可自行决断，无须请示"],["简召英俊","选拔征召优秀人才"],["关东守宰","函谷关以东的郡守与县令"],["台除正","尚书台正式任命"],["待罪一州","到某州任职，自称有罪待处置"]],"think":["王猛有苻坚的“便宜从事”授权，为什么还要上疏请辞？","自请收权是保全之道：权力越大，外界越关注；宗室旧臣“皆害其宠”，前面他自己也被攻击过。主动提出“请避贤路”，可以让苻坚有机会表态“不许”，反而加固信任。这是一种风险管理：用“请辞”换“确认”。"],"quiz":[["猛入邺后邺中治安如何？",["劫盗绝迹，远近帖然，燕人安之","劫盗更加横行","无任何变化"],"“猛之未至邺也，劫盗公行，及猛之至，远近帖然，燕人安之。”"],["猛拒绝了什么赏赐？",["美妾、女妓、马与车","官爵","封地"],"“赐以美妾五人，上女妓十二人，中妓三十八人，马百匹，车十乘，猛上疏固辞不受。”"],["猛请求辞去六州便宜权，苻坚怎么处理？",["不许，遣侍中梁谠到邺传旨，猛继续视事","同意","改派他人"],"“坚不许，遣其侍中梁谠诣邺喻旨，猛乃视事如前。”"]],"cards":[["“简召英俊，以补关东守宰”的含义？","王猛可以自行选拔官员，先任命后报备。"],["猛请辞时的理由？","东夏之事非臣所能康理，愿授亲贤，或乞待罪一州。"]],"line":["军禁严明，师无私犯","接管新团队时的第一印象工程，可以引：军禁严明，师无私犯——先稳住秩序，再谈改革。"],"tags":["王猛","前秦","治理"]},"zhuyan_ling":{"intro":"《资治通鉴》里慕容垂之子慕容令的结局：在被前秦反间逼走之后，他回到前燕，却被安置到沙城“谪戍”。他自知难免，便聚谪戍士东袭威德城，起兵失败，被降者涉圭所杀，龙城的勃海王亮“收令尸而葬之”。这一段写出垂家在前燕的尴尬与旧燕人的情感。","focus":["令起兵的路径很清晰：先“沙城中谪戍士数千人，令皆厚抚之”，再“杀牙门孟妫”，涉圭“惧，请自效”，令“信之，引置左右”，随后“东袭威德城，杀城郎慕容仓，据城部署，遣人招东西诸戍，翕然皆应之”。这几句说明：谪戍士是他最重要的人力，边戍对他的响应也不弱。","败因是两处：一是轻信涉圭，二是亲弟泄密：“其弟麟以告亮，亮闭城拒守。”令的原计划是继续袭龙城，镇东将军勃海王亮在龙城坚守，他“将袭之”落空。最终是“涉圭因侍直击令，令单马走，其党皆溃”，涉圭追到薛黎泽杀了他。注意：《晋书·慕容垂载记》称垂之子为“世子全”，《通鉴》作“令”，名字有别，是否同一人、孰为正，存疑。","收尾耐读：涉圭“诣龙城白亮”，“亮为之诛涉圭，收令尸而葬之”。亮没有因为令是“叛者”而弃尸，反而诛杀杀令的人，说明在慕容宗室内部，令的身份与情感超过了官方立场。垂后来返回河北时，农、楷等旧部迅速响应，也是同一种情感的延续。"],"notes":[["自度","自己估量"],["谪戍","因罪发配守边的士兵"],["牙门","军营的牙门将，掌管军门的武官"],["威德城","原为涉奕于城，皝改名威德城，是东北边城"],["城郎","边城的守官"],["翕然","一致响应的样子"],["镇东将军","高级将军号，亮任此职镇龙城"],["侍直","在身边侍卫值班"],["单马走","一人一马逃走"],["薛黎泽","地名，令被杀处"],["诣龙城","到龙城去"],["收令尸","收殓令的尸体"]],"think":["令明知兵少，为何仍要起兵？从文中找出“他不起兵也不能活”的依据。","文章开头就是“令自度终不得免”，也就是说在沙城他一直处于被监视、被怀疑的位置；留在原地必被清算，起兵反而有一线生机。这说明前燕朝廷对垂家的猜忌已经使对方无路可走。这也解释了垂后来的叛秦与复燕：他并非单纯的野心，而是被一次次推到墙角。"],"quiz":[["令起兵的人力基础主要是？",["沙城中的谪戍士数千人","禁军","龙城守军"],"“沙城中谪戍士数千人，令皆厚抚之。”"],["令为什么没能袭取龙城？",["其弟麟告密，亮闭城拒守","遇大雪","粮草耗尽"],"“其弟麟以告亮，亮闭城拒守。”"],["亮对令的处理是？",["诛杀涉圭，收令尸而葬之","悬首示众","追赠官职"],"“亮为之诛涉圭，收令尸而葬之。”"]],"cards":[["《晋书》与《通鉴》对垂之子名字的差异？","《晋书》作“全”，《通鉴》作“令”，存疑。"],["令兵败后死于何处？","薛黎泽，被涉圭追及擒杀。"]],"line":["令自度终不得免，密谋起兵","在困境中评估“不动也难免”的判断，可以用这句：自度终不得免——先问不动的代价。"],"tags":["慕容垂","通鉴","人物"]},"zhuyan_chui_ru_qin":{"intro":"慕容垂的前半生：少年被皝评为“或能破人家，或能成人家”；石赵之乱时劝儁南伐；枋头之战威名大振；被评谋害后奔秦，又在王猛反间下险些被杀，最后因苻坚“恩待如初”而留在前秦；邺城陷落后旧臣高弼劝他“鸿渐之始”。这是理解后燕的起点。","focus":["《晋书》开篇用三件事塑造他：皝对他的评价“此儿阔达好奇，终能破人家，或能成人家”，名霸字道业；因“恩遇逾于世子儁，故儁不能平之”，儁即位后改名为“𡙇”，后又“以谶记之文，乃去夬，以‘垂’为名”；少好畋游，“因猎坠马折齿”。每一件都在提示：他既被偏爱，又被忌惮。","他对儁的建议很有分量：石季龙死，垂说“时来易失，赴机在速，兼弱攻昧，今其时矣”，儁因新遭大丧不许，慕舆根重复才从之；儁克幽州，“将坑降卒”，垂谏“吊伐之义，先代常典……坑戮之刑不可为王师之先声”，儁从之。枋头之后，“慕容评深忌恶之，乃谋诛垂”，垂“与世子全奔于苻坚”。","在秦期间：王猛劝坚杀垂，坚不从；王猛使人“诡传垂语于全”，全奔燕，垂“惧而东奔，及蓝田，为追骑所获”，坚说“卿家国失和，委身投朕……卿何为过惧而狼狈若斯也”，“复垂爵位，恩待如初”。邺城陷后，垂见故吏“有不悦之色”，高弼劝“此乃鸿渐之始，龙变之初……网漏吞舟，以弘苞养之义”，垂深纳。从这里，垂从“被逼逃亡的人”转向“有意识经营旧部的人”。"],"notes":[["岐嶷","幼年聪颖"],["阔达好奇","胸襟开阔、喜欢新奇事物"],["能破人家，或能成人家","既可能毁掉家族，也可能成就家族"],["时来易失","机会来了容易错失"],["兼弱攻昧","兼并弱小、攻打昏昧"],["吊伐之义","吊民伐罪的道义"],["坑戮之刑","活埋杀戮的刑罚"],["信都","地名，垂曾徙镇处"],["留台","派驻地方代理朝廷事务的机构"],["首丘","狐死首丘，喻思念故乡"],["追骑","追赶的骑兵"],["鸿渐之始","好比鸿雁逐步高升的开始"],["网漏吞舟","法网宽疏到能漏过吞舟之鱼，指宽厚待人"]],"think":["王猛劝苻坚杀垂，苻坚没有杀；垂两次叛逃（奔秦、叛秦）又都被宽恕。从苻坚的角度，这是气度还是失误？","这是双重结论：气度上，宽待投降者强化了前秦“以义致英豪”的形象；决策上，对一位明知有谋略、有旧部的人不加限制，是对力量对比的误判。因为苻坚此时压倒性占优，容易低估后果。判断决策好坏要看时点：他在最强大时的宽容，后来在最弱时付出了代价。"],"quiz":[["垂改名“垂”的原因是？",["曾因儁忌惮改名，又以谶记之文去夬","为避皇帝讳","受封"],"“内实恶而改之。寻以谶记之文，乃去夬，以‘垂’为名焉。”"],["垂劝儁勿坑降卒的理由是？",["吊伐之义，坑戮之刑不可为王师之先声","降卒数量太多","粮草不足"],"“吊伐之义，先代常典。今方平中原，宜绥怀以德，坑戮之刑不可为王师之先声。”"],["高弼劝垂善待旧吏，核心理由是？",["“鸿渐之始，龙变之初”，需以宽容招旧臣","旧吏有罪","旧吏人数多"],"“此乃鸿渐之始，龙变之初……收纳旧臣之胄，以成为山之功。”"]],"cards":[["皝评垂的话？","“此儿阔达好奇，终能破人家，或能成人家。”"],["垂奔秦的原因？","慕容评深忌其威名，谋诛垂，垂惧而奔苻坚。"]],"line":["时来易失，赴机在速，兼弱攻昧，今其时矣","遇到稍纵即逝的机会时可以说：时来易失，赴机在速——但要先确认自己看到的是真窗口。"],"tags":["慕容垂","后燕","人物"]},"zhuyan_fa_jin":{"intro":"淝水之战前，苻坚在灞上宣布“吾计决矣，不复与诸卿议”，太子宏与道安反对，慕容垂却上言“陛下内断神谋足矣”；另一段写苻融屡谏，指出垂与姚苌“皆我之仇敌，思闻风尘之变”。两段合读，可见前秦内部一场关键的决策失败。","focus":["苻坚论证以“天下垂平，惟东南未殄”为起点，用“晋武若信朝士之言而不征吴者，天下何由一轨”做类比，说“吾计决矣，不复与诸卿议也”。太子宏以“吴今得岁”“谢安、桓冲兄弟皆一方之俊才”劝止，并预言“若动而无功，则威名损于外，资财竭于内”，苻坚以“往年车骑灭燕，亦犯岁而捷之”反驳。","慕容垂的发言是整段的转折点：“陛下德侔轩唐……孙氏跨僭江东，终并于晋，其势然也……诗云：筑室于道谋，是用不溃于成。陛下内断神谋足矣，不烦广访朝臣以乱圣虑。昔晋武之平吴也，言可者张杜数贤而已，若采群臣之言，岂能建不世之功！”他一边顺着苻坚的意思，一边把反对者说成“乱圣虑”的“朝臣”。苻坚“大悦”，赐帛五百匹，说“与吾定天下者，其惟卿耳”。","苻融的话对照而读：“知足不辱，知止不殆，穷兵极武，未有不亡。且国家，戎族也，正朔会不归人。”他从“戎族”的身份论证不应与正统争。苻坚答“帝王历数岂有常哉，惟德之所授耳”，并以刘禅为例。融又警告“垂、苌皆我之仇敌，思闻风尘之变，冀因之以逞其凶德”。结果是：“及淮南之败，垂、苌之叛，坚悼恨弥深。”"],"notes":[["灞上","长安东灞水旁的高地"],["轩辕","黄帝"],["一轨","车同轨，指统一"],["桓温之寇","指桓温北伐关中"],["商风之陨秋箨","秋风吹落枯叶，喻轻易击败"],["道安","前秦名僧释道安"],["张杜","张华、杜预，西晋灭吴的主张者"],["筑室于道谋","在路旁与人商量盖房，比喻议论纷纭不成事"],["偷魂假号","苟且保命、假借名号"],["知足不辱","知足就不会受辱"],["戎族","指氐族出身"],["正朔会不归人","正统历法终不归于我们这样的外族"],["刘禅","蜀汉后主，苻坚以其亡国为例"]],"think":["垂的发言一边顺着苻坚，一边贬低朝臣。这是真心还是策略？","从结果看是策略：他借“内断神谋”抬高苻坚，使反对声失效，同时给自己争取“与吾定天下者其惟卿耳”的信任。苻融的警告说明他的动机被识破：想看到前秦失败。这种“迎合式建议”最危险，在于它既不是公开反对，也不是真心支持。"],"quiz":[["太子宏反对伐晋的主要理由是？",["晋有谢安、桓冲，凭长江固守，不可图","秦军数量不足","路途太远"],"“谢安、桓冲兄弟皆一方之俊才，君臣戮力，阻险长江，未可图也。”"],["垂在朝议中建议苻坚？",["内断神谋足矣，不烦广访朝臣","广泛听取意见","暂缓出兵"],"“陛下内断神谋足矣，不烦广访朝臣以乱圣虑。”"],["苻融对苻坚警告的核心？",["垂、苌皆我之仇敌，思闻风尘之变","晋军强大","粮食不足"],"“垂、苌皆我之仇敌，思闻风尘之变，冀因之以逞其凶德。”"]],"cards":[["苻融“知足不辱”之后的下一句？","知止不殆，穷兵极武，未有不亡。"],["苻坚的回答“帝王历数岂有常哉”意思？","天命不专属某族，惟德者得之。"]],"line":["知足不辱，知止不殆，穷兵极武，未有不亡","面对扩张冲动时可以引：知足不辱，知止不殆——决策越顺利，越要有人说“停”。"],"tags":["苻坚","前秦","决策"]},"zhuyan_quanyi":{"intro":"淝水之后，慕容垂请求回河北“镇慰”，权翼劝苻坚不要放虎归山，苻坚却说“匹夫犹不食言，况万乘乎”。《通鉴》这段还写了权翼派人在河桥邀杀垂，垂以草筏、替身脱险。细读它，可以看到苻坚为什么没留住垂，也可以看到垂如何一步步脱离前秦。","focus":["垂的请求来自慕容农的建议：农引“秘记”说“燕复兴当在河阳”，并劝“取果于未熟与自落，不过晚旬日之间，然其难易美恶，相去远矣”——不要强夺，等对方崩溃。垂于是到渑池对苻坚说“北鄙之民，闻王师不利，轻相扇动，臣请奉诏书以镇慰安集之，因过谒陵庙”，苻坚许可。","权翼的反对出于冷静的判断：“国兵新破，四方皆有离心，宜征集名将，置之京师，以固根本，镇枝叶。垂勇略过人，世豪东夏，顷以避祸而来，其心岂止欲作冠军而已哉！譬如养鹰，饥则附人，每闻风飙之起，常有凌霄之志，正宜谨其绦笼，岂可解纵，任其所欲哉！”苻坚引“匹夫犹不食言”拒绝，权翼说“陛下重小信而轻社稷，臣见其往而不返，关东之乱，自此始矣”。","苻坚的防范并非没有：同时派石越戍邺、张蚝戍并州、毛当戍洛阳，并让李蛮等“送垂”。权翼更干脆，“密遣壮士邀垂于河桥南空仓中”，垂有所觉，“自凉马台结草筏以渡”，“使典军程同衣己衣，乘己马，与僮仆趣河桥”，伏兵发，同“驰马获免”。垂此时已经被盯得很紧，必须逃出渡口，才得以北上。"],"notes":[["秘记","秘密流传的预言书"],["河阳","黄河北岸渡口，在今河南孟州"],["取果于未熟","不等成熟就摘果，喻急于求成"],["渑池","地名，在今河南三门峡一带"],["谒陵庙","拜谒祖先的陵庙"],["权翼","前秦谋臣"],["绦笼","拴系鹰的绳索与笼"],["陵霄之志","凌云高飞的志向"],["匹夫犹不食言","普通人尚且不违背自己的话"],["河桥","黄河上的浮桥，在今河南孟津一带"],["草筏","用草结成的筏子"],["典军","掌管军务的官员"]],"think":["苻坚说“匹夫犹不食言，况万乘乎”，是守信还是误判？","对个人来说，这是守信；对国家来说，是误判：权翼的话“重小信而轻社稷”点中了要害。信用与国家利益冲突时，决策者需要分层判断：对垂的承诺是私人信用，但对国家的责任更大。苻坚在此把前者放在后者之上。"],"quiz":[["慕容农劝垂的比喻是？",["取果于未熟与自落，难易美恶相去甚远","趁热打铁","不入虎穴"],"“夫取果于未熟与自落，不过晚旬日之间，然其难易美恶，相去远矣！”"],["权翼用什么比喻说明垂的危险？",["养鹰，饥则附人，有陵霄之志","养虎","养马"],"“譬如养鹰，饥则附人，每闻风飙之起，常有陵霄之志。”"],["垂如何躲过河桥的伏击？",["自凉马台结草筏渡河，派典军程同替身去河桥","杀出重围","贿赂伏兵"],"“自凉马台结草筏以渡，使典军程同衣己衣，乘己马，与僮仆趣河桥。”"]],"cards":[["权翼对苻坚的预言？","垂往而不返，关东之乱自此始。"],["苻坚的回答？","匹夫犹不食言，况万乘乎。"]],"line":["陛下重小信而轻社稷，臣见其往而不返","劝上级不要为小承诺放弃大局时可以引：重小信而轻社稷——先看后果，再谈信用。"],"tags":["慕容垂","苻坚","通鉴"]},"zhuyan_fanghu":{"intro":"垂到邺后，苻丕与石越的两次对话：一次是丕决定派垂去平翟斌，石越警告“虎傅翼”，丕自认“卞庄子之术”；另一次是垂潜服入邺拜庙，斩吏烧亭，石越劝杀，丕以“淝水之败时垂侍卫乘舆”为由不忍。《通鉴》把两次决策点写得极细，是理解前秦在河北丧失主动权的关键。","focus":["石越的预判一针见血：“慕容垂，燕之宿望，有兴复旧业之心。今复资之以兵，此为虎傅翼也。”丕的回答是：“垂在邺如藉虎寝蛟，常恐为肘腋之变。今远之于外，不犹愈乎！且翟斌凶悖，必不肯为垂下，使两虎相毙，吾从而制之，此卞庄子之术也。”在丕看来，把垂放出去是消除近忧，而且可以借翟斌牵制他。","具体安排却暴露了小聪明：“乃以羸兵二千及铠仗之弊者给垂，又遣广武将军苻飞龙帅氐骑一千为垂之副，密戒飞龙曰：垂为三军之帅，卿为谋垂之将。”给弱兵，是为了不让垂壮大；派副将“谋垂”，是为了暗中监视和防备。这种安排本身就是在激化矛盾，垂后来杀飞龙起兵，是它的直接后果。","第二个节点是亭吏事件：垂“请入邺城拜庙”，丕不许，垂“潜服而入”，亭吏禁之，垂“斩吏烧亭而去”。石越说“反形已露，可因此除之”，丕说“淮南之败，垂侍卫乘舆，此功不可忘也”，石越退后叹“公父子好为小仁，不顾大计，终当为人擒耳”。《资治通鉴》把这句话写作石越的私下叹息，也是史家对丕的评价。"],"notes":[["王师新败","指淝水之败"],["负罪亡匿之徒","犯罪逃亡躲藏的人"],["虎傅翼","为老虎添上翅膀"],["藉虎寝蛟","让老虎睡觉、让蛟龙蛰伏，比喻危险的邻居"],["肘腋之变","发生在身边的变故"],["卞庄子之术","卞庄刺虎，等两虎相斗再收渔利"],["羸兵","疲弱的士兵"],["苻飞龙","丕派去监视垂的副将"],["亭吏","负责驿亭的小吏"],["反形已露","反叛的迹象已经显露"],["小仁","小恩小惠式的仁慈"]],"think":["丕的“卞庄子之术”听起来合理，为什么最终失败？","此术需要“两虎”势均力敌且互相仇视，但垂与翟斌的实力并不对等，垂也能很快反客为主；另一方面，丕给垂的兵是“羸兵”，却把监视安排得过于明显，反倒加剧了垂的警惕。“借刀”之计成立的前提是自己掌握信息与节奏，丕两者都缺。"],"quiz":[["丕准备利用谁牵制垂？",["翟斌","苻晖","石越"],"“且翟斌凶悖，必不肯为垂下，使两虎相毙，吾从而制之。”"],["丕给垂的配置是？",["羸兵二千加苻飞龙氐骑一千为副","精兵万人","不配兵"],"“乃以羸兵二千及铠仗之弊者给垂，又遣广武将军苻飞龙帅氐骑一千为垂之副。”"],["丕不杀垂的理由是？",["淮南之败垂侍卫乘舆，此功不可忘","垂手握重兵","垂是皇族"],"“淮南之败，垂侍卫乘舆，此功不可忘也。”"]],"cards":[["石越对丕的批评？","好为小仁，不顾大计，终当为人擒耳。"],["“虎傅翼”的意思？","给本已凶猛的对手增添力量。"]],"line":["公父子好为小仁，不顾大计","看到团队在关键时刻因情面误事时，可以引：好为小仁，不顾大计——情义与大局要分开算。"],"tags":["慕容垂","苻丕","通鉴"]},"zhuyan_jihe":{"intro":"垂到河内后杀苻飞龙、悉诛氐兵，召募远近，济河焚桥，立下军令。同时翟斌推他为盟主，他表面推辞，暗中另有算计；他的儿子农在列人起兵，响应者众，垂的复国之路由此展开。这一组段落连读，最能看出垂的“外借秦名、内谋复燕”的双层话语。","focus":["第一层话语对内：垂“济河焚桥，令曰：吾本外假秦声，内规兴复。乱法者军有常刑，奉命者赏不逾日。天下既定，封爵有差，不相负也”。焚桥是断后路的象征，军令则是“有罚有赏”的最简框架，“外假秦声”四字把真实意图说得毫不遮掩。","第二层话语对外：翟斌推他为盟主，他答“吾父子寄命秦朝，危而获济，荷主上不世之恩……吾本救豫州，不赴君等”。史官特意写出他的盘算：“垂进欲袭据洛阳，故见苻晖以臣节，退又未审斌之诚款，故以此言距之。”也就是进是为了让苻晖放心，退是为了不被翟斌绑住。等到“苻晖闭门距守”，垂才转变，郭通劝说，他“乃许之”。","垂的第二个姿态是不称尊号：“新兴侯，国之正统，孤之君也。若以诸君之力，得平关东，当以大义喻秦，奉迎反正。无上自尊，非孤心也。”这里的“新兴侯”指暐，意思是复国成功后迎暐回邺，自己不篡位。战略选择也很清晰：“洛阳四面受敌，北阻大河，至于控驭燕赵，非形胜之便，不如北取邺都，据之而制天下。”同时农、宙在列人、楷、绍在辟阳起兵，“众至十余万”，“斩越于陈”。"],"notes":[["河内","郡名，在今河南焦作、沁阳一带"],["济河焚桥","渡河之后烧毁桥梁，表示不再退"],["外假秦声","表面借用前秦的名义"],["内规兴复","暗中谋划复兴燕国"],["盟主","联盟的领袖"],["臣节","臣子的礼节与姿态"],["诚款","诚意"],["新兴侯","指慕容暐，苻坚所封"],["奉迎反正","迎回旧主、恢复正统"],["形胜","地势险要而便利"],["列人","地名，慕容农起兵处"],["斩越于陈","在陈地斩杀石越"]],"think":["垂对翟斌说“吾本救豫州，不赴君等”，同时又接受他的会师。这种“先拒后受”有什么作用？","先拒是保持与前秦的名义关系，不给苻晖、苻丕口实；后受是情势变化后的现实选择。史官点明这种“进以见臣节，退以防诚款”的双重考虑，让读者看到：在乱世，名义和实力并行，说法是随情势调整的工具。"],"quiz":[["垂济河焚桥后所下军令的核心是？",["乱法者军有常刑，奉命者赏不逾日","只许进不许退","不得抢掠"],"“乱法者军有常刑，奉命者赏不逾日。天下既定，封爵有差，不相负也。”"],["垂不称尊号的理由是？",["新兴侯是国之正统，应迎其反正","兵力不足","不愿称帝"],"“新兴侯，国之正统，孤之君也……当以大义喻秦，奉迎反正。”"],["垂放弃洛阳取邺的原因？",["洛阳四面受敌，不利控驭燕赵","邺城粮多","翟斌所请"],"“洛阳四面受敌，北阻大河，至于控驭燕赵，非形胜之便。”"]],"cards":[["“吾本外假秦声，内规兴复”意思？","表面借秦名义，内里谋划复兴燕国。"],["农在哪里起兵？","列人。"]],"line":["乱法者军有常刑，奉命者赏不逾日","团队创业初期立规矩时可以引：乱法者有常刑，奉命者赏不逾日——赏罚都要及时。"],"tags":["慕容垂","后燕","起兵"]},"zhuyan_chengyan":{"intro":"垂到荥阳称燕王，建号“燕元”，立宝为太子，封功臣百余人；苻丕遣侍郎姜让来劝，一番义理交锋之后，垂“默然”，左右劝杀，他说“犬各吠非其主”，放让归。两段合读，可见垂称王时的格式与心理。","focus":["称号设计很有章法：“自称大将军、大都督、燕王，承制行事，建元曰燕元。令称统府，府置四佐，王公已下称臣，凡所封拜，一如王者。”《资治通鉴》写作“依晋中宗故事”，也就是仿东晋元帝以晋王身份承制行事的先例——有权力，不称帝。《晋书》本段把时间系于太元八年，《通鉴》则说济河在八年岁末、称燕王在九年正月，年份存疑。","封赏名单：翟斌“建义大将军，河南王”，翟檀“柱国大将军、弘农王”，弟德“车骑大将军、范阳王”，兄子楷“征西大将军、太原王”，“众至二十余万”，立子宝为太子，“封功臣为公侯伯子男者百余人”。名单兼顾外援（翟氏）与宗室（德、楷），既有兵力来源，也有政治安排。","姜让的话分三层：先说垂“保卫銮舆，勤王诚义”，再责他“弃崇山之功”，最后点“将军欲裂冠毁冕，拔本塞源者……但念将军以七十之年，悬首白旗”。垂的回答先说“欲安全长乐公，使尽众赴京师，然后修复家国之业”，被让驳到“默然”。文中“七十之年”是修辞：按《晋书》载垂卒年七十一（太元二十一年），此时不过五十八岁。垂最终说“古者兵交，使在其间，犬各吠非其主，何所问也”，遣让归。"],"notes":[["荥阳","地名，在今河南郑州一带"],["承制行事","没有朝命时代行任命与处置"],["燕元","垂所建年号"],["统府","垂把自己的官府称为统府"],["四佐","府中的四位主要僚佐"],["一如王者","全部按王的规格办理"],["建义大将军","授给翟斌的将军号"],["柱国大将军","高级武官头衔"],["姜让","苻丕派去劝降的侍郎"],["崇山之功","像高山一样的功绩，指保卫秦主"],["无名之师","没有正当名义的军队"],["犬各吠非其主","狗各自对着不是自己主人的人叫，喻使者各为其主"]],"think":["垂为什么选择“燕王”而非“皇帝”？这个选择在当时有什么政治意义？","称“燕王”保留了与旧燕、东晋“承制”体系的联系，不立即与前秦、东晋公开决裂，而且称王的成本低，容易被各方（翟斌、旧燕臣）接受；称帝则会激起暐、泓等宗室的反弹。选择“承制行事”的王位，是在不确定条件下的稳妥做法。"],"quiz":[["垂称“燕王”时设立的官府称作？",["统府","丞相府","大司马府"],"“令称统府，府置四佐，王公已下称臣。”"],["姜让对垂的质问核心是？",["弃勤王之功，起无名之师，欲裂冠毁冕","兵力不足","背信叛国"],"“将军起无名之师，而欲兴天所废，窃未见其可。”"],["垂对左右劝杀姜让的回答是？",["古者兵交，使在其间，犬各吠非其主","杀之以立威","押回监禁"],"“古者兵交，使在其间，犬各吠非其主，何所问也！”"]],"cards":[["垂称燕王的年份记载有什么分歧？","《晋书》作太元八年，《通鉴》系于九年正月，存疑。"],["姜让所说“七十之年”准确吗？","不是实际年龄，更像修辞，按《晋书》推算垂此时五十八岁左右。"]],"line":["古者兵交，使在其间，犬各吠非其主，何所问也","对立场相反却恪守职责的人，可以用这句表达宽容：犬各吠非其主——各为其主，不必针对个人。"],"tags":["慕容垂","后燕","外交"]},"zhuyan_fujian_shu":{"intro":"垂围邺后上表苻坚，申辩自己的叛离出于苻丕的猜忌；苻坚回信痛斥，却承认垂曾“保卫朕躬，社稷之不陨，卿之力也”，并以“失笼之鸟”“脱网之鲸”的比喻放手。这是一对难得的“君臣决裂书”：双方都在保留名分，也在表达真实的愤怒与不甘。","focus":["垂的表文先自述在秦的功绩与忠诚：“去夏桓冲送死，一拟云消，回讨郧城，俘馘万计”“陛下单马奔臣，臣奉卫匪贰”，再列举丕的猜忌：“令臣野次外庭，不听谒庙。丁零逆竖寇逼豫州，丕迫臣单赴，限以师程，惟给弊卒二千，尽无兵杖，复令飞龙潜为刺客。”最后提出方案：“邺者臣国旧都，应即惠及，然后西面受制，永守东藩。”他想把邺城作为交换条件，保留藩臣的姿态。","苻坚的回信先承认“赖卿忠诚之至，辅翼朕躬”，再用一连串比喻写愤怒：“伯夷忽毁冰操，柳惠倏为淫夫”“畜水覆舟，养兽反害，悔之噬脐，将何所及”。又说“失笼之鸟，非罗所羁；脱网之鲸，岂罟所制！翘陆任怀，何须闻也”，等于放手；“念卿垂老，老而为贼，生为叛臣，死为逆鬼”则是怒极而詈。","最耐读的是结尾：“朕之历运兴丧，岂复由卿！但长乐、平原以未立之年，遇卿于两都，虑其经略未称朕心，所恨者此焉而已。”苻坚真正在意的不是垂的叛，而是儿子们能否对付垂。两封信互相呼应：垂想留名分，坚想留恩情；两人都不愿把关系完全说死。"],"notes":[["祸起萧墙","祸患起于内部"],["归命圣朝","归顺朝廷"],["淮阴功高之虑","指韩信功高被疑的忧虑"],["李广失利之愆","指李广战败的罪责"],["青蝇","喻进谗言的小人"],["天符","天命的符验"],["东藩","东方的藩属"],["食椹怀音","鸱鸮食桑椹后改变声音，喻受恩后应感恩"],["畜水覆舟","蓄积的水也能把船掀翻"],["悔之噬脐","后悔得想咬自己的肚脐，喻悔之莫及"],["失笼之鸟","逃出笼子的鸟"],["脱网之鲸","挣脱渔网的鲸鱼"],["逆鬼","叛逆者死后的恶鬼"]],"think":["垂的上表和苻坚的回信，哪一份更接近“真实动机”？","两份都有修辞：垂的上表把起兵归因于丕的猜忌，淡化了复燕动机；苻坚的回信把垂定性为“叛臣”，却承认他的功劳。真实动机可以从行动看：垂围邺、称王、立太子，都属于复国。表文是为了保留名分、延缓前秦反击；回信是为了表达愤怒、保持道义优势。"],"quiz":[["垂在表中提出的交换条件是？",["把邺城（旧都）交给他，他西面受制、永守东藩","割地求和","质子入朝"],"“邺者臣国旧都，应即惠及，然后西面受制，永守东藩。”"],["苻坚用“失笼之鸟”比喻垂，意思是？",["对方一旦脱身，不是罗网所能束缚","垂愚笨","垂缺少帮手"],"“失笼之鸟，非罗所羁；脱网之鲸，岂罟所制！”"],["苻坚最后说“所恨者此焉而已”，指的是？",["担心丕、晖年轻，难以对付垂","后悔未杀垂","担心国库空虚"],"“但长乐、平原以未立之年，遇卿于两都，虑其经略未称朕心，所恨者此焉而已。”"]],"cards":[["垂指责丕的三件事？","野次外庭不听谒庙；给弊卒二千无兵杖；令飞龙潜为刺客。"],["苻坚对垂的最后判语？","“老而为贼，生为叛臣，死为逆鬼。”"]],"line":["失笼之鸟，非罗所羁；脱网之鲸，岂罟所制","形容一位已离开原体制、无法再被约束的人时可用：失笼之鸟，非罗所羁——只能面对，不能再管。"],"tags":["慕容垂","苻坚","后燕"]},"zhuyan_zhaibin":{"intro":"垂复国过程中的一个麻烦人物是翟斌：功大、骄横，要求“尚书令”，被垂以“台既未建”搁置，转而与苻丕勾结，垂果断诛之。随后垂改变围邺策略，“引师去邺，北屯新城”，打算让苻丕离城，同时先解决丁零叛乱，并显露北都中山之意。","focus":["封衡的评语很尖锐：“马能千里，不免羁靽，明畜生不可以人御也。斌戎狄小人，遭时际会，兄弟封王，自驩兜已来，未有此福。忽履盈忘止，复有斯求，魂爽错乱，必死不出年也。”他把斌比作畜生，并预言他“必死不出年”。垂“犹隐忍容之”，令曰“翟王之功宜居上辅，但台既未建，此官不可便置”——用程序性理由拒绝，避免公开决裂。","斌却“怒，密应苻丕，潜使丁零决防溃水”，事泄被诛。垂对其兄子翟真的处理很稳：令太子宝与隆击破之，再让楷追击，战于下邑，楷败。垂对将领们说“苻丕穷寇，必守死不降；丁零叛扰，乃我腹心之患”，所以“引师去邺，北屯新城”，“开其逸路”，理由是“进以谢秦主畴昔之恩，退以严击真之备”。把放走丕包装成报恩，同时先清内患。","接着“进师又攻邺，开其西奔之路”，目的是让苻丕离开。垂“将有北都中山之意，农率众数万迎之”，群僚听说暐被苻坚所杀，劝垂僭位，垂“以慕容冲称号关中，不许”。这最后一句说明一个规则：宗室之中还有称帝者（冲），垂不能抢先，需要先看关中局势。"],"notes":[["尚书令","尚书台长官，实际宰相"],["羁靽","笼头与绊绳，用来拴系马"],["驩兜","传说中尧时的四凶之一"],["履盈忘止","已处满位而不知止足"],["魂爽错乱","神志错乱，失去理智"],["隐忍","忍耐不发作"],["决防溃水","破开堤防放水"],["承营","地名，翟真屯驻处"],["新城","垂暂时驻扎的城"],["逸路","让对方脱身的出路"],["腹心之患","最内部、最致命的威胁"],["北都中山","把中山作为北方都城"]],"think":["垂放走苻丕、先打翟真，这个顺序有什么军事和政治逻辑？","军事上：苻丕是“穷寇”，守死不降会消耗大量兵力；翟真的丁零军是“腹心之患”，会动摇后方。把放丕说成“谢秦主畴昔之恩”，在政治上保持了对苻坚的“报恩”形象，也避免了过度决裂。先清内患、再收外敌，是一种常见的优先级排序。"],"quiz":[["封衡评翟斌的核心是？",["骄盈忘止，必死不出年","有勇无谋","忠诚可靠"],"“忽履盈忘止，复有斯求，魂爽错乱，必死不出年也。”"],["垂对翟斌“尚书令”之请的回应是？",["台既未建，此官不可便置，待六合廓清再议","立刻同意","公开斥责"],"“翟王之功宜居上辅，但台既未建，此官不可便置。”"],["垂不即位的理由是？",["慕容冲已在关中称号","尚无国号","大臣反对"],"“垂以慕容冲称号关中，不许。”"]],"cards":[["垂为何先“引师去邺”？","丁零叛扰是腹心之患，又想开逸路让苻丕离城，并以此谢秦主旧恩。"],["翟斌的下场？","密应苻丕、潜使丁零决防溃水，事泄被诛。"]],"line":["丁零叛扰，乃我腹心之患","排优先级时可以引：腹心之患——先处理影响根基的内部问题，再对付外敌。"],"tags":["慕容垂","后燕","人物"]},"zhuyan_zhongshan_ji":{"intro":"垂定都中山，群僚劝即尊号，他“具典仪，修郊燎之礼”，于太元十一年即位，年号“建兴”，置百官，立宝为太子。随后追尊其母兰氏，引发博士反对；又为太子起承华观，建留台于龙城。这是后燕建国的一份“组织表”，也留下了日后继承问题的隐线。","focus":["程序完整：“具典仪，修郊燎之礼”，“置百官，缮宗庙社稷，立宝为太子”。任命名单有旧臣与亲族：库辱官伟、段崇、张崇、封衡，慕容德“侍中、都督中外诸军事、领司隶校尉”，慕容麟“卫大将军”。注意“库辱官”这一姓，出现在非慕容旧臣的行列，可见后燕的政权有多民族的构成。","追尊母兰氏的争议：“追尊母兰氏为文昭皇后，迁皝后段氏，以兰氏配飨。”博士刘详、董谧反对，用“尧母妃位第三，不以贵陵姜嫄”说明“圣王之道以至公为先”，垂“不从”。这里的矛盾是：私情上他想尊母，礼制上需要按先后；他选择了私情，说明他在新朝初建时仍有强烈的个人决断。","太子的位置：“为其太子宝起承华观，以宝录尚书政事，巨细皆委之，垂总大纲而已。”又“以宝领侍中、大单于、骠骑大将军、幽州牧。建留台于龙城，以高阳王慕容隆录留台尚书事”。这样做是培养继承人，也使太子位置过高；后来宝即位后的局面（参合陂、立嗣之争）与此有直接关联。末尾“时慕容暐及诸宗室为苻坚所害者，并招魂葬之”，是对旧朝的补祭。"],"notes":[["郊燎","祭天时焚柴升烟的礼仪"],["建兴","垂称帝时的年号"],["左长史","官府中的主要佐吏"],["吏部尚书","主管官吏任免的长官"],["追尊","为已故者追加尊号"],["配飨","附祭于宗庙"],["博士","掌礼制与经学的官员"],["尧母妃位第三","传说尧母位列第三妃，后世援引为礼制先例"],["承华观","为太子所建的宫观"],["录尚书政事","总领尚书事务"],["留台","派驻地方的中央机构"],["招魂葬","遗体不得而收，以魂招葬"]],"think":["垂不顾博士反对，坚持追尊母亲，这一细节想说明什么？","一是垂有强烈的个人决断与孝心；二是新朝建立初期，礼制的“公”与个人的“私”并未分离。史官放这条，恰恰是为了展示：开国之君有时会为私情压倒制度，而制度的反对者仍能在朝堂上说话——这本身就是后燕政治的特点之一。"],"quiz":[["垂称帝的年号是？",["建兴","燕元","永康"],"“改元曰建兴。”"],["博士反对追尊兰氏的理由是？",["尧母妃位第三，不以贵陵姜嫄，圣王之道以至公为先","兰氏出身低","兰氏无子"],"“尧母妃位第三，不以贵陵姜嫄，明圣王之道以至公为先。”"],["垂在龙城设留台，由谁主持？",["高阳王慕容隆","慕容宝","慕容德"],"“建留台于龙城，以高阳王慕容隆录留台尚书事。”"]],"cards":[["后燕建国的年份记载？","太元十一年，垂僭即位，改元建兴。"],["垂对太子宝的政治安排？","录尚书政事、领侍中、大单于、骠骑大将军、幽州牧。"]],"line":["垂总大纲而已","高层与执行层分工时可以引：总大纲而已——最高负责人抓方向，细务交给继任者，但要留意交班是否稳。"],"tags":["慕容垂","后燕","建国"]},"zhuyan_huatai":{"intro":"后燕建国后，翟辽之子翟钊据滑台，攻逼邺城。垂亲征，面对黄河南岸的防守，他“徙营就西津，为牛皮船百余艘，载疑兵列杖，溯流而上”，让对方分兵，再派镇、国夜渡黄河，一举成功。这是垂晚年的一个经典奇计。","focus":["战前先稳军心：诸将“恶其兵精，咸谏不宜济河”，垂“笑曰：竖子何能为，吾今为卿等杀之”。一笑一语，把一支被对手吓住的军队稳了下来。与慕容恪“神色自若”的方式如出一辙，说明前燕出身的统帅有共同的“稳”的传统。","战术分两层：明处，“徙营就西津，为牛皮船百余艘，载疑兵列杖，溯流而上”；暗处，“潜遣其桂林王慕容镇、骠骑慕容国于黎阳津夜济，壁于河南”。翟钊“先以大众备黎阳，见垂向西津，乃弃营西拒”，于是上当；“钊闻而奔还，士众疲渴，走归滑台”，又“携妻子率数百骑北趋白鹿山”，被农追擒，“单骑奔长子”。","战后处理：“钊所统七郡户三万八千皆安堵如故，徙徐州流人七千余户于黎阳。”不迁走原有人口，只迁移外来流人，是为了安抚新降区；这和皝时的“按原籍编县”思路有相通之处。要点是：战术奇谲，处置稳妥，这是垂区别于一般将领之处。"],"notes":[["滑台","地名，在今河南滑县东，翟钊据点"],["黎阳津","黄河渡口，在今河南浚县一带"],["牛皮船","用牛皮蒙成的渡河工具"],["疑兵","迷惑敌人、虚张声势的部队"],["竖子","对人的轻蔑称呼，意为小子"],["西津","黎阳西侧的渡口"],["夜济","夜间渡河"],["壁于河南","在黄河南岸立营垒"],["白鹿山","地名，翟钊逃往之处"],["七郡","翟钊所统的七个郡"],["安堵","安居如旧"],["徐州流人","流亡到此的徐州百姓"]],"think":["为什么垂选择“西津”做疑兵，而不是在黎阳津直接强渡？","黎阳津对岸有翟钊的主力“于南岸距守”，强渡伤亡大；移到西津，使敌人以为他要绕道，从而抽调主力西拒，黎阳津的防守空了。疑兵的关键是让对方“看见”你想让他看见的方向，而且必须有足够的规模（牛皮船百余艘），否则无法令人相信。"],"quiz":[["垂用牛皮船的目的是？",["载疑兵溯流西上，诱翟钊主力离开黎阳津","运送粮草","架浮桥"],"“为牛皮船百余艘，载疑兵列杖，溯流而上。”"],["真正渡河的部队从哪里夜渡？",["黎阳津","西津","白鹿山"],"“潜遣其桂林王慕容镇、骠骑慕容国于黎阳津夜济，壁于河南。”"],["战后对翟钊统辖的七郡百姓怎样处置？",["户三万八千皆安堵如故","全部迁往中山","收为俘虏"],"“钊所统七郡户三万八千皆安堵如故。”"]],"cards":[["“竖子何能为，吾今为卿等杀之”的作用？","稳定被敌方吓住的诸将。"],["翟钊败后逃往？","先奔白鹿山，后单骑奔长子。"]],"line":["竖子何能为，吾今为卿等杀之","团队被强敌吓住时，领导人可以用这种语气稳定情绪，前提是已经有可靠的计划。"],"tags":["慕容垂","后燕","战例"]},"zhuyan_mie_xiyan":{"intro":"垂晚年出兵灭慕容永的西燕。《晋书》写决策与战术：诸将劝缓，垂闻慕容德的策略后说“吾计决矣”，用“月余不进”引永调兵，再从天井关突入，壶壁伏兵大破；《通鉴》则补外援：晋与魏的救兵都来不及，西燕被内应开门，永被擒斩。两书对内应者姓名记载不同，是需要注意的细节。","focus":["决策片段：诸将“以慕容永未有衅，连岁征役，士卒疲怠，请俟他年”，垂“将从之”，及闻德之策，“笑曰：吾计决矣。且吾投老，扣囊底智，足以克之，不复留逆贼以累子孙也”。理由不是军事，而是年龄与继承：趁自己在世，把问题解决，免得留给子孙。这与后来太子宝的局面形成讽刺：留给子孙的问题并未因此减少。","战术是“示形—误判—突入—伏击”：“垂顿于邺之西南，月余不进。永谓垂诡道伐之，乃摄诸军还杜太行轵关。垂进师入自天井关，至于壶壁。”永“阻河曲以自固，驰使请战”，垂“列阵于壶壁之南，农、楷分为二翼，慕容国伏千兵于深涧”，“引军伪退”，“永追奔数里，国发伏兵驰断其后”，“斩首八千余级”。结局：“进围长子，永将贾韬等潜为内应。”","《通鉴》补出外部：永“遣其子常山公弘等求救于雍州刺史郗恢”，恢上言“垂若并永，为患益深，不如两存之，可以乘机双毙”，晋廷诏王恭、庾楷救之；永又告急于魏，魏遣陈留公虔、庾岳“东渡河，屯秀容”。“晋、魏兵皆未至，大逸豆归部将伐勤等开门内燕兵，燕人执永，斩之。”内应者，《晋书》作“贾韬”，《通鉴》作“伐勤”，存疑。"],"notes":[["长子","西燕都城，在今山西长子"],["未有衅","尚没有破绽"],["扣囊底智","把口袋底最后的智慧都倾出来"],["诡道","诈谋、迂回的路线"],["太行轵关","太行山轵关陉，晋东南重要通道"],["天井关","太行山要关，在今山西晋城南"],["壶壁","地名，决战处"],["河曲","河流转弯的地方"],["伪退","假装撤退"],["郗恢","东晋雍州刺史"],["两存之","让双方都保存下来"],["乘机双毙","借机让两方同归于尽"],["内燕兵","开门放燕军入城"]],"think":["晋廷的郗恢提出“不如两存之，可以乘机双毙”，这一建议意味着什么？","意味着东晋对北方政权的基本态度是“以夷制夷”，并不真正想救谁；同时也说明垂的战略成功之处：在晋、魏援兵尚未到达之前，他已经通过战役把西燕解决了。这种“趁邻国犹豫时先动手”的节奏，是垂用兵的特点。"],"quiz":[["垂最终决定攻永的理由是？",["年迈，不愿把逆贼留给子孙","诸将请战","朝廷下诏"],"“且吾投老，扣囊底智，足以克之，不复留逆贼以累子孙也。”"],["垂在壶壁怎样取胜？",["伪退诱敌，慕容国伏兵断其后，农、楷夹击","水攻","夜袭"],"“垂引军伪退，永追奔数里，国发伏兵驰断其后，楷、农夹击之。”"],["《通鉴》写长子城破的直接原因是？",["大逸豆归部将伐勤等开门内燕兵","晋军援至","疫病"],"“晋、魏兵皆未至，大逸豆归部将伐勤等开门内燕兵，燕人执永，斩之。”"]],"cards":[["《晋书》中长子城的内应是谁？","永将贾韬等；《通鉴》作伐勤，存疑。"],["垂的诱敌之法？","顿兵月余不进，使永调兵至太行，再入天井关突袭壶壁。"]],"line":["且吾投老，扣囊底智，足以克之，不复留逆贼以累子孙也","高层在时间有限时做大决策，可以引这句：吾投老——但决策动机要警惕“急于了结”。"],"tags":["慕容垂","后燕","战例"]},"zhuyan_canhe":{"intro":"参合陂是后燕由盛转衰的节点。《资治通鉴》版本已列入主线，本卷用《晋书》版：太子宝南还时遇风与黑气，沙门支昙猛劝备，宝笑而不纳，麟纵猎，魏军夜袭，士众还者十一二。其后垂亲征，经过参合，见积骸如山，惭愤呕血，病死于平城北。","focus":["败因被写成“天象预警”与“主将轻忽”的对比：宝至参合，“忽有大风黑气，状若堤防，或高或下，临覆军上”，沙门支昙猛说“风气暴迅，魏军将至之候”，宝“笑而不纳”；昙猛固争，才遣麟率三万骑为后殿，麟却“以昙猛言为虚，纵骑游猎”。夜里魏师大至，“三军奔溃，宝与德等数千骑奔免，士众还者十一二，绍死之”。史官还写了出征前“车轴无故自折”，术士靳安劝还，宝“怒不从”。预兆的细节固然带有叙事色彩，但“不肯听反对意见”是文意核心。","报仇的出发点是情绪：“宝恨参合之败，屡言魏有可乘之机。”德也说“魏人狃于参合之役，有陵太子之心”，垂于是“自率大众出参合，凿山开道，次于猎岭”，派宝与农、隆、盛两路，袭陷平城，“收其众三万余人而还”。这是军事上的一次成功，但也引出了最后一幕。","垂至参合，“见往年战处积骸如山，设吊祭之礼，死者父兄一时号哭，军中皆恸。垂惭愤欧血，因而寝疾，乘马舆而进，过平城北三十里疾笃，筑燕昌城而还”，终于上谷沮阳去世，“时年七十一，凡在位十三年”。遗令“丧礼一从简易……强寇伺隙，秘勿发丧，至京然后举哀行服”，宝等遵行。从灭西燕到参合陂，垂的最后几年，正是后燕兴衰的缩影。"],"notes":[["临河","靠近黄河"],["参合","地名，在今内蒙古凉城一带"],["黑气","暗色云气，古人视为兵灾之兆"],["沙门支昙猛","僧人支昙猛"],["后殿","殿后部队"],["黄雾","黄色的雾气，此处指尘雾"],["车轴无故自折","出征前车轴自行折断，视为凶兆"],["术士靳安","占星术士靳安"],["狃于参合之役","对参合之战的成功习以为常"],["猎岭","地名，垂出师所经山岭"],["燕昌城","垂病中修筑的城"],["秘勿发丧","保密，不宣布死讯"]],"think":["参合陂败于“主将轻忽”还是“天时不利”？史官的叙述想让读者得出什么结论？","史官把预警写得很具体（黑气、支昙猛、车轴折断、术士劝返），目的不是证明预兆有效，而是强调“反对意见被拒绝”的结构：宝笑而不纳，麟认为是虚言，纵猎。判断一场败仗，不要被“预兆”叙事牵着走，要看决策链条：谁提出了风险，谁否决了，后果由谁承担。"],"quiz":[["支昙猛对宝的警告是？",["风气暴迅，是魏军将至之候，宜遣兵防御","粮道将断","水位上涨"],"“风气暴迅，魏军将至之候，宜遣兵御之。”"],["麟的失误是？",["把支昙猛的话当作虚言，纵骑游猎","擅自撤退","投降魏军"],"“麟以昙猛言为虚，纵骑游猎。”"],["垂在参合陂见到什么而病？",["往年战处积骸如山，军中皆恸，垂惭愤呕血","魏军伏击","粮食耗尽"],"“垂至参合，见往年战处积骸如山，设吊祭之礼……垂惭愤欧血，因而寝疾。”"]],"cards":[["参合陂败后还者几成？","士众还者十一二。"],["垂遗令的要点？","丧礼从简，强寇伺隙，秘勿发丧，至京然后举哀。"]],"line":["魏人狃于参合之役，有陵太子之心","分析对手心理变化时可以引：狃于前役，有陵之心——一次胜利会让对方变得轻敌或更凶。"],"tags":["慕容垂","后燕","战例"]},"zhuyan_baoping":{"intro":"慕容垂死后，第四子慕容宝继位，后燕由盛转衰。这一段前半写他怎样靠做样子赢得父亲信任，后半写他即位后推行垂的遗令，结果“百姓思乱者十室而九”。读法：看《晋书》怎样把“人设”与“政绩”并排放在一起，不加评语，反差自现。","focus":["前后两种评价并置。早年是“少轻果无志操，好人佞己”，立为太子后变成“砥砺自修，敦崇儒学，工谈论，善属文”，可关键一句是“曲事垂左右小臣，以求美誉”。称赞宝的是“垂之朝士”，把话说到垂耳边的是左右近臣。史家只写这条传话链，宝的真实成色就不言自明。","垂的遗令有明确内容：“校阅户口，罢诸军营分属郡县，定士族旧籍，明其官仪”。清查户口、拆掉军营改归郡县、核定士族门第，三件事都要动既有的人口荫附与军功势力。《晋书》把后果归在宝身上，“法峻政严，上下离德”；政策本身是否过急、执行者是否苛刻，本段不分，属于可再讨论之处。","全段的对照落在“垂亦以为克保家业，甚贤之”与“百姓思乱者十室而九焉”两句之间。一个是父亲眼里的守成之君，一个是百姓口中的将乱之世，两句相隔不到百字。史书的评价标准是后者。"],"notes":[["太子洗马","东宫属官，本为太子出行时前导，后多为文学侍从"],["万年令","万年县县令，苻坚时万年属京畿一带"],["陵江将军","杂号将军名号，淝水之战前后授予"],["砥砺自修","磨炼自己、修养德行"],["翕然","一致、协同的样子"],["克保家业","能够守住父辈的基业"],["永康","慕容宝即位后所改年号"],["太师","三师之一，位望极高的荣衔"],["左光禄大夫","加官名号，表示优崇"],["校阅户口","清点核查户籍人口"],["士族旧籍","士族门第的原有簿籍"],["法峻政严","法令严厉、政事苛紧"]],"think":["慕容宝“曲事垂左右小臣，以求美誉”，说明垂的哪一种失察？","垂的失察是信息来源单一：他对宝的认识主要来自“朝士”与近臣的转述，而这些人恰是宝讨好的对象。老年君主越依赖近侍传话，越难看到继承人的真面目。判断时要区分“有人称赞”与“称赞者是否独立”，这一点今天选人用人同样适用。"],"quiz":[["《晋书》说慕容宝做太子时赢得美誉靠的是什么？",["谦恭修养并曲意结交垂身边的近臣","在战场上屡立战功","主持改革得到百姓拥戴"],"原文“曲事垂左右小臣，以求美誉”，称赞者是朝士，来源是近臣转述。"],["宝即位后遵行垂遗令，不包括下面哪一项？",["废除太子之位","校阅户口","罢诸军营分属郡县"],"遗令的三项是校阅户口、罢诸军营分属郡县、定士族旧籍，没有废太子。"],["“法峻政严，上下离德，百姓思乱者十室而九焉”主要说明？",["苛政使上下离心、民间思乱","法制严明、国家大治","军队改制顺利推行"],"“离德”指上下不同心，“思乱”指盼望动乱，全句是负面评价。"]],"cards":[["慕容宝是慕容垂的第几子？","第四子。"],["宝即位后“百姓思乱者十室而九”的原因，《晋书》归于什么？","法峻政严，上下离德。"]],"line":["及为太子，砥砺自修，敦崇儒学，工谈论，善属文","评价一个人要看他做了什么，不只看他会说什么：能谈论、善属文的人，未必担得起事。"],"tags":["慕容宝","后燕","继承"]},"zhuyan_lice":{"intro":"后燕立嗣之争：垂看好宝的庶子清河公慕容会，宝却宠爱少子慕容策，而长子慕容盛为了压会，反过来盛称策宜为储贰。这一段把一次嗣位安排写成三方算计，后燕日后的内乱从这里埋下伏笔。读时抓人物各自的动机。","focus":["垂的安排是步步做出来的：宝北伐时“使会代摄宫事，总录、礼遇一同太子”，伐魏时“复使会镇幽州，委以东北之重”，临死“以会为宝嗣”。史书用“所以见定旨也”点明意图，垂并非临终一句话，而是长期铺路。","宝的态度很简单：“宝宠爱少子濮阳公策，意不在会。”他不讲才能，凭偏爱。而史家对策的描写只有一句：“年十一，美姿貌，而惷弱不慧。”“美姿貌”与“惷弱不慧”并列，宝所爱的是什么，一目了然。","盛的算计最值得读。“自以同生年长，耻会先之”，于是反过来“盛称策宜为储贰，而非毁会”。他不是支持策，是借策排除会；赵王麟、高阳王隆则“咸希旨赞成之”，只会迎合上意。一个“希旨”写尽朝臣的惯性。"],"notes":[["冢嗣","嫡长继承人，即太子"],["代摄宫事","代为处理宫中事务"],["总录","总管、总领"],["幽州","燕国东北方的重镇州名"],["顾命","临终前嘱托后事"],["储贰","储君，即太子"],["非毁","诋毁、攻击"],["希旨","迎合上意"],["惷弱不慧","愚笨软弱、不聪明"],["同生","同胞兄弟"],["龙城","燕国旧都，在今辽宁朝阳一带"],["美姿貌","仪容长得好看"]],"think":["慕容盛为什么不自己争太子，而是推策、毁会？这种做法对他有什么风险？","盛是庶长子，并不占嫡，但年长于策；会更有才名，直接竞争难胜。推弱小的策上位，既能压倒会，又能在日后辅佐或取代。风险是策太弱，朝局失衡，反而给宗室篡夺的机会，后燕后来的内乱正与此相应。"],"quiz":[["垂属意的继承人是谁？",["清河公慕容会","濮阳公慕容策","长乐公慕容盛"],"原文“临死顾命，以会为宝嗣”。"],["原文如何评价策？",["年十一，美姿貌，而惷弱不慧","少有大志，聪敏好学","沉敏多谋略"],"这是对策的直接评语，说明宝偏爱的依据是外貌而非才能。"],["慕容盛“盛称策宜为储贰”的真实意图是？",["借抬策压制会","真心拥戴策","谋求自己先立为太子"],"原文“耻会先之”，说明他是为了不让会居先。"]],"cards":[["垂如何为会铺路？","让他代摄宫事、镇幽州，临死顾命立会为宝嗣。"],["谁“希旨赞成”立策？","赵王麟、高阳王隆。"]],"line":["宝宠爱少子濮阳公策，意不在会","偏爱出现在用人决策里，团队就先裂开：“意不在会”这四个字，是所有内耗的开头。"],"tags":["后燕","立嗣","慕容盛"]},"zhuyan_hui_bian":{"intro":"北魏大军压境，宝出城与会会合于蓟，却因猜忌逼反了本可御敌的清河王会，最终两败俱伤、中山也丢了。《晋书》这一段写得长，核心是几次“该决断而误断”的瞬间。读时盯住几个角色的话：谁在劝，谁在谗，宝又听了谁。","focus":["宝的第一个误判在“有恨色”：会见到策被立为太子，脸上有怨色，宝便告知农、隆。农、隆当时的回答是“会一年少，专任方事，习骄所致，岂有他也。臣当以礼责之”，判断相当冷静；但宝已经动了疑心，“左右皆害其勇略，谮而不许”，让幽平将士的请战落了空。","仇尼归给会的建议非常直白：“盍诛二王，废太子，大王自处东宫”，会不从。会起初没有造反的意思，是宝与左右“事当必然，宜早杀之”之后，会才“闻之弥惧，奔于广都黄榆谷”。“弥惧”二字表明，是恐惧推着会走向叛。","农的劝阻保留了一条理性线：“今社稷之危若缀旒然，复内相诛戮，有损威望。”宝却说“会逆心已成”，“事败之后，当思朕言”。两种推理的差别，是前者从大局算，后者从猜忌算。结局是会攻宝，被高云（后来的慕容云）夜袭击败，会单马入中山，为慕容详所杀。"],"notes":[["幽并","幽州与并州，会所统辖的地区"],["蓟","地名，在今北京一带"],["缀旒","旌旗下垂的饰物，喻君权悬而不固"],["诛二王","指杀农、隆两位王"],["东宫","太子之宫，代指太子位"],["黄榆谷","地名，会逃奔的山谷"],["谮","进谗言诬陷"],["衅发","事端爆发"],["侍御郎","宫中侍卫官"],["敢死士","不惜赴死的勇士"],["开封公","封爵名，慕容详的爵位"],["弥惧","更加恐惧"]],"think":["如果宝听从农的劝告“宜且隐忍”，结局会不同吗？","或许不会完全避免冲突，但至少不会把会逼入绝路。农的论据有两层：逆迹未彰；敌军压境不宜内斗。宝的反论“会逆心已成”无法验证，却被他当作事实。大敌当前，对尚未行动的人动手，常常制造了对方本不一定有的反叛。"],"quiz":[["宝对会产生疑心的直接起因是？",["会因策被立为太子而有恨色","会拒绝出兵","会私通北魏"],"原文“会以策为太子，有恨色”。"],["慕容农对宝的劝阻理由是？",["逆迹未彰，社稷危殆时不宜内相诛戮","会兵多难制","等魏军退后再杀"],"原文“又逆迹未彰，宜且隐忍。今社稷之危若缀旒然，复内相诛戮，有损威望”。"],["最终击败慕容会围龙城之举的是？",["侍御郎高云夜袭","慕容农","慕容详"],"原文“侍御郎高云夜率敢死士百余人袭会，败之”，会随后入中山被慕容详所杀。"]],"cards":[["谁劝会“诛二王，废太子”？","侍御史仇尼归。"],["会之变中谁夜袭败会？","侍御郎高云，即后来的慕容云。"]],"line":["今社稷之危若缀旒然，复内相诛戮，有损威望","形势最危的时候，团队内部最该克制的是互相清算：“有损威望”四个字，对谁都适用。"],"tags":["后燕","慕容会","内耗"]},"zhuyan_baoyan":{"intro":"宝南伐中途兵变，龙城易手，宝自己被兰汗所杀。这一段是慕容宝一朝的收场，也是慕容盛登上舞台的前奏。读时注意两个转折：宝拒谏的“吾计决矣，敢谏者斩”，以及他对兰汗“必谓忠款无贰”的判断。","focus":["宝的拒谏很典型。慕容盛说“兵疲师老，魏新平中原，宜养兵观衅”，慕舆腾却说“难与图始，惟当独决圣虑，不足广采异同”，意思是民众只能让他们跟着做，不能让他们参与谋划。宝取后者，并以“敢谏者斩”结束讨论。这把一个本该有争议的军事决定，变成了权威的单方宣示。","军心早有裂痕。“众军之惮役”，段速骨、宋赤眉乘机杀乐浪王宙、立高阳王崇，宝只得“单骑奔农”。这说明南伐并非众志成城，兵变不是偶然。随后农又“为兰汗所谲”被杀，宝的退路一层层断掉。","最后一步的误判在“宝以汗垂之季舅，盛又汗之婿也，必谓忠款无贰”。两层亲缘被当作忠诚的担保。结果是“汗引宝入于外邸，弑之”，并杀太子策与王公卿士百余人。史家用“必谓”二字，既写宝的想法，也暗含评判。关于宝死年，本段作隆安三年；与通行系年可能相差一年，存疑。"],"notes":[["众旅","军队、兵众"],["观衅","观察对方破绽"],["独决圣虑","由君主一人独自决断"],["乙连","地名，宝出龙城后驻军处"],["长上","宫廷或军中长期当值的军士"],["惮役","害怕征战劳役"],["谲","欺骗、用诡计"],["黎阳","渡口及城名，在今河南浚县一带"],["季舅","最小的舅父"],["忠款","忠诚恳切"],["外邸","外面的馆舍"],["惠愍","慕容宝的谥号"]],"think":["慕容宝“敢谏者斩”与《晋书》对后果的叙述，说明了什么决策问题？","这说明决策者把“效率”当成“正确”。慕舆腾替他把拒绝讨论说得冠冕堂皇，宝便堵死了异议渠道。此后兵变、农死、龙城失，都是信息渠道关闭的结果。决策者可以不接受建议，但不应惩罚提建议者。"],"quiz":[["对南伐提出谏阻的是谁？",["慕容盛","慕舆腾","慕容德"],"原文“慕容盛切谏，以为兵疲师老”。"],["宝为什么轻信兰汗？",["汗是垂的季舅，又是盛的岳父","汗手握重兵","汗曾救过宝"],"原文“宝以汗垂之季舅，盛又汗之婿也，必谓忠款无贰”。"],["宝南伐途中引发兵变的是？",["段速骨、宋赤眉","兰汗","慕容德"],"原文“长上段速骨、宋赤眉因众军之惮役也，杀司空、乐浪王宙”。"]],"cards":[["宝拒谏的原话？","吾计决矣，敢谏者斩。"],["谁弑宝于龙城？","兰汗。"]],"line":["吾计决矣，敢谏者斩","会议桌上一旦出现“敢谏者斩”式的收口，后面再正确的意见也说不出来了。"],"tags":["后燕","慕容宝","兰汗"]},"zhuyan_sheng_xi":{"intro":"慕容盛是后燕少有的有谋略的君主：十二岁就能评断叔父，成年后在兰汗的宫内周旋数月，设计诛兰穆、斩兰汗。本段是《晋书》写盛最集中的一篇，既有识人，也有借刀杀人的离间术。读时抓住他怎样利用对手的矛盾。","focus":["少年识人：十二岁的盛评断中山王冲，“智不先众，才不出下，恩未施人，先自骄大”，四个否定短句下得很准；冲不久“为段木延所杀”，应验。随慕容永东行时，他又对柔说“愚则为人所猜，智则危甚巢幕”，处在猜忌之间，愚与智都有危险，所以要“如鸿鹄高飞”。这是一个少年对处境的清醒。","入龙城后的第一步是冒险赴丧，理由是对兰汗性格的判断：“汗性愚近，必顾念婚姻，不忍害我。旬月之间，足展吾志。”事实证明这个判断对了一半，汗的兄弟与其子穆都劝杀盛，是汗自己下不了手。盛靠的不是力量，是对关键人物的心理预估。","离间用得最漂亮：盛对汗说“奇，小儿也，未能办此，必内有应之者。提素骄，不可委以大众”，汗于是杀了兄兰提，兰氏兄弟“皆阻兵背汗”，内部自裂。最后在汗、穆醉酒的夜里，“袒而逾墙，入于东宫”，与李旱等诛穆斩汗。盛登位后“谦揖自卑，不称尊号”，只以长乐王称制，也是稳住人心的姿态。"],"notes":[["中山王","指慕容冲，西燕君主；后以中山王称"],["巢幕","幕上筑巢，喻处境极危"],["鸿鹄","天鹅，喻志向高远"],["罟网","捕兽的网，喻陷阱"],["婚姻","姻亲关系，此处指盛为汗之婿"],["萧墙之难","内部祸乱，典出《论语》"],["腹心","亲信"],["阻兵","凭借兵力对抗"],["袒而逾墙","脱衣赤膊越墙而过"],["东宫","太子所居之宫"],["怗然","安定平息的样子"],["谦揖自卑","谦逊自处，不称尊号"]],"think":["盛赴丧之前说“汗性愚近，必顾念婚姻”，这是冒险还是计算？","是计算，但带有赌的成分。他的依据是汗的性格（愚近）与亲缘（婚姻），这两点确实让汗下不了手；风险在汗身边的兄弟与儿子。史书写汗几次被劝杀盛而“不从”，说明这个判断部分成立。能成事的人，通常会把对方的弱点当作最重要的变量。"],"quiz":[["盛对汗进行离间时，攻击的对象是？",["汗的兄弟兰提","汗的儿子穆","汗的妻子乙氏"],"原文“提素骄，不可委以大众”，汗因而收提诛之。"],["盛十二岁时评断冲“鲜不覆败”，依据是？",["智不先众、才不出下、恩未施人、先自骄大","兵少粮缺","宗室不和"],"这四个否定判断是评断理由。"],["盛诛汗后的态度是？",["谦揖自卑，不称尊号，以长乐王称制","立即称帝","迎宝之子即位"],"原文“盛谦揖自卑，不称尊号。其年，以长乐王称制”。"]],"cards":[["盛十二岁评冲的核心判断？","先自骄大，鲜不覆败。"],["盛如何借兰汗之手去兰提？","说提骄不可委以大众，汗怒而诛之。"]],"line":["我今投命，告以哀穷。汗性愚近，必顾念婚姻，不忍害我","面对强势对手谈判时，先判断对方的软肋在哪里，再决定怎么出场。"],"tags":["慕容盛","后燕","谋略"]},"zhuyan_sheng_zhougong":{"intro":"慕容盛听人歌周公之事，忽然质问群臣：周公真是忠圣吗？这一段是一场君臣辩论，盛提出的论点是“周公之诈”。读时不必纠结周公是否真诈，而要看盛怎样论证，以及这些论证透露出他对忠臣的怀疑，与他严酷猜忌的统治相互印证。","focus":["起因很有意思：盛从周公谈到“我之太宰桓王”，也就是慕容恪，认为恪“辟境千里，以礼让维宗亲，德刑制群后”，功德不输周公，燕国的颂诗却没有述恪之功，所以“乃命中书更为燕颂”。盛是在为本朝权臣争座次，同时把周公的神位降下去。","盛的论证有三步：一是周公“求代其死”，是“诈”；二是“据摄天位而丹诚不见”，使兄弟之间“有干戈之事”；三是“二公足明周公之无罪而坐观成王之疑”，所谓“二公”也未必信任周公。结论是“乃天下之罪人”。这些推论多半是从动机反推，缺乏史料对证，与其说是史论，不如说是对“权臣摄政”的警惕。","臣下的回答也值得读。阳璆、常忠分别举“烈风以悟主”“启金縢而返风”，实际是引经书为证。盛一句“卿徒因成文而未原大理”就把经书当作“成文”挡回去，又说“但时无直笔之史，后儒承其谬谈”。注意这句：他以直笔之名质疑记载，却自己也没有给出新的史料。"],"notes":[["太宰桓王","指慕容恪，谥桓，官太宰"],["闚𨵦","窥伺边境空隙"],["缉穆","和睦"],["敦睦雍熙","和睦兴盛"],["燕颂","颂扬燕国功德的诗篇"],["金縢","周公祝告之书，封存在金属封缄的柜中"],["摄政","代幼主处理国政"],["孺子","幼主，此指成王"],["直笔","据实记载的史笔"],["鸱鸮","《诗经》篇名，相传周公所作"],["疏不间亲","关系疏远者不介入亲近者之间"],["大义灭亲","为大义而不顾亲属"]],"think":["慕容盛批评周公，为什么会同时抬高慕容恪？这透露出什么政治意图？","他把周公和恪放在同一位置作比较，其实是为本朝的宗室辅政者争评价，并借机提示臣下：真正的辅臣要靠“勋道”，不是靠“忠”的名声。同时，对周公“诈”的指控，也暗示他自己对摄政者本能的警惕。读这类“翻案”文章，先看翻案者的现实处境。"],"quiz":[["盛说周公“诈”的第一条理由是？",["武王未尽寿算而周公求代其死","周公杀管蔡","周公制礼作乐"],"原文“武王之筭未尽而求代其死，是非诈乎”。"],["盛在这场论辩里命中书更作燕颂，是为了？",["述慕容恪的功绩","颂扬自己的功德","批评周公"],"原文“乃命中书更为燕颂以述恪之功焉”。"],["盛对群臣用经书辩护的态度是？",["认为只是因袭成文，未原大理","全盘接受","要求再查史料"],"原文“卿徒因成文而未原大理”。"]],"cards":[["盛称周公为什么人？","诈而非忠圣，乃天下之罪人。"],["盛推崇的“太宰桓王”是谁？","慕容恪。"]],"line":["朕见周公之诈，未见其忠圣也","对流传已久的定论提出异议时，要先给出自己的论据，而不是只说“我看不出”。"],"tags":["慕容盛","周公","史论"]},"zhuyan_sheng_lilang":{"intro":"这一单元包含两段：前一段写慕容盛用“召回又出击”的欺骗战术诛灭叛将李朗，后一段写他讨库莫奚后遇变身亡，并附史家的盖棺论定。两段对读，可以看盛的长处在谋，而短处在“峻极威刑”，最后败于猜忌。","focus":["诛李朗一段，盛用的是“反向调度”：先遣李旱讨朗，走到建安又召回，朗以为内变不设备，亲迎魏师，旱乘机袭克令支，在无终斩朗。盛事后向群臣解释“以盈怠其志，卒然掩之”，众皆称“非所及也”。这是一次以兵出奇、以耳目误导的操作，细节完整。","盛对李旱的处置很有分寸：旱因盛杀衞双而弃军逃走，盛却“复其爵位”，并说“旱以刑余之体，效力尽命……故录其忘身之功，免其丘山之罪耳”。既表明法在，又留人情，一赏一罚都有话说。《晋书》这样写，是在展示盛对用人的算计。","史家的收语是整篇重点：“惩宝暗而不断，遂峻极威刑，纤芥之嫌，莫不裁之于未萌”，结果“上下振局，人不自安，虽忠诚亲戚亦皆离贰，旧臣靡不夷灭，安忍无亲，所以卒于不免”。盛死前一年又有慕容国等“禁兵袭盛”，死者五百余人。他的用谋与他的猜忌，其实是一个人的两面。"],"notes":[["辽西太守","辽西郡行政长官"],["累征不赴","多次征召也不来"],["距寇","抵御敌寇"],["令支","地名，在今河北迁安一带"],["无终","地名，在今天津蓟州区一带"],["盈怠","使其自满懈怠"],["杖节死绥","持节殉职，以死守职"],["刑余之体","受过刑罚之人，自谦之词"],["库莫奚","东北古族名"],["禁中","宫禁之内"],["中宗","慕容盛的庙号"],["峻极威刑","把刑罚严厉到极点"]],"think":["盛对李朗“尽灭其族”，与“复其爵位”宽宥李旱，是前后矛盾吗？","不矛盾，但都出于同一逻辑：对威胁自己的人，立即彻底处理；对仍可用的人，给出一次机会并说明理由。问题在于这套逻辑太依赖君主判断，下属无从预期，所以史家说“人不自安”。可预期的规则，才能让忠诚者安心。"],"quiz":[["盛让李旱“旋师”再出击，目的是？",["使李朗放松警惕后突袭","退兵休整","等待魏军退去"],"盛自言“以盈怠其志，卒然掩之”。"],["《晋书》总结盛败亡的原因是？",["峻极威刑，忠诚亲戚亦皆离贰","兵力不足","外敌强大"],"原文“虽忠诚亲戚亦皆离贰，旧臣靡不夷灭，安忍无亲，所以卒于不免”。"],["慕容盛去世时的年龄是？",["二十九岁","四十四岁","二十三岁"],"原文“时年二十九，在位三年”。"]],"cards":[["盛诛李朗的战术要点？","先召回李旱，使朗松懈，再突袭。"],["史家称盛死因？","峻刑猜忌，众叛亲离，安忍无亲。"]],"line":["惩宝暗而不断，遂峻极威刑，纤芥之嫌，莫不裁之于未萌","矫枉过正是管理里最常见的陷阱：看到上一任优柔，就把制度推到苛刻另一头。"],"tags":["慕容盛","后燕","用人"]},"zhuyan_xi_fushi":{"intro":"慕容熙与宠妃苻氏，是后燕宫廷最荒唐的一章：游猎致数千人冻死、为苻氏起殿、思鱼脍而不得即杀、苻氏死后“复启其棺而与交接”、令群臣“含辛以为泪”。读这一段，要看《晋书》怎样用具体细节写失控的权力，并留意末尾一句民间的断语。","focus":["权力失控从“弗之禁也”开始：二苻并美，微行游宴，熙不加禁止，“请谒必从，刑赏大政无不由之”。接着是代价：北登白鹿山，东过青岭，南临沧海，“士卒为豺狼所害及冻死者五千余人”。数字放在游猎之后，不加形容，却比任何形容更重。","苻氏之死与丧礼写得最细。“苻氏尝季夏思冻鱼脍，仲冬须生地黄，皆下有司切责，不得，加以大辟”，要求违反季节，也就等于要求不可能；熙“拥其尸而抚之”，“复启其棺而与交接”，又令群臣哭临，“有泪以为忠孝，无则罪之”，于是“莫不含辛以为泪焉”。含辛为泪，是虚假的悲痛被逼出来的样子。","收束在两处预兆。其一是熙说“朕将随后入此陵”，史家加“识者以为不祥”；其二是轜车太高，“毁北门而出”，“长老窃相谓曰：慕容氏自毁其门，将不久也”。《晋书》这类征兆多是事后附会，但表明当时民间对这场丧事的评价，属于叙事手法，不宜当作史实。"],"notes":[["昭仪","后妃封号"],["游䜩","游乐宴饮"],["公车门","宫门名"],["支解","肢解，一种酷刑"],["冲车","古代攻城战车"],["季夏","夏季最后一个月"],["仲冬","冬季第二个月"],["大辟","死刑"],["躄踊","捶胸顿足地哀号"],["斩缞","最重的丧服"],["哭临","聚集吊丧哭泣"],["徽平陵","苻氏墓号"]],"think":["《晋书》这段为什么写那么多细节而很少评论？","因为荒唐本身就是评价。“思冻鱼脍”“复启其棺”“有泪以为忠孝”这些事，一件就足够说明问题，作者连续写下，读者自己得出结论。这是古代史书的一种常见手法：用事实排列代替议论。但也要留意，史家站在对立立场，细节真实程度仍需存疑。"],"quiz":[["熙游猎期间士卒死亡的数字是？",["五千余人","百余人","一万余人"],"原文“士卒为豺狼所害及冻死者五千余人矣”。"],["群臣“含辛以为泪”的原因是？",["熙规定有泪为忠孝、无泪罪之","苻氏生前恩泽","辛辣食物所致"],"原文“使有司案检哭者，有泪以为忠孝，无则罪之”。"],["长老私下说“慕容氏自毁其门”指的是？",["轜车太高，毁北门而出","苻氏墓毁","宫门失火"],"原文“轜车高大，毁北门而出”。"]],"cards":[["苻氏墓号什么？","徽平陵。"],["熙为苻氏“殉”事件中被赐死的是谁？","慕容隆之妻张氏，熙之嫂。"]],"line":["于是群臣震惧，莫不含辛以为泪焉","被要求表态的场合里，真情和表演很难区分：群臣“含辛以为泪”，就是这种场面的精准写照。"],"tags":["慕容熙","后燕","暴政"]},"zhuyan_xi_fall":{"intro":"后燕的最后一夜：冯跋、张兴等人以慕容云为主，闭门拒守，熙仓促回救，在龙城北门攻不下，出逃后被擒。史家紧接着引一条童谣，说“灭燕”之谶早已写好。读这一段要分清两层：前半是事件，后半是后人的附会。","focus":["事变发动时的人事格局值得留意：“中衞将军冯跋、左衞将军张兴，先皆坐事亡奔”，也就是都是被熙逼逃的人；他们与跋从兄万泥等二十二人结盟，推慕容云为主，并动用“尚方徒五千余人”，也就是宫廷工匠与徒役。这样的班底，说明熙的统治已不得人心。","熙的反应是“此鼠盗耳，朕还当诛之”，随即“收发贯甲，驰还赴难”，说明他当时正在外面为苻氏办丧事。他到龙城“攻北门不克，遂败，走入龙腾苑，微服隐于林中，为人所执，云得而弑之”。几句交代，没有任何战斗场面，节奏很快，显得不堪一击。","童谣是全段的钥匙：“一束藁，两头然，秃头小儿来灭燕。”史家作了拆字说明：藁字去掉上草、下禾，“则禾草俱尽而成高字”，云父名拔、小字秃头，云在三子中最小。这类“谶谣”是事后有解释的叙述，《晋书》把它收在传末，作为天命应验的说明，不能当作熙之亡的原因。"],"notes":[["中衞将军","禁卫军武官"],["坐事","因犯事获罪"],["尚方徒","隶属少府尚方的工匠与刑徒"],["收发贯甲","束好头发披上铠甲"],["龙腾苑","龙城的苑囿"],["微服","改穿平民衣服隐藏身份"],["殡","停柩"],["太元","东晋孝武帝年号"],["义熙","东晋安帝年号"],["童谣","民间流传的谶言歌谣"],["藁","禾秆，也作草名"],["小字","幼名"]],"think":["史家为什么要把童谣与拆字放在慕容熙之死之后？","在史家的叙述里，一朝灭亡有两层说明：人事层面的失道，和天命层面的验证。童谣这类材料出现，是为了把这场政变放入“天命已定”的框架，让其有正当性。读者应该把它与“熙之虐”区分开：前者是附会，后者是《晋书》其余部分记录的实情。"],"quiz":[["谁被推为主发动政变？",["慕容云","冯跋","慕容熙"],"原文“推慕容云为主”。"],["童谣“秃头小儿来灭燕”被解释为指谁？",["慕容云","冯跋","张兴"],"原文说云父小字秃头，云为三子之季。"],["《晋书》算后燕共历几世、几年？",["四世、二十四年","三世、十八年","五世、三十年"],"原文“至熙四世，凡二十四年”。"]],"cards":[["熙死后葬在哪里？","云把他葬在苻氏墓。"],["后燕灭于什么年？","东晋安帝义熙三年。"]],"line":["一束藁，两头然，秃头小儿来灭燕","这类“事后拆字”的预言，常用于说明天命，不宜当作原因：遇到类似说法，先问是谁在何时写下的。"],"tags":["慕容熙","后燕灭亡","谶谣"]},"zhuyan_yun":{"intro":"后燕灭亡后的新君不是慕容氏，而是被宝收为养子的高云。冯跋逼他称王，他“复姓高氏”，改国号仍叫“大燕”，实权则在冯跋手里。这一段篇幅不长，重点是政变后怎样重新安排合法性：谁来做名义上的君，谁来做实际的权臣。","focus":["云的出身有两层说法：一是“宝之养子”，赐姓慕容氏；二是“祖父和，高句骊之支庶，自云高阳氏之苗裔，故以高为氏”。“自云”二字表明高阳氏苗裔之说出自自称，《晋书》不为之担保，属存疑。冯跋劝云时特意强调“公自高氏名家，何能为他养子”，是借这个身份让云摆脱慕容氏的名义。","云的性格被写成“沈深有局量，厚重希言，时人咸以为愚，唯冯跋奇其志度而友之”。可见他与跋早有私交。推戴过程里他两次推辞，“吾婴疾历年”“实惟否德不足以济元元”，是常见的让位语，跋则“扶之而出”。这类场面既要显得被迫，又要完成既定安排。","登位之后的处理很有章法：“复姓高氏”，改元“正始”，国号仍“大燕”，冯跋任“侍中、都督中外诸军事、征北大将军、开府仪同三司、录尚书事、武邑公”，同时“熙之群官，复其爵位”。国号沿用，旧官保留，实权归跋。这是一次尽量减少震荡的改朝。"],"notes":[["养子","收养之子"],["高句骊","即高句丽"],["支庶","旁支庶出"],["苗裔","后代"],["局量","气度、器量"],["希言","少言"],["侍御郎","宫中侍卫官"],["夕阳公","慕容云此前的封爵"],["天亡之时","上天要使其灭亡的时候"],["否德","缺乏德行，自谦"],["元元","百姓"],["开府仪同三司","享受三公待遇的高级荣衔"]],"think":["高云为什么在称王后“复姓高氏”，而不继续用慕容姓？","这能与慕容熙、慕容宝一脉切开：新政权不再算作“继承后燕”，而是新朝。同时保留“大燕”国号，又维持了一部分旧臣的认同。这是在新旧之间找平衡：改姓给新君一个独立身份，沿用国号则降低政变的冲击。"],"quiz":[["谁把政变的谋划告诉高云？",["冯跋","张兴","慕容熙"],"原文“熙之葬苻氏也，冯跋诣云，告之以谋”。"],["云称王后国号与年号分别是？",["大燕、正始","北燕、太平","后燕、永康"],"原文“改元曰正始，国号大燕”。"],["原文对云早年评价是？",["沈深有局量，厚重希言","轻果无志操","勇冠三军"],"原文如此。"]],"cards":[["云祖父之来源？","高句骊之支庶，自云高阳氏苗裔。"],["谁任都督中外诸军事？","冯跋。"]],"line":["慕容氏世衰，河间虐暴，惑妖淫之女而逆乱天常","大变局前要先陈述“为什么必须动”：理由说得清，参与者才站得稳。"],"tags":["高云","冯跋","北燕前史"]},"zhuyan_de_zhuan":{"intro":"慕容德，字玄明，是慕容皝之少子，后来在滑台称王，开创南燕。《晋书》写他前半生，主要是两件事：他在慕容暐面前提出乘衅讨坚，未被采纳；淝水之后他又劝止暐带走苻坚的张夫人。看这两件事，可知他“识者言其有远略”的评价从哪里来。","focus":["“年未弱冠，身长八尺二寸，姿貌雄伟，额有日角偃月重文”，是史书写帝王相貌的惯例，日角偃月之类说法属于传说式的描写，不是证据。后面的“博观群书，性清慎，多才艺”才是德的性格底色。垂对他说“非复吴下阿蒙也”，借吕蒙的典故，指德的见识提高了。","他的政治判断在第一件事中就出现：苻双据陕、苻柳起兵枹罕，“德劝暐乘衅讨坚，辞旨慷慨”，但“暐竟不能用”。这并非德的决策被验证，而是史书借此提示：燕在前秦下的复国机会，他早已看到。后面谏暐“昔句践栖于会稽，终获吴国。圣人相时而动，百举百全”，仍是同一思路。","第二件事更细：坚败后与张夫人走散，暐将护送夫人，德“正色”谏之：“昔楚庄灭陈，纳巫臣之谏而弃夏姬。此不祥之人，惑乱人主，戎事不迩女器，秦之败师当由于此。”他借夏姬的典故说，不应收留敌方的宠妃。暐不从，德驰马而去。德的用典和决断都在这一小段里。"],"notes":[["皝","慕容皝，前燕奠基君主之一"],["日角偃月","相术所谓额骨隆起如日、如月，指帝王之相"],["散骑常侍","皇帝近侍官，多为荣衔"],["枹罕","地名，在今甘肃临夏一带"],["乘衅","利用对方的破绽"],["非复吴下阿蒙","原指吕蒙学业大进；喻人长进显著"],["枋头之役","前燕与东晋桓温交战的战役"],["夏姬","春秋时有名的美女，常被视为祸水"],["戎事不迩女器","军事行动不亲近女子"],["句践","越王勾践"],["会稽","勾践被困之地"],["荥阳","地名，在今河南荥阳"]],"think":["德谏暐时为什么要引夏姬、勾践这两个典故？","夏姬用来说明“战败之际收留敌方宠妃”的风险，是把一个小事放大成败亡原因；勾践用来说明“败中求复”，要利用对方弱点。两典故指向同一结论：不要被眼前小事牵制，抓住大势。引典不是炫耀，而是让听者在熟悉的故事里接受判断。"],"quiz":[["垂说“非复吴下阿蒙”是在称赞德什么？",["器识长进","武艺高强","出身高贵"],"原文“汝器识长进，非复吴下阿蒙也”。"],["德反对暐护送张夫人的理由是？",["夏姬式的不祥之人，惑乱人主","张夫人身份低微","路途遥远"],"原文借“楚庄灭陈，纳巫臣之谏而弃夏姬”说明。"],["德劝暐“乘衅讨坚”的背景是？",["苻双、苻柳起兵反叛","淝水大败","慕容垂起兵"],"原文“苻坚将苻双据陕以叛，坚将苻柳起兵枹罕”。"]],"cards":[["德是谁之子？","慕容皝的少子。"],["德用什么典故劝暐不要收留张夫人？","楚庄王弃夏姬。"]],"line":["圣人相时而动，百举百全","做重大决定要看时机：时势到了才出手，才可能“百举百全”。"],"tags":["慕容德","南燕前史","谋略"]},"zhuyan_de_shouye":{"intro":"魏将拓拔章攻邺，慕容德的别驾提出“魏不可击者四，燕不宜动者三”，主张不出击、深沟高垒。这是《晋书》里难得的一份完整的守势论证。读时按“魏的弱点”“燕的弱点”“后续办法”三段拆开，再看德怎样用人心稳住局面。","focus":["论证结构很整齐：先说魏不可击四：悬军远入，利在野战；深入近畿，顿兵死地；前锋既败，后阵方固；彼众我寡。再说燕不宜动三：官军自战其地，动而不胜，城郭未修。前四条是对方的优势，后三条是己方的弱点，合起来就是不出击。","处理办法是“深沟高垒，以逸待劳”，关键依据是对方补给：“彼千里餽粮，野无所掠，久则三军靡资”。魏军孤军深入，补给线越长，越被动；守方只要不被诱出，就能赢。这是兵家常说的“以逸待劳”，史书用别驾口吻说出，德回答“良、平之策也”，表示认可。","后面的发展印证了这一思路：章、卢之间“内相乖争，各引军潜遁”，魏司马丁建来降，说章师已老。但德的作用不止于采纳，“亲飨战士，厚加抚接，人感其恩，皆乐为致死”，因为援兵不来，“众大惧”，能稳住军心靠的是亲自慰劳。守城不只是战术，也是人心工程。"],"notes":[["别驾","州刺史的佐官"],["悬军","孤军深入、后无接应的军队"],["野战","在城外开阔地作战"],["顿兵死地","把军队停在没有退路的地方"],["以逸待劳","养足精神等待疲惫的敌人"],["深沟高垒","挖深壕沟、筑高壁垒"],["餽粮","运送粮食"],["靡资","没有物资可用"],["良、平","张良与陈平，汉初谋臣"],["亲飨战士","亲自宴请慰劳士兵"],["师老","军队久战疲惫"],["乖争","互相争执"]],"think":["“魏不可击者四，燕不宜动者三”是谁的优势？这种论证有什么缺点？","它同时承认对方的四个优势和己方的三个弱点，结论是不动，实际是把主动权让给对方。好处是稳，缺点是依赖对方内部生变和补给困难，若魏军有稳定补给或统一指挥，这一策可能让守方被动。能成事的前提是“久则三军靡资”真会发生。"],"quiz":[["别驾的核心策略是？",["深沟高垒，以逸待劳","出城野战","弃城南走"],"原文“不如深沟高垒，以逸待劳”。"],["魏军的困难在哪里？",["千里餽粮，野无所掠","兵员不足","没有骑兵"],"原文“彼千里餽粮，野无所掠，久则三军靡资”。"],["魏军撤离的直接起因是？",["章、卢二将内相乖争","邺城投降","燕军追击"],"原文“会章、卢内相乖争，各引军潜遁”。"]],"cards":[["魏不可击的四条之一？","悬军远入，利在野战。"],["德如何稳定军心？","亲飨战士，厚加抚接。"]],"line":["不如深沟高垒，以逸待劳","对手占据主动时，先把阵脚站稳，让时间去消耗对方的补给与耐心。"],"tags":["慕容德","守势","邺城"]},"zhuyan_de_nan":{"intro":"后燕在北魏打击下崩溃，慕容德带着四万户南渡黄河，在滑台称燕王，南燕由此起步。这一段先是慕容麟的献策，再写渡河遇险与“冰合”的传说，最后是称元年、置百官。读时区分三层：策略、神异叙述、制度安排。","focus":["慕容麟的计划很具体：不守邺，趁魏军未至“拥众南渡，就鲁阳王和，据滑台而聚兵积谷，伺隙而动”。他的判断是“城大难固，且人情沮动，不可以战”；魏拔中山后“不过驱掠而返”，不会久留；如果魏军撤走，德再起兵，“魏则内外受敌”。这是用空间换时间的撤退设计。","渡河一段用了神异叙述：“遇风，船没，魏军垂至，众惧，议欲退保黎阳。其夕流凘冻合，是夜济师，旦，魏师至而冰泮，若有神焉。”史书连用“其夕”“是夜”“旦”，把时间压缩得很紧，随后黎阳津改名天桥津。冰合是否史实，无法核对，应把它看作当时用来解释这次南渡的天命叙事。","称元年的细节有存疑：“于是德依燕元故事，称元年，大赦境内殊死已下，置百官。”“燕元故事”所指何事，本段未说明，是否指前燕旧例或年号，存疑。人事安排倒清楚：麟为司空、领尚书令，法为中军将军，慕舆拔、丁通为左右仆射。麟随后因“河间有麟见”以为己瑞而谋乱，被赐死。祥瑞被拿来做政治借口，处理很快。"],"notes":[["义台","邺城台观名，慕容麟由此奔邺"],["沮动","人心沮丧动摇"],["滑台","地名，在今河南滑县一带"],["伺隙","等待机会"],["恋旧之士","眷恋旧朝的人"],["流凘","河中浮冰"],["冰泮","冰层融化"],["天桥津","慕容德为黎阳津所改之名"],["景星","吉祥之星"],["殊死","犯死罪者"],["称元年","自行建元，称第一年"],["麟见","出现麒麟，古人视为祥瑞"]],"think":["“流凘冻合”“冰泮”这类叙述，今天应怎样处理？","可以理解为：某次渡河确实顺利，当事人把它解释为天意。史书保留并命名新渡口，是在为新政权制造合法性。读时分清两层：渡河成功是事实，冰合如神则是叙述。这种叙述可以用来研究当时的政治宣传，不应当作自然现象的记录。"],"quiz":[["慕容麟建议南迁的第一站是？",["滑台","邺城","黎阳"],"原文“据滑台而聚兵积谷”。"],["黎阳津因何改名？",["渡河时冰合，传为神助","德出生于此","战胜北魏"],"原文“遂改黎阳津为天桥津”。"],["麟最后的结局是？",["以河间麒麟为己瑞谋乱被赐死","封为司空，善终","战死"],"原文“潜谋为乱，事觉，赐死”。"]],"cards":[["德率多少户南迁？","四万户，车二万七千乘。"],["德称元年后任司空的是谁？","慕容麟。"]],"line":["及魏军未至，拥众南渡","大势已去时，先保存实力、换地方再谋后图，比硬守更现实。"],"tags":["慕容德","南燕","滑台"]},"zhuyan_de_zhanghua":{"intro":"慕容德已摄位，慕容宝却从龙城南奔而来，君臣要在“奉迎”与“称尊”之间选一条路。张华一句“陛下若蹈匹妇之仁，舍天授之业，威权一去，则身首不保”，把问题说到根上。这一段同时写了另一个人物：中黄门令赵思，他拒绝为德所用。","focus":["德的第一反应是退让：“吾将具驾奉迎，谢罪行阙，然后角巾私第。”这既是试探，也是一种自保，若群臣顺着说，他就能名正言顺地不称尊。张华的回答完全不同：“争夺之世，非雄才不振；从横之时，岂懦夫能济”。他把礼法转成利害，威权一去，则“身首不保”。","德随即说出内心犹豫：“吾以古人逆取顺守，其道未足，所以中路徘徊，怅然未决耳。”“逆取顺守”是以非正当方式夺取、再用正当方式守住，他担心前一步不足以支撑后一步，也就是缺乏正统性。随后派慕舆护去问宝虚实，自己“率壮士数百，随思而北，因谋杀宝”，实际已在为最坏结果做准备。","赵思的一段是反面：德欲重用，思回答“昔关羽见重曹公，犹不忘先主之恩”，并指责德“不能率先群后以匡王室，而幸根本之倾为赵伦之事”。德“怒，斩之”。《晋书》让一个宦官说出最直接的道德批评，再让德杀之，显出在“称尊”这件事上，德并不坦然。"],"notes":[["慕容钟","慕容德宗室，首议劝德称尊号者"],["中黄门令","宫中宦官官名"],["嗣帝","继位的皇帝，此指宝"],["行阙","皇帝出行时的临时宫阙"],["角巾私第","戴角巾回家，指退隐"],["从横","合纵连横，指纷争之世"],["匹妇之仁","妇人式的小仁小义"],["逆取顺守","以武力夺取，以仁德守成"],["关羽见重曹公","关羽受曹操礼遇，仍念刘备"],["赵伦","赵王司马伦，西晋篡位者"],["申胥哭秦","申包胥向秦哭师救楚，喻忠臣求援"],["刑余","受过宫刑的人，指宦官"]],"think":["德为什么要问群臣“卿等以为何如”？这是真心咨询，还是自导自演？","两种成分都有。他的“谢罪行阙”既是对宝的尊重，也是对群臣的试探：若群臣沉默，他可以顺势退让；若有人反对，他便有了继续的借口。张华的答话把“退让”的成本说透，德于是以“逆取顺守”自辩。他后来继续称尊，说明他早已有决定，只缺理由。"],"quiz":[["张华劝德的核心理由是？",["舍天授之业，威权一去则身首不保","宝已无力反击","魏军将至"],"原文“若蹈匹妇之仁，舍天授之业，威权一去，则身首不保”。"],["德所说“逆取顺守”表达的是？",["担心取得方式不足以支撑后来的守成","夸耀自己仁德","请求宝的原谅"],"原文“其道未足，所以中路徘徊”。"],["赵思被杀的原因是？",["拒绝任用并指责德不匡王室","泄露军情","谋杀德"],"思指责“不能率先群后以匡王室”，德“怒，斩之”。"]],"cards":[["张华对德的提醒？","若退让，则身首不保。"],["赵思引什么人物表明忠心？","关羽，不忘先主之恩。"]],"line":["夫争夺之世，非雄才不振；从横之时，岂懦夫能济","形势剧烈变动时，犹豫就是代价：此时需要的是决断，不是姿态。"],"tags":["慕容德","劝进","张华"]},"zhuyan_de_xi":{"intro":"南燕攻青州，齐郡太守辟闾浑拒不接受招谕，慕容钟传檄青州诸郡。这篇檄文是了解当时军事宣传话语的好样本：先讲天命，再数敌罪，然后夸兵威，最后开出赏格。读完檄文，再看辟闾浑被擒、张瑛从容就死，这一段情节完整。","focus":["檄文的结构非常清楚。第一层讲历数：“宣王龙飞于危周，光武凤起于绝汉”，以中兴之君为先例；第二层数罪：辟闾浑“于覆巢之下，蒙全卵之施”，却“复袭凶父乐祸之志，盗据东秦，远附吴越”；第三层夸兵威：“都督元戎一十二万，皆乌丸突骑，三河猛士”；第四层给出赏格：“有能斩送浑者，赏同佐命”。","文中的数字与比喻是宣传性质的：“七州之众二十余万”“元戎一十二万”不能直接当作兵力，与前文“徐兖之士附者十余万”并读，只能当作声势。典故也服务说服：韩信伐齐“有征无战”，耿弇讨步“克不移朔”，窦融归汉“荣被后裔”，彭宠盗逆“身死奴仆”，一正一反，劝降对象在眼前。","结局很利落：“诸郡皆承檄降于德”，浑逃魏被追斩于莒城。参军张瑛平时替浑写檄，辞多不逊，被擒后说“浑之有臣，犹韩信之有蒯通”，德“初善其言，后竟杀之”。这一反复，说明德起初愿以大度收人，最终仍没有放过。"],"notes":[["檄","古代用于征讨或晓谕的文书"],["历数","天命的次序"],["龙飞","喻帝王兴起"],["长鲸","喻凶暴之敌"],["覆巢之下","巢倾卵破，喻国亡家破"],["东秦","指青州一带"],["岱宗","泰山"],["乌丸突骑","乌桓骑兵，慕容氏常用的精锐"],["三河","河东、河内、河南，泛指中原"],["窦融","东汉初割据河西，后归附光武"],["彭宠","东汉初渔阳太守，叛汉被杀"],["蒯通","韩信谋士，曾劝韩信反汉"]],"think":["檄文里的“二十余万”“一十二万”该怎样用？","作为宣传，这些数字的作用是吓住对手，使其不战而降；作为史料，应当与其他记载互证。从传文自身看，德“进据琅邪，徐兖之士附者十余万”，两数相近，说明规模确实很大，但具体精确数字仍应存疑。读檄文要问两个问题：想让谁相信？他们有多大可能验证？"],"quiz":[["檄文中批评辟闾浑的核心说法是？",["受恩而不知报，反袭凶父之志","贪图财货","暴虐百姓"],"原文“曾微犬马识养之心，复袭凶父乐祸之志”。"],["张瑛自比什么人物？",["韩信的蒯通","萧何","张良"],"原文“浑之有臣，犹韩信之有蒯通”。"],["德对张瑛的处置是？",["初善其言，后竟杀之","赦免任用","流放"],"原文如此。"]],"cards":[["谁传檄青州诸郡？","慕容钟。"],["檄中开出的赏格？","能斩送浑者，赏同佐命。"]],"line":["此非古今之吉凶，已然之成败乎","劝人改变立场时，先摆出已经发生的结局，比空泛的威胁有力。"],"tags":["南燕","檄文","辟闾浑"]},"zhuyan_de_hanfan":{"intro":"桓玄篡晋之际，不少晋臣奔向南燕，中书侍郎韩范上疏建议南燕乘机南下，德却回答“且韬戈耳”。这一段把一次战略选择写得很完整：建议、答复、群议、检阅、又因病作罢。重点是判断：为什么好机会最后没用上。","focus":["韩范的奏疏有清晰的逻辑：“夫帝王之道，必崇经略。有其时无其人，则弘济之功阙；有其人无其时，则英武之志不申。”然后分析当前时机：“桓玄逆篡，虐逾董卓”，江淮“守备之事盖亦微矣”，只要“步骑一万，建雷霆之举”，即可“望旗草偃，壶浆属路”。最后用“机过患生”收束，要求不要错过。","德的答复回避了正面交锋：他先说自己“缮甲待衅，为日久矣”，引用少康复国，再说“但欲先定中原，埽除逋孽”，所以暂时“韬戈”。随后“咸以桓玄新得志，未可图，乃止”。群臣的意见是否稳妥，不好断言；但事实是桓玄随即败，南燕没有趁势行动，“俄闻桓玄败”之后又因德寝疾而罢兵。","讲武一段的数字需谨慎：“步兵三十七万，车一万七千乘，铁骑五万三千”，对于一个据三齐之地的政权来说，这一数字与实际兵力是否相符，存疑，应视为声势。德对刘轨、高雅之说“郤克忿齐，子胥怨楚”，是对降来的晋臣讲复仇之志，收拢人心。"],"notes":[["桓玄","东晋权臣，篡晋称帝"],["经略","筹划治理与征战"],["弘济","大力救助、成就"],["董卓","东汉末权臣，暴虐"],["草偃","风吹草倒，喻望风而降"],["壶浆","盛着酒浆迎军的民众"],["少康","夏代中兴之君"],["逋孽","逃亡的余孽"],["韬戈","收起兵器，暂不用兵"],["讲武","检阅演练军队"],["郤克","春秋晋国大夫，曾为受辱于齐而求报复"],["子胥","伍子胥，因父兄被害投吴伐楚"]],"think":["德为什么不接受韩范的建议？","原文给出的理由是“先定中原”与“桓玄新得志，未可图”，实际上也有对内部实力的顾虑：南燕刚立，城郭未固。机会不会等人，但也不是任何机会都能抓。判断的标准是：抓住机会后能否守住。德的选择偏保守，但随后桓玄速败，也使韩范的“机过患生”没有立即应验。"],"quiz":[["韩范上疏的要点是？",["乘桓玄之乱南下，以一万步骑直指江岸","继续固守三齐","向魏称臣"],"原文“若以步骑一万，建雷霆之举，卷甲长驱，指临江会”。"],["德为何暂不行动？",["先定中原，且桓玄新得志未可图","兵力不足","魏军压境"],"原文“但欲先定中原”“咸以桓玄新得志，未可图”。"],["最终罢兵的直接原因是？",["德寝疾","大雨","晋军来援"],"原文“而德寝疾，于是罢兵”。"]],"cards":[["韩范的结论？","天与不取，悔将及焉。"],["德讲武时对谁说“郤克忿齐，子胥怨楚”？","刘轨、高雅之。"]],"line":["有其时无其人，则弘济之功阙；有其人无其时，则英武之志不申","人和时机往往不同时出现：只有一方具备时，要想清楚缺的是哪一边。"],"tags":["慕容德","南燕","战略"]},"zhuyan_chao_jindao":{"intro":"慕容超的身世像一部小说：慕容德的侄子，生在羌中，随人流转到长安，装疯行乞，被姚兴看轻后才得离开，最后凭一把金刀与祖母遗言回到广固。本段主要写这条回家之路，要看他怎样靠“晦匿”保全自己。","focus":["金刀是全篇的线：“德之南征，留金刀而去”；祖母公孙氏临终“授超以金刀”，嘱“若天下太平，汝得东归，可以此刀还汝叔也”；到广固，超“呈以金刀，具宣祖母临终之言，德抚之号恸”。一件器物既是信物，也是身份证明，在没有别的凭据的情况下，它承担了“认亲”的全部作用。","救命的人也有交代：呼延平，“德之故吏也，尝有死罪，德免之”，于是在垂诛德诸子时救出纳母与有孕的段氏，“生超焉”。超后来娶平之女，以报厚惠。史书让一个旧恩贯穿三代，是本篇的伦理主线。","晦匿是关键：超“阳狂行乞”，姚绍见而异之，劝兴以爵位拘留，兴召见后“大鄙之”，说“妍皮不裹痴骨，妄语耳”，超因此“得去来无禁”。装疯，是他在异国能活下来的方法。回广固后，“德无子，欲以超为嗣，故为超起第于万春门内，朝夕观之”，超“入则尽欢承奉，出则倾身下士”，一步步取信，立为太子。"],"notes":[["北海王","德之兄纳的封号"],["娠","怀孕"],["狱掾","监狱属吏"],["耄","年老"],["阳狂","假装疯狂"],["晦匿","隐藏自己"],["妍皮不裹痴骨","谚语，指外表漂亮的人不会是真愚"],["广固","南燕都城，在今山东青州一带"],["抚之号恸","抱着他放声痛哭"],["万春门","广固宫门名"],["嗣","继承人"],["倾身下士","降低身份结交贤士"]],"think":["超“阳狂行乞”的做法，是否有其他选择？","在姚兴手下，他是燕宗室的后裔，身份本身就是危险；表现出才干会招致拘禁，装疯却能让对方放松。他唯一能依靠的是对方的轻视。这一策略代价很高，但在没有军队、没有同盟时，是少数可用的办法。"],"quiz":[["金刀的作用是？",["证明身份的信物","武器","赏赐"],"祖母“授超以金刀”，超到广固“呈以金刀”。"],["姚兴为什么放任超？",["以为他真是痴人","畏惧德","收受贿赂"],"兴说“妍皮不裹痴骨，妄语耳”。"],["救出超母子的是谁？",["狱掾呼延平","姚绍","吕光"],"原文“狱掾呼延平，德之故吏也，尝有死罪，德免之”。"]],"cards":[["超是德的什么人？","兄纳之子，即侄子。"],["超回国靠什么凭证？","祖母遗赠的金刀。"]],"line":["若天下太平，汝得东归，可以此刀还汝叔也","临终托付要说清条件和凭据：一句话和一件信物，可以走过十几年的流亡路。"],"tags":["慕容超","南燕","身世"]},"zhuyan_chao_xian":{"intro":"刘裕北伐，南燕君臣在东阳殿议如何抵御。公孙五楼提出上、中、下三策，慕容超偏选了被评为下策的“纵贼入岘”。这一段是南燕亡国的关键，看点在三策的差别、慕容超的理由，以及慕容镇的预言。","focus":["三策层次分明。上策：据大岘，不让晋军入；同时遣精骑二千“循海而南，绝其粮运”，段晖率军“缘山东下”，腹背夹击。中策：“依险自固”，坚壁清野，“余悉焚荡，芟除粟苗，使敌无所资”。下策：“纵贼入岘，出城逆战”。三策的共同逻辑是：对方利在速战，就设法拖。","超的反对理由可以逐条看：“京都殷盛，户口众多，非可一时入守”“青苗布野，非可卒芟”，说明坚壁清野代价太大；再说“今据五州之强，带山河之固，战车万乘，铁马万群，纵令过岘，至于平地，徐以精骑践之，此成擒也”。这是对自己骑兵的自信，也是对代价的回避。《晋书》让他的话说得很满。","反对者的话更有分量。慕容镇用成安君不守井陉、诸葛瞻不据束马之崄两个先例，主张“天时不如地利，阻守大岘”。贺赖卢“苦谏，不从”，退而说“上不用吾计，亡无日矣”。镇出，对人说“酷似刘璋矣”，超“闻而大怒，收镇下狱”。从这里可以看出：不是没有对策，而是无人能改变决策者的意志。"],"notes":[["大岘","山名，地势险要，今山东临朐一带"],["旷日延时","拖延时间"],["沮其锐气","挫败其锐气"],["坚壁清野","加固防守，焚毁野外资财"],["芟除","割除"],["下策","最差的方案"],["殷盛","繁盛"],["井陉","太行山口，韩信破赵之地"],["束马之崄","诸葛瞻未守的险要之地"],["刘璋","益州牧，因懦弱失蜀"],["文身","身刺花纹，指被夷化"],["修城隍","整治城墙与护城河"]],"think":["超坚持放晋军入岘，在军事上有无合理之处？","有一定道理：平原作战对骑兵有利，若晋军步兵孤军深入，确有机会歼灭。问题在于，这一设想的前提是骑兵能取胜，而且没有备选方案。三策中的上策、中策都能防止风险，超只押一种可能，且不接受谏言，所以史家把它写为亡国关键。"],"quiz":[["公孙五楼的上策是？",["据大岘，另遣精骑绝粮运，段晖夹击","坚壁清野","出城逆战"],"原文“宜据大岘，使不得入……腹背击之，上策也”。"],["超不愿坚壁清野的理由之一是？",["青苗布野，非可卒芟","缺乏人手","魏军压境"],"原文“青苗布野，非可卒芟”。"],["慕容镇以什么人物作比批评超？",["刘璋","刘备","项羽"],"原文“酷似刘璋矣”。"]],"cards":[["五楼的下策是什么？","纵贼入岘，出城逆战。"],["谁“苦谏，不从”？","贺赖卢。"]],"line":["天时不如地利，阻守大岘，策之上也","面对强敌，先把险要守住，比寄望一场决战更稳妥。"],"tags":["慕容超","南燕","大岘"]},"zhuyan_chao_lin":{"intro":"晋军度岘后，临朐一战败，超退守广固，城被围。这一段写南燕亡国前最后的内部变化：张纲反戈、韩范降晋、超还想“请为藩臣”。读时盯住三个人，他们的选择一步步拆掉守城的信心。","focus":["败得很快：超遣段晖等进据临朐，晋军度岘后，超“率卒四万就晖等于临朐”。五楼抢占川源失败，檀韶攻破临朐，超“单骑奔段晖于城南”，晖被斩。战斗过程没有描写，数个动词一路排下，节奏近于崩塌。","张纲与韩范是转折。张纲被派去长安乞师，回来后“遂奔于裕”，裕令他“周城大呼”，对守军喊“勃勃大破秦军，无兵相救”，破的是援兵的预期。韩范则出使乞师回来，处境转为：“天其灭燕乎！”收到裕书后降晋。裕问他“卿欲立申包胥之功，何以虚还”，范答“智者见机而作”。","读到这里，超曾“谢之曰”，承认“专固自由，覆水不收，悔将何及”；慕容镇仍主张“更决一战”，慕容惠则主张乞援，守与战意见再次分裂。史书最后写异象：“东莱雨血，广固城门鬼夜哭”，属于亡国前的灾异叙述。本段所涉战役在《宋书》《资治通鉴》另有记载，这里只据《晋书》，细节可再对读，我未逐条核对。"],"notes":[["临朐","地名，在今山东临朐"],["川源","水源，战场上争夺的水源地"],["咨议参军","军府参谋官"],["小城","广固内城"],["六奇","汉初陈平六出奇计，借指谋略"],["乞师","请求出兵援助"],["攻具","攻城器械"],["藩臣","对朝廷称臣的属国"],["啗以重利","用厚利诱使"],["申包胥","春秋楚臣，赴秦乞师救楚"],["见机而作","看准时机行动"],["雨血","天降血雨，灾异之说"]],"think":["张纲的“反戈”为什么比一次战败更致命？","战败是军事损失，反戈则带走了关键信息：援兵是否会来。守城的底线靠“有人来救”撑着，张纲向城里喊“无兵相救”，等于拆掉了这个预期。晋军后来又引诱韩范，同样是攻心。围城战里，信息比兵器更重要。"],"quiz":[["裕让张纲周城大呼的内容是？",["勃勃大破秦军，无兵相救","南燕主已降","晋军粮尽"],"原文如此。"],["韩范降晋时说“智者见机而作”，意思是？",["看清形势后顺势行动","坚守不降","等待救兵"],"原文“智者见机而作，敢不至乎”。"],["超对裕的请求是？",["称藩臣，以大岘为界，献马千匹","举城投降","出城决战"],"原文“请为藩臣，以大岘为界，并献马千匹”。"]],"cards":[["谁在临朐被斩？","段晖。"],["刘裕用谁劝降韩范？","张俊建议诱范，裕致书招之。"]],"line":["智者见机而作，敢不至乎","局势已定时，早一步选择，往往比晚一步更主动。"],"tags":["慕容超","南燕灭亡","刘裕"]},"zhuyan_fengba_qi":{"intro":"冯跋原是后燕的中衞将军，高云被杀后，被众人推为天王，国号仍叫“燕”，史称北燕。这一段交代家世、起事、让位、任命与封弟。读时注意：叙事里年代记载与通行系年不合，属存疑。","focus":["出身只写到“长乐信都人”，说“其先毕万之后”，并把冯姓的由来附到“食采冯乡”，这是追溯世系的惯例，史实依据不足。接着写他的性格：“幼而懿重少言，宽仁有大度，饮酒一石不乱”，并写“所居上每有云气若楼阁”“夜见天门开”，是为日后称王做的预兆铺垫，属于神异叙述。","起事一幕写得很紧：云被幸臣离班、桃仁所杀，跋“升洪光门以观变”，帐下督张泰、李桑说“此竖势何所至！请为公斩之”，于是“奋劔而下”，斩杀二人。众推跋为主，他却先说“范阳公素弗才略不恒”，素弗辞曰“臣闻父兄之有天下，传之于子弟，未闻子弟藉父兄之业而先之”，最终“群臣固请，乃许之”。这是一次典型的“让三次”场面。","称王时年代有疑：本段作“以太元二十年乃僭称天王于昌黎”，但太元只到二十一年（396），与跋称天王于409年（义熙五年）的通行系年及后文“凡二十有八载”不相合，存疑。国号“燕”、建元“太平”则明确。任命上，弟素弗为侍中、车骑大将军、录尚书事，弘为征东大将军，从兄万泥与从兄子乳陈各镇一方，宗室与功臣并用。"],"notes":[["长乐信都","冯跋籍贯，今河北冀州一带"],["毕万","春秋晋国大夫，传说为冯氏远祖"],["食采","受封领地，享其赋税"],["懿重","美好而稳重"],["符命","天命的征兆"],["帐下督","主将帐下的卫队长官"],["靖乱","平定祸乱"],["缀旒","喻政权悬而不固"],["天工","上天之事，喻帝业"],["昌黎","郡名，北燕建国之处"],["僭称","非正统而自称"],["录尚书事","总领尚书台政务"]],"think":["冯跋称王时为什么必须经过“让”的程序？","一是确认合法性：被推而非自求，才显得符合天命与众望；二是内部协调：素弗等宗亲表态辞让，也等于表态支持。程序简短，意图实在。读这类“辞—固请—乃许”的描写，先看让位对象是不是当事人的得力亲信：多半是，因为他们也是新政权的分配者。"],"quiz":[["冯跋称王后国号是？",["燕","魏","秦"],"原文“即国曰燕”。"],["斩杀离班、桃仁的是？",["张泰、李桑","冯素弗","冯弘"],"原文“桑斩班于西门，泰杀仁于庭中”。"],["关于称王年代，《晋书》本段记载有何问题？",["作太元二十年，与通行系年不合，存疑","作义熙五年，与通行系年一致","没有记年"],"太元二十年即395年，而北燕建国通行系年为409年。"]],"cards":[["冯跋的小字？","乞直伐。"],["跋任命素弗为什么官？","侍中、车骑大将军、录尚书事。"]],"line":["未闻子弟藉父兄之业而先之","在家族或团队里谈让位，先把原则说清楚，再谈该谁上：素弗这一句把规矩和人情都顾到了。"],"tags":["冯跋","北燕","建国"]},"zhuyan_wanni":{"intro":"北燕立国之初，宗室万泥、乳陈因没有入朝为公辅而心怀怨恨，据白狼叛乱，被冯弘夜战平定。冯跋随后下诏“前朝苛政，皆悉除之”，又处理马弗勤受贿案。这一段是北燕初年收拢人心、整顿吏治的缩影。","focus":["叛乱的起因是分配不满：“万泥、乳陈自以亲而有大功，谓当入为公辅，跋以二藩任重，因而弗征，并有憾焉。”跋的理由是“二藩任重”，他们的理由是“亲而有大功”。乳陈“按劔怒曰：大丈夫死生有命”，主战，而冯弘提前判断对方夜袭，“密严人课草十束，畜火伏兵以待之”，“俘斩无遗”。","弘劝降的话值得读：“裂土疏爵，当与兄弟共之，奈何欲寻干戈于萧墙，弃友于而为阏伯！”他先讲共享成果，再讲内部之争的后果。叛者一旦投降，却被“皆斩之”，可见说降与处置是两回事。","下诏与断案是整顿的两手。诏书：“赋役繁苦，百姓困穷。宜加宽宥，务从简易，前朝苛政，皆悉除之。”李训带宫中珍宝行贿，马弗勤以训为方略令，被人写于阙下碑。跋说“弗勤宜肆诸市朝”，但因“大业草创”而“其特原之”，李训则“东市考竟”。重刑一个小人，宽恕一个大臣，这是一种有选择的整顿。"],"notes":[["白狼","地名，叛军所据之处"],["二藩","指万泥、乳陈镇守的地区"],["斫营","夜袭营寨"],["萧墙","宫内屏风，喻内部"],["友于","兄弟之情"],["阏伯","高辛氏之子，与弟实沈不和"],["兰台都官","监察官署"],["赇","贿赂"],["方略令","官名，主管谋略事务"],["阙下碑","宫阙前的碑，供人揭发"],["考竟","拷问至死"],["肆诸市朝","在闹市中处死示众"]],"think":["冯跋为什么杀李训而宽恕马弗勤？","跋自己的解释是“大业草创，彝伦未叙，弗勤拔自寒微”。实际是政治考虑：新政权需要人用，宽恕大臣可以稳住朝局，杀小人又足以示警。这种处理能在短期内稳定局面，但留下了“重小轻大”的先例，对长远吏治未必有利。"],"quiz":[["万泥、乳陈叛乱的原因是？",["未被召入朝任公辅而心怀怨恨","被削爵","魏军挑唆"],"原文“谓当入为公辅，跋以二藩任重，因而弗征”。"],["冯弘如何击败夜袭？",["提前备火，设伏兵","主动出击","诈降"],"原文“密严人课草十束，畜火伏兵以待之”。"],["跋对李训的处置是？",["东市考竟","贬官","罚金"],"原文“可东市考竟”。"]],"cards":[["跋诏书里取消的是？","前朝苛政。"],["谁以李训为方略令？","马弗勤。"]],"line":["赋役繁苦，百姓困穷。宜加宽宥，务从简易","新政权刚立时，先减负担、不折腾，比急着立威更能稳住人心。"],"tags":["冯跋","北燕","吏治"]},"zhuyan_fengba_zhi":{"intro":"本段收了冯跋的两道民政诏令与一件外交处置：令百姓种桑柘、禁厚葬，扣留魏使耿贰。前两者是农桑与节俭，后者暴露北燕与北魏的关系。读时可以对照：诏令讲给内部听，外交处理反映处境。","focus":["第一道诏书出发于实际观察：“今疆宇无虞，百姓宁业，而田亩荒秽，有司不随时督察，欲令家给人足，不亦难乎！”接着给出指标：“此土少桑，人未见其利，可令百姓人殖桑一百根，柘二十根。”不是空讲农本，而是给每人定数量，且承认“人未见其利”，说明要靠行政推动。","第二道诏书讲薄葬：“人之亡也，精魂上归于天，骨肉下归于地，朝终夕坏……衣以锦绣，服以罗纨，宁有知哉！”论证先破厚葬的前提，再讲“有损于生”，最后以“祖考因旧立庙，皆不改营陵寝”作示范。把这一条与前一单元慕容熙为苻氏大修陵墓对照，北燕的取向与后燕相反。","魏使一段很微妙：耿贰“忿而不谢”，申秀说“不可容也”，冯懿又“盛称贰之陵傲以激跋”，跋却说“亦各其志也。匹夫尚不可屈，况一方之主乎”，但最后“请幽而降之，跋乃留贰不遣”。他理解对方的立场，却仍扣留使者，这个动作让之后“聘使断绝”的局面更难收拾。"],"notes":[["疆宇无虞","疆土无忧"],["家给人足","家家富足"],["桑柘","桑树与柘树，养蚕之用"],["送终","办丧事"],["棺椁","棺材与外棺"],["罗纨","丝织品"],["陵寝","陵墓与寝庙"],["耿贰","北魏使者"],["黄门郎","皇帝近侍官"],["骄蹇","傲慢"],["倾佞","奸邪谄媚"],["幽","拘禁"]],"think":["冯跋说“匹夫尚不可屈，况一方之主乎”，却仍扣留魏使，前后是否矛盾？","这是理解与利益的分离：他能理解对方不屈，但国家的体面与安全需要有一个表示。扣留使者对内是姿态，对外却无法转圜，也是后来魏军压境的伏笔。在内外压力下，个人的“通达”往往让位于集体的“颜面”。"],"quiz":[["诏令规定每人种桑与柘各多少？",["桑一百根、柘二十根","桑二十根、柘一百根","各五十根"],"原文“人殖桑一百根，柘二十根”。"],["薄葬诏的理由是？",["厚葬对死者无益，有损于生者","国库空虚","先王遗命"],"原文“厚于送终，贵而改葬，皆无益亡者，有损于生”。"],["冯跋对魏使的最后处置是？",["留贰不遣","礼送回国","处死"],"原文“跋乃留贰不遣”。"]],"cards":[["冯跋为何劝种桑柘？","此土少桑，人未见其利。"],["魏使是谁？","耿贰。"]],"line":["厚于送终，贵而改葬，皆无益亡者，有损于生","红白之事讲排场，往往只是活人的负担：省下的钱，对生者更有用。"],"tags":["冯跋","北燕","民政"]},"zhuyan_sufu":{"intro":"本单元两段：前一段写冯素弗，北燕的“宰衡”，谦恭、俭约、存亡继绝；后一段写魏军大至与北燕收尾，包括冯弘杀兄子自立、东奔高句丽被杀。读这篇要同时看两层：一位辅臣的品格，一个王朝的结局，并注意末尾年代算法的疑点。","focus":["素弗的写法全靠细节。“虽冢养之贱，皆与之抗礼”，连奴仆都按礼相待；“车服屋宇，务于俭约”；对曾不顾他的韩业，他说“既往之事，岂复与君计之”，“待业弥厚”；又好“存亡继绝，申拔旧门”，问阳哲前朝勋臣子弟何在，召桃豹之孙为左常侍。“论者归其有宰衡之度”是众口评价。","后一段是预警与失败：赤气四塞，太史令张穆劝“宜还前使，修和结盟”，“违义怒邻，取亡之道”，跋只说“吾当思之”。魏军随后大至，姚昭、皇甫轨距战，“轨中流矢死”，魏“以有备，引还”。与上一单元留魏使对读，可看出这条外交路线的后果。","收尾处有存疑。“跋立十一年，至是，元熙元年也”，后文又说“至元嘉七年死”，“弟弘杀跋子翼自立，后为魏所伐，东奔高句丽。居二年，高句丽杀之”，最后“始，跋以孝武太元二十年僭号，至弘二世，凡二十有八载”。起算年与上一单元同样不合；北燕始年又有407年（云建国）与409年（跋称天王）两说，二十八载的算法存疑。"],"notes":[["京尹","京城行政长官"],["营丘","地名，在今山东一带，素弗曾镇守"],["冢养","家中奴仆"],["抗礼","以平等之礼相待"],["存亡继绝","使灭亡的延续、断绝的继续"],["宰衡","宰辅之职，喻总揽朝政的大臣"],["太史令","掌天文历法之官"],["赤气","红色气，古人视为兵象"],["聘使","出使的使节"],["流矢","乱飞的箭"],["元熙","东晋恭帝年号"],["元嘉","南朝宋文帝年号"]],"think":["史家为什么把素弗的品德与魏军的压境放在同一单元里？","对照的作用：一个重礼、节俭、肯为旧人说话的辅臣，对应的是一个对外骄蹇、对邻不让的朝廷。素弗在内部稳住了秩序，却改变不了外交与军事处境。传文末尾紧接冯弘杀侄自立，说明一人之贤不能代替制度，辅臣一去，继承问题就暴露了。"],"quiz":[["太史令张穆劝跋做什么？",["还前使，修和结盟","出兵伐魏","迁都"],"原文“宜还前使，修和结盟”。"],["弘最终下场是？",["东奔高句丽，被杀","降魏封侯","病死"],"原文“东奔高句丽。居二年，高句丽杀之”。"],["素弗被称有什么气度？",["宰衡之度","帝王之度","将帅之度"],"原文“论者归其有宰衡之度”。"]],"cards":[["素弗待奴仆如何？","皆与之抗礼。"],["谁杀跋子翼自立？","弟弘。"]],"line":["既往之事，岂复与君计之","对曾经得罪过自己的人，先把旧账放下：这样人才愿意回头用力。"],"tags":["冯素弗","北燕","兴亡"]}});
